function SeparateNumbers(numbers: array of integer): (array of integer, array of integer);
begin
  var evenNumbers := numbers.Where(x -> x mod 2 = 0).ToArray;
  var oddNumbers := numbers.Where(x -> x mod 2 <> 0).ToArray;
  Result := (evenNumbers, oddNumbers);
end;

function SumCommonElements(arr1, arr2: array of integer): integer;
begin
