end;

function NthNonprime(n: integer): integer;
begin
  var nonPrimes := new List<integer>;
  nonPrimes.Add(1);
  var primeCounter := 2;

  while nonPrimes.Count < n do
  begin
    primeCounter += 1;
    var isPrime := True;

    for var num := 2 to Trunc(Sqrt(primeCounter)) do
      if primeCounter mod num = 0 then
      begin
        isPrime := False;
        break;
      end;

    if not isPrime then
      nonPrimes.Add(primeCounter);
  end;

  Result := nonPrimes.Last;
end;

