function IsAnagramPalindrome(s: string): boolean;
begin
  var charCount := new Dictionary<char, integer>;

  foreach var ch in s do
    if charCount.ContainsKey(ch) then
      charCount[ch] += 1
    else
      charCount[ch] := 1;

  var oddCounts := 0;
  foreach var count in charCount.Values do
    if count mod 2 <> 0 then
      oddCounts += 1;

  Result := oddCounts <= 1;
end;

