function GeneratePascal(n: integer): array of array of integer;
begin
  var output := new List<array of integer>;
  output.Add([1]);

  for var row := 1 to n - 1 do
  begin
    var tempRow := new List<integer>;
    tempRow.Add(1);

    for var i := 1 to row - 1 do
      tempRow.Add(output.Last[i] + output.Last[i-1]);

    tempRow.Add(1);
    output.Add(tempRow.ToArray);
  end;

  Result := output.ToArray;
end;

function MaxWaterContainer(height: array of integer): integer;
begin
  var maxWater := 0;
  var containerLeft := 0;
  var containerRight := height.Length - 1;

  while containerLeft < containerRight do
  begin
    var currentWater := Min(height[containerLeft], height[containerRight]) * 
                        (containerRight - containerLeft);
    maxWater := Max(maxWater, currentWater);

    if height[containerLeft] < height[containerRight] then
      containerLeft += 1
    else
      containerRight -= 1;
  end;

  Result := maxWater;
end;

