function MinimumWindowSubstring(s, t: string): string;
begin
  if (t = '') or (s = '') then
  begin
    Result := '';
    exit;
  end;

  var dictT := new Dictionary<char, integer>;
  foreach var ch in t do
    if dictT.ContainsKey(ch) then
      dictT[ch] += 1
    else
      dictT[ch] := 1;

  var required := dictT.Count;
  var left := 0;
  var right := 0;
  var formed := 0;
  var windowCounts := new Dictionary<char, integer>;
  var ans := (integer.MaxValue, 0, 0);

  while right < s.Length do
  begin
    var character := s[right];

    if windowCounts.ContainsKey(character) then
      windowCounts[character] += 1
    else
      windowCounts[character] := 1;

    if dictT.ContainsKey(character) and (windowCounts[character] = dictT[character]) then
      formed += 1;

    while (left <= right) and (formed = required) do
    begin
      var leftChar := s[left];

      if right - left + 1 < ans[0] then
        ans := (right - left + 1, left, right);

      windowCounts[leftChar] -= 1;

      if dictT.ContainsKey(leftChar) and (windowCounts[leftChar] < dictT[leftChar]) then
        formed -= 1;

      left += 1;
    end;

    right += 1;
  end;

  if ans[0] = integer.MaxValue then
    Result := ''
  else
    Result := s.Substring(ans[1], ans[0]);
end;

function MinDeletionsToAnagram(str1, str2: string): integer;
begin
  var count1 := new Dictionary<char, integer>;
  var count2 := new Dictionary<char, integer>;

  foreach var ch in str1 do
    if count1.ContainsKey(ch) then
      count1[ch] += 1
    else
      count1[ch] := 1;

  foreach var ch in str2 do
    if count2.ContainsKey(ch) then
      count2[ch] += 1
    else
      count2[ch] := 1;

  var deletions := 0;
  var allChars := new HashSet<char>(count1.Keys);
  allChars.UnionWith(count2.Keys);

  foreach var ch in allChars do
  begin
    var val1 := count1.Get(ch);
    var val2 := count2.Get(ch);
    deletions += Abs(val1 - val2);
  end;

  Result := deletions;
end;

function CountUniquePaths(grid: array[,] of integer): integer;
begin
  var m := grid.GetLength(0);
  var n := grid.GetLength(1);

  if (grid[0,0] = 1) or (grid[m-1,n-1] = 1) then
  begin
    Result := 0;
    exit;
  end;

  var dp := new integer[m, n];
  dp[0,0] := 1;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i,j] = 1 then
        dp[i,j] := 0
      else
      begin
        if i > 0 then
          dp[i,j] += dp[i-1,j];
        if j > 0 then
          dp[i,j] += dp[i,j-1];
      end;

  Result := dp[m-1,n-1];
end;

