function PostOrderTraversal(tree: array of integer): array of integer;
begin
  if tree.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var stack := new Stack<integer>;
  stack.Push(0);
  var resultList := new List<integer>;

  while stack.Count > 0 do
  begin
    var index := stack.Pop;
    resultList.Add(tree[index]);

    var leftIndex := 2 * index + 1;
    var rightIndex := 2 * index + 2;

    if leftIndex < tree.Length then
      stack.Push(leftIndex);
    if rightIndex < tree.Length then
      stack.Push(rightIndex);
  end;

  resultList.Reverse;
  Result := resultList.ToArray;
end;

