function KTimesRepeatDeletion(s: string; k: integer): string;
begin
  var stack := new Stack<Tuple<char, integer>>;

  foreach var ch in s do
  begin
    if (stack.Count > 0) and (stack.Peek.Item1 = ch) then
    begin
      var (char_, cnt) := stack.Pop;
      cnt += 1;
      if cnt < k then
        stack.Push(Tuple.Create(char_, cnt));
    end
    else
      stack.Push(Tuple.Create(ch, 1));
  end;

  var sb := new StringBuilder;
  var reversed := stack.Reverse.ToArray;

  foreach var item in reversed do
    for var i := 1 to item.Item2 do
      sb.Append(item.Item1);

  Result := sb.ToString;
end;

function LeastBricks(wall: array of array of integer): integer;
begin
  var rowCount := wall.Length;
  var bricksEndingPoints := new Dictionary<integer, integer>;
  var maxFreq := 0;

  foreach var bricks in wall do
  begin
    var endPoint := 0;
    for var i := 0 to bricks.Length - 2 do
    begin
      endPoint += bricks[i];

      if bricksEndingPoints.ContainsKey(endPoint) then
        bricksEndingPoints[endPoint] += 1
      else
        bricksEndingPoints[endPoint] := 1;

      maxFreq := Max(maxFreq, bricksEndingPoints[endPoint]);
    end;
  end;

  Result := rowCount - maxFreq;
end;

