function SumAndLength(n: integer): (integer, integer);
begin
  var sum := 0;
  var length := 0;
  var num := n;

  while num > 0 do
  begin
    var digit := num mod 10;
    sum += digit;
    length += 1;
    num := num div 10;
  end;

  Result := (sum, length);
