type
  TreeNode = auto class
    val: integer;
    left: TreeNode;
    right: TreeNode;
  end;

function AreSiblings(root: TreeNode; x, y: integer): boolean;
begin
  if root = nil then
  begin
    Result := False;
    exit;
  end;

  if (root.left <> nil) and (root.right <> nil) and
     (((root.left.val = x) and (root.right.val = y)) or
      ((root.left.val = y) and (root.right.val = x))) then
  begin
    Result := True;
    exit;
  end;

  Result := AreSiblings(root.left, x, y) or AreSiblings(root.right, x, y);
end;

