function FindMedianSortedArrays(nums1, nums2: array of integer): real;
begin
  var combined := nums1 + nums2;
  combined.Sort;
  var length := combined.Length;

  if length mod 2 = 0 then
    Result := (combined[length div 2 - 1] + combined[length div 2]) / 2
  else
    Result := combined[length div 2];
end;

function InterleaveStrings(str1, str2: string): string;
begin
  var sb := new StringBuilder;
  var i := 1;
  var j := 1;

  while (i <= str1.Length) and (j <= str2.Length) do
  begin
    sb.Append(str1[i]);
    sb.Append(str2[j]);
    i += 1;
    j += 1;
  end;

  if i <= str1.Length then
    sb.Append(str1.Substring(i-1));

  if j <= str2.Length then
    sb.Append(str2.Substring(j-1));

  Result := sb.ToString;
end;

