function DecToBinary(decimalNumber: integer): string;
begin
  if decimalNumber = 0 then
  begin
    Result := '0';
    exit;
  end;

  var binaryDigits := new List<string>;
  var num := decimalNumber;

  while num > 0 do
  begin
    binaryDigits.Add((num mod 2).ToString);
    num := num div 2;
  end;

  binaryDigits.Reverse;
  Result := string.Join('', binaryDigits);
end;

function IsDecimal(s: string): boolean;
begin
  var trimmed := s.Trim;

  try
    var lowerCase := trimmed.ToLower;
    if lowerCase.Contains('e') then
    begin
      var ePos := lowerCase.IndexOf('e');
      if (ePos = 0) or (ePos = lowerCase.Length - 1) then
      begin
        Result := False;
        exit;
      end;

      var mantissa := lowerCase.Substring(0, ePos);
      var exponent := lowerCase.Substring(ePos + 1);

      Convert.ToDouble(mantissa);
      Convert.ToInt64(exponent);
    end
    else
      Convert.ToDouble(trimmed);

    Result := True;
  except
    Result := False;
  end;
end;

function StringRotation(A, B: string): integer;
begin
  if A = B then
  begin
    Result := 0;
    exit;
  end;

  var len := A.Length;
  if len <> B.Length then
  begin
    Result := -1;
    exit;
  end;

  for var i := 1 to len do
  begin
    var rotated := A.Substring(i) + A.Substring(0, i);
    if rotated = B then
    begin
      Result := i;
      exit;
    end;
  end;

  Result := -1;
end;

function MaxProductThreeNumbers(arr: array of integer): integer;
begin
  var sorted := arr.ToArray;
  sorted.Sort;
  var n := sorted.Length;

  var product1 := sorted[0] * sorted[1] * sorted[n-1];
  var product2 := sorted[n-1] * sorted[n-2] * sorted[n-3];

  Result := Max(product1, product2);
end;

function OddEvenSort(array_: array of integer): array of integer;
begin
  var arr := array_.ToArray;
  var n := arr.Length;
  var sorted := False;

  while not sorted do
  begin
    sorted := True;

    // Perform even indexed comparison and swap
    for var i := 0 to n - 2 step 2 do
      if arr[i] > arr[i+1] then
      begin
        Swap(arr[i], arr[i+1]);
        sorted := False;
      end;

    // Perform odd indexed comparison and swap
    for var i := 1 to n - 2 step 2 do
      if arr[i] > arr[i+1] then
      begin
        Swap(arr[i], arr[i+1]);
        sorted := False;
      end;
  end;

  Result := arr;
end;

