function MaxRepeated(s: string): integer;
begin
  if s.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var maxLen := 1;
  var currentLen := 1;

  for var i := 2 to s.Length do
  begin
    if s[i] = s[i-1] then
    begin
      currentLen += 1;
      maxLen := Max(maxLen, currentLen);
    end
    else
      currentLen := 1;
  end;

  Result := maxLen;
end;

function LongestRepeatedSeq(str1, str2: string): string;
begin
  var len1 := MaxRepeated(str1);
  var len2 := MaxRepeated(str2);

  if len1 > len2 then
    Result := str1
  else if len1 < len2 then
    Result := str2
  else
    Result := Min(str1, str2);
end;

