function PerfectSquareUnique(nums: array of integer): array of integer;
begin
  var seen := new HashSet<integer>;
  var uniqueNums := new List<integer>;

  foreach var num in nums do
  begin
    if (not seen.Contains(num)) and (Sqrt(num) = Floor(Sqrt(num))) then
    begin
      uniqueNums.Add(num);
      seen.Add(num);
    end;
  end;

  Result := uniqueNums.ToArray;
end;

function MinAvgOperations(nums: array of integer): integer;
begin
  if nums.All(x -> x = nums[0]) then
  begin
    Result := 0;
    exit;
  end;

  var sorted := nums.ToArray;
  sorted.Sort;

  var avg := nums.Average;
  var operations := 0;

  foreach var num in sorted do
    if num < avg then
      operations += 1
    else
      break;

  if operations * 2 < nums.Length then
    Result := operations * 2
  else
    Result := -1;
end;

function HappyNum(n: integer): boolean;
begin
  var visited := new HashSet<integer>;
  var num := n;

  while num <> 1 do
  begin
    var sum := 0;
    var temp := num;

    while temp > 0 do
    begin
      var digit := temp mod 10;
      sum := sum + digit * digit;
      temp := temp div 10;
    end;

    if visited.Contains(sum) then
    begin
      Result := False;
      exit;
    end;

    visited.Add(sum);
    num := sum;
  end;

  Result := num = 1;
end;

function FindLongestConsecutive(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var numSet := new HashSet<integer>(nums);
  var longestStreak := 0;

  foreach var num in numSet do
  begin
    if not numSet.Contains(num - 1) then
    begin
      var currentNum := num;
      var currentStreak := 1;

      while numSet.Contains(currentNum + 1) do
      begin
        currentNum += 1;
        currentStreak += 1;
      end;

      longestStreak := Max(longestStreak, currentStreak);
    end;
  end;

  Result := longestStreak;
end;

function AverageExceptExtremes(nums: array of integer): real;
begin
  if nums.Length <= 2 then
    raise new System.ArgumentException('Array must contain at least 3 elements.');

  var sorted := nums.ToArray;
  sorted.Sort;

  var sum := 0.0;
  for var i := 1 to sorted.Length - 2 do
    sum += sorted[i];

  Result := sum / (sorted.Length - 2);
end;

function HasContinuousSubarray(nums: array of integer; target: integer): boolean;
begin
  var sumTable := new Dictionary<integer, integer>;
  sumTable[0] := -1;
  var sum := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    sum += nums[i];
    if sumTable.ContainsKey(sum - target) then
    begin
      Result := True;
      exit;
    end;
    sumTable[sum] := i;
  end;

  Result := False;
end;

