  for var i := 1 to s.Length do
  begin
    // Odd length palindromes
    totalCount += ExpandAroundCenter(s, i, i);
    // Even length palindromes
    if i < s.Length then
      totalCount += ExpandAroundCenter(s, i, i + 1);
  end;

  Result := totalCount;
end;

function SubarrayCount(nums: array of integer; k: integer): integer;
begin
  var sumTillI := 0;
  var cnt := 0;
  var hashMap := new Dictionary<integer, integer>;
  hashMap[0] := 1;

  for var i := 0 to nums.Length - 1 do
  begin
    sumTillI += nums[i];
    var need := sumTillI - k;

    if hashMap.ContainsKey(need) then
      cnt += hashMap[need];

    if hashMap.ContainsKey(sumTillI) then
      hashMap[sumTillI] += 1
    else
      hashMap[sumTillI] := 1;
  end;

  Result := cnt;
end;

function LongestArithmetic(nums: array of integer): integer;
begin
  if nums.Length < 2 then
  begin
    Result := nums.Length;
    exit;
  end;

  var dp := new Dictionary<integer, integer>[nums.Length];
  for var i := 0 to dp.Length - 1 do
    dp[i] := new Dictionary<integer, integer>;

  var maxLen := 1;

  for var i := 0 to nums.Length - 1 do
    for var j := 0 to i - 1 do
    begin
      var diff := nums[i] - nums[j];

      if dp[j].ContainsKey(diff) then
        dp[i][diff] := dp[j][diff] + 1
      else
        dp[i][diff] := 2;

      maxLen := Max(maxLen, dp[i][diff]);
    end;

  Result := maxLen;
end;

function LongestCommonSubarray(nums1, nums2: array of integer): integer;
begin
  var len1 := nums1.Length;
  var len2 := nums2.Length;
  var res := 0;

  var dp := new integer[len1 + 1, len2 + 1];

  for var i := 1 to len1 do
    for var j := 1 to len2 do
      if nums1[i-1] = nums2[j-1] then
      begin
        dp[i,j] := dp[i-1, j-1] + 1;
        res := Max(res, dp[i,j]);
      end;

  Result := res;
end;

