function MinElementsToDelete(arr: array of integer; k: integer): integer;
begin
  var sorted := arr.ToArray;
  sorted.Sort;

  var total := sorted.Sum;

  if total <= k then
  begin
    Result := 0;
    exit;
  end;

  var diff := total - k;
  var count := 0;

  foreach var num in sorted do
  begin
    if diff >= num then
    begin
      diff -= num;
      count += 1;
    end
    else
      break;
  end;

  Result := count;
end;

