var combResult: List<array of integer>;
    combNums: array of integer;
    combK: integer;

procedure DfsComb(index: integer; path: List<integer>);
begin
  if path.Count = combK then
  begin
    combResult.Add(path.ToArray);
    exit;
  end;

  for var i := index to combNums.Length - 1 do
  begin
    path.Add(combNums[i]);
    DfsComb(i + 1, path);
    path.RemoveAt(path.Count - 1);
  end;
end;

