  for var i := 0 to lst.Length - 1 step k do
  begin
    var size := Min(k, lst.Length - i);
    var group := new integer[size];

    for var j := 0 to size - 1 do
      group[j] := lst[i + j];

    groups.Add(group);
  end;

  Result := groups.ToArray;
end;

function SubstringRepeats(source, target: string): integer;
begin
  var sourceChars := source.ToHashSet;

  foreach var ch in target do
    if not sourceChars.Contains(ch) then
    begin
