      exit;
    end;

  var cnt := 0;
  var idx := 1;
  var repeated := '';

  while idx <= target.Length do
  begin
    cnt += 1;
    repeated := repeated + source;

    if repeated.Contains(target) then
    begin
      Result := cnt;
      exit;
    end;

    if cnt > 100 then // Prevent infinite loop
    begin
      Result := -1;
      exit;
    end;
  end;

  Result := -1;
end;

