function SequenceReconstruction(org: array of integer; seqs: array of array of integer): boolean;
begin
  var dst := new Dictionary<integer, HashSet<integer>>;
  var src := new Dictionary<integer, HashSet<integer>>;
  var nodes := new HashSet<integer>;

  foreach var seq in seqs do
  begin
    foreach var node in seq do
      nodes.Add(node);

    for var i := 0 to seq.Length - 2 do
    begin
      if not dst.ContainsKey(seq[i]) then
        dst[seq[i]] := new HashSet<integer>;
      dst[seq[i]].Add(seq[i+1]);

      if not src.ContainsKey(seq[i+1]) then
        src[seq[i+1]] := new HashSet<integer>;
      src[seq[i+1]].Add(seq[i]);
    end;
  end;

  if nodes.Count <> org.Length then
  begin
    Result := False;
    exit;
  end;

  var q := new Queue<integer>;
  foreach var node in nodes do
    if not src.ContainsKey(node) then
      q.Enqueue(node);

  var path := new List<integer>;

  while q.Count = 1 do
  begin
    var node := q.Dequeue;
    path.Add(node);

    if dst.ContainsKey(node) then
      foreach var nei in dst[node] do
      begin
        src[nei].Remove(node);
        if src[nei].Count = 0 then
          q.Enqueue(nei);
      end;
  end;

  Result := path.SequenceEqual(org);
end;

function CutRod(price: array of integer; n: integer): integer;
begin
  var length := new integer[n];
  for var i := 1 to n do
    length[i-1] := i;

  var dp := new integer[n+1, n+1];

  for var i := 1 to n do
    for var j := 1 to n do
      if j >= length[i-1] then
        dp[i,j] := Max(price[i-1] + dp[i, j - length[i-1]], dp[i-1, j])
      else
        dp[i,j] := dp[i-1, j];

  Result := dp[n, n];
end;

function NumWaysToExpress(n: integer): integer;
begin
  var count := 0;
  var i := 1;

  while i * (i - 1) div 2 < n do
  begin
    if (n - i * (i - 1) div 2) mod i = 0 then
      count += 1;
    i += 1;
  end;

  Result := count;
end;

