function InsertNode(root: TreeNode; value: integer; var res: array of integer; resultIndex: integer): TreeNode;
begin
  if root = nil then
    Result := new TreeNode(value)
  else if value <= root.value then
  begin
    root.count += 1;
    root.left := InsertNode(root.left, value, res, resultIndex);
    Result := root;
  end
  else
  begin
    res[resultIndex] += root.count + 1;
    root.right := InsertNode(root.right, value, res, resultIndex);
    Result := root;
  end;
end;

