function CanSplit(nums: array of integer): boolean;
begin
  var count := new Dictionary<integer, integer>;
  var tail := new Dictionary<integer, integer>;

  foreach var n in nums do
    if count.ContainsKey(n) then
      count[n] += 1
    else
      count[n] := 1;

  foreach var n in nums do
  begin
    if count[n] = 0 then
      continue;

    if tail.ContainsKey(n-1) and (tail[n-1] > 0) then
    begin
      tail[n-1] -= 1;
      if tail.ContainsKey(n) then
        tail[n] += 1
      else
        tail[n] := 1;
    end
    else if (count.Get(n+1, 0) > 0) and (count.Get(n+2, 0) > 0) then
    begin
      count[n+1] -= 1;
      count[n+2] -= 1;
      if tail.ContainsKey(n+2) then
        tail[n+2] += 1
      else
        tail[n+2] := 1;
    end
    else
    begin
      Result := False;
      exit;
    end;

    count[n] -= 1;
  end;

  Result := True;
end;

