begin
  var res: int64 := 0;
  var multiplier: int64 := 1;

  for var i := intArray.Length - 1 downto 0 do
  begin
    res := res + intArray[i] * multiplier;
    var digits := intArray[i].ToString.Length;
    for var j := 1 to digits do
      multiplier *= 10;
  end;

