end;

function MaxNumKSumPairs(nums: array of integer; k: integer): integer;
begin
  var sorted := nums.ToArray;
  sorted.Sort;
  var numsCount := new Dictionary<integer, integer>;

  foreach var num in sorted do
    if numsCount.ContainsKey(num) then
      numsCount[num] += 1
    else
      numsCount[num] := 1;

  var maxOps := 0;

  foreach var key in numsCount.Keys.ToArray do
  begin
    if numsCount.ContainsKey(key) and numsCount.ContainsKey(k - key) then
    begin
      if key = k - key then
      begin
        maxOps += numsCount[key] div 2;
        numsCount[key] := 0;
        continue;
      end;

      maxOps += Min(numsCount[key], numsCount[k - key]);
      numsCount[key] := 0;
      numsCount[k - key] := 0;
    end;
  end;

  Result := maxOps;
end;

