  var t := new Dictionary<integer, integer>;

  for var i := 1 to N do
    t[i] := 0;

  foreach var (a, b) in trust do
  begin
    t[b] := t.Get(b) + 1;
    t[a] := t.Get(a) - 1;
  end;

  for var i := 1 to N do
    if t[i] = N - 1 then
    begin
      Result := i;
      exit;
    end;

  Result := -1;
end;

function MinDistinctSubstring(s: string): integer;
begin
  var charSet := new HashSet<char>(s.ToCharArray);
  var count := charSet.Count;
  var start := 1;
  var minLen := s.Length;
  var distinct := 0;
  var freq := new integer[256];

  for var i := 1 to s.Length do
  begin
    freq[Ord(s[i])] += 1;
    if freq[Ord(s[i])] = 1 then
      distinct += 1;

    if distinct = count then
    begin
      while freq[Ord(s[start])] > 1 do
      begin
        freq[Ord(s[start])] -= 1;
        start += 1;
      end;

      var lenWindow := i - start + 1;
      if minLen > lenWindow then
        minLen := lenWindow;
    end;
  end;

  Result := minLen;
end;

