function FindLongestBalancedParenthesis(s: string): integer;
begin
  var stack := new Stack<integer>;
  var maxLength := 0;
  var start := 0;

  for var i := 1 to s.Length do
  begin
    if s[i] = '(' then
      stack.Push(i)
    else
    begin
      if stack.Count = 0 then
        start := i
      else
      begin
        stack.Pop;
        if stack.Count = 0 then
          maxLength := Max(maxLength, i - start)
        else
          maxLength := Max(maxLength, i - stack.Peek);
      end;
    end;
  end;

  Result := maxLength;
end;

function LongestSubstringWithTwoDistinct(s: string): integer;
begin
  var left := 1;
  var maxLen := 0;
  var charMap := new Dictionary<char, integer>;

  for var right := 1 to s.Length do
  begin
    if charMap.ContainsKey(s[right]) then
      charMap[s[right]] += 1
    else
      charMap[s[right]] := 1;

    if charMap.Count > 2 then
    begin
      while charMap.Count > 2 do
      begin
        charMap[s[left]] -= 1;
        if charMap[s[left]] = 0 then
          charMap.Remove(s[left]);
        left += 1;
      end;
    end;

    maxLen := Max(maxLen, right - left + 1);
  end;

  Result := maxLen;
end;

