function FindPeakElement(nums: array of integer): integer?;
begin
  if nums.Length = 0 then
  begin
    Result := nil;
    exit;
  end;

  var left := 0;
  var right := nums.Length - 1;

  while left < right do
  begin
    var mid := (left + right) div 2;
    if nums[mid] > nums[mid + 1] then
      right := mid
    else
      left := mid + 1;
  end;

  Result := nums[left];
end;

