function WordFormation(text, word: string): integer;
begin
  var charCount := new Dictionary<char, integer>;
  var wordCount := new Dictionary<char, integer>;

  foreach var ch in word do
    if wordCount.ContainsKey(ch) then
      wordCount[ch] += 1
    else
      wordCount[ch] := 1;

  foreach var ch in text do
    if wordCount.ContainsKey(ch) then
      if charCount.ContainsKey(ch) then
        charCount[ch] += 1
      else
        charCount[ch] := 1;

  var minCount := integer.MaxValue;

  foreach var kv in wordCount do
  begin
    var available := charCount.Get(kv.Key, 0);
    var needed := kv.Value;

    if available < needed then
    begin
      Result := 0;
      exit;
    end;

    minCount := Min(minCount, available div needed);
  end;

  Result := minCount;
end;

