function MaxProductSubarray(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var n := nums.Length;
  var maxDP := new integer[n];
  var minDP := new integer[n];

  maxDP[0] := nums[0];
  minDP[0] := nums[0];

  for var i := 1 to n - 1 do
  begin
    maxDP[i] := Max(nums[i], Max(maxDP[i-1] * nums[i], minDP[i-1] * nums[i]));
    minDP[i] := Min(nums[i], Min(maxDP[i-1] * nums[i], minDP[i-1] * nums[i]));
  end;

  Result := maxDP.Max;
end;

