function MergeSortedLists(list1, list2: ListNode): ListNode;
begin
  var dummy := new ListNode(0, nil);
  var current := dummy;
  var l1 := list1;
  var l2 := list2;

  while (l1 <> nil) and (l2 <> nil) do
  begin
    if l1.val < l2.val then
    begin
      current.next := l1;
      l1 := l1.next;
    end
    else
    begin
      current.next := l2;
      l2 := l2.next;
    end;
    current := current.next;
  end;

  if l1 <> nil then
    current.next := l1
  else
    current.next := l2;

  Result := dummy.next;
end;

