function CreateLinkedList(values: array of integer): ListNode;
begin
  if values.Length = 0 then
  begin
    Result := nil;
    exit;
  end;

  var head := new ListNode(values[0], nil);
  var current := head;

  for var i := 1 to values.Length - 1 do
  begin
    current.next := new ListNode(values[i], nil);
    current := current.next;
  end;

  Result := head;
end;

// Helper function to convert a linked list to an array of values
function ConvertLinkedListToList(linkedList: ListNode): array of integer;
begin
  var values := new List<integer>;
  var current := linkedList;

  while current <> nil do
  begin
    values.Add(current.val);
    current := current.next;
  end;

  Result := values.ToArray;
end;

