function CheckBalancedBrackets(s: string): boolean;
begin
  var stack := new Stack<char>;
  var bracketMap := new Dictionary<char, char>;
  bracketMap.Add(')', '(');
  bracketMap.Add('}', '{');
  bracketMap.Add(']', '[');

  for var i := 1 to s.Length do
  begin
    var ch := s[i];

    if (ch = '(') or (ch = '{') or (ch = '[') then
      stack.Push(ch)
    else if bracketMap.ContainsKey(ch) then
    begin
      if (stack.Count = 0) or (bracketMap[ch] <> stack.Pop) then
      begin
        Result := False;
        exit;
      end;
    end;
  end;

  Result := stack.Count = 0;
end;

function StairClimbingWays(n: integer): int64;
begin
  if n <= 1 then
  begin
    Result := 1;
    exit;
  end;

  var first: int64 := 1;
  var second: int64 := 1;

  for var i := 2 to n do
  begin
    var third := first + second;
    first := second;
    second := third;
  end;

  Result := second;
end;

function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
  begin
    Result := False;
    exit;
  end;

  if n <= 3 then
  begin
    Result := True;
    exit;
  end;

  if (n mod 2 = 0) or (n mod 3 = 0) then
  begin
    Result := False;
    exit;
  end;

  var i := 5;
  while i * i <= n do
  begin
    if (n mod i = 0) or (n mod (i + 2) = 0) then
    begin
      Result := False;
      exit;
    end;
    i += 6;
  end;

  Result := True;
end;

