end;

function MinimumCoins(coins: array of integer; amount: integer): integer;
begin
  var dp := new integer[amount + 1];

  for var i := 1 to amount do
    dp[i] := integer.MaxValue;

  dp[0] := 0;

  for var i := 1 to amount do
    foreach var coin in coins do
      if i >= coin then
        if dp[i - coin] <> integer.MaxValue then
          dp[i] := Min(dp[i], dp[i - coin] + 1);

  if dp[amount] = integer.MaxValue then
    Result := -1
  else
    Result := dp[amount];
end;

