var wordSet: HashSet<string>;
var memo: Dictionary<string, boolean>;

function Dfs(word: string): boolean;
begin
  if memo.ContainsKey(word) then
  begin
    Result := memo[word];
    exit;
  end;

  memo[word] := False;

  for var i := 1 to word.Length - 1 do
  begin
    var prefix := word.Substring(0, i);
    var suffix := word.Substring(i);

    if wordSet.Contains(prefix) and wordSet.Contains(suffix) then
    begin
      memo[word] := True;
      break;
    end
    else if wordSet.Contains(prefix) and Dfs(suffix) then
    begin
      memo[word] := True;
      break;
    end;
  end;

  Result := memo[word];
end;

