    if Dfs(word) then
      output.Add(word);

  Result := output.ToArray;
end;

function RomanToDecimal(roman: string): integer;
begin
  var romanValues := new Dictionary<char, integer>;
  romanValues.Add('I', 1);
  romanValues.Add('V', 5);
  romanValues.Add('X', 10);
  romanValues.Add('L', 50);
  romanValues.Add('C', 100);
  romanValues.Add('D', 500);
  romanValues.Add('M', 1000);

  var decimal_ := 0;

  for var i := 1 to roman.Length do
  begin
    if (i > 1) and (romanValues[roman[i]] > romanValues[roman[i-1]]) then
      decimal_ := decimal_ + romanValues[roman[i]] - 2 * romanValues[roman[i-1]]
    else
      decimal_ := decimal_ + romanValues[roman[i]];
  end;

  Result := decimal_;
end;

