function SubsequenceCount(s, sub: string): integer;
begin
  var dp := new integer[s.Length + 1, sub.Length + 1];

  for var i := 0 to s.Length do
    dp[i, 0] := 1;

  for var i := 1 to s.Length do
    for var j := 1 to sub.Length do
      if s[i] = sub[j] then
        dp[i, j] := dp[i-1, j-1] + dp[i-1, j]
      else
        dp[i, j] := dp[i-1, j];

  Result := dp[s.Length, sub.Length];
end;

