function FindCeiling(arr: array of integer; target: integer): integer?;
begin
  var left := 0;
  var right := arr.Length - 1;
  var ceiling: integer? := nil;

  while left <= right do
  begin
    var mid := (left + right) div 2;

    if arr[mid] = target then
    begin
      Result := arr[mid];
      exit;
    end
    else if arr[mid] < target then
      left := mid + 1
    else
    begin
      ceiling := arr[mid];
      right := mid - 1;
    end;
  end;

  Result := ceiling;
end;

