function FindRotateIndex(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := -1;
    exit;
  end;

  if nums[0] < nums[nums.Length - 1] then
  begin
    Result := 0;
    exit;
  end;

  var left := 0;
  var right := nums.Length - 1;

  while left <= right do
  begin
    var mid := (left + right) div 2;

    if nums[mid] > nums[mid + 1] then
    begin
      Result := mid + 1;
      exit;
    end
    else if nums[mid] < nums[0] then
      right := mid - 1
    else
      left := mid + 1;
  end;

  Result := 0;
end;

