  var merged := mergedList.OrderBy(x -> x[0]).ThenBy(x -> x[1]).ToList;

  var i := 0;
  while i < merged.Count - 1 do
  begin
    if merged[i][1] >= merged[i+1][1] then
      merged.RemoveAt(i+1)
    else if (merged[i][1] < merged[i+1][1]) and (merged[i][1] >= merged[i+1][0]) then
    begin
      merged[i][1] := merged[i+1][1];
      merged.RemoveAt(i+1);
    end
    else
      i += 1;
  end;

  Result := merged.ToArray;
end;

