function CheckNQueens(board: array of array of integer): boolean;
begin
  var n := board.Length;

  if n = 0 then
  begin
    Result := False;
    exit;
  end;

  // Check rows and columns
  for var i := 0 to n - 1 do
  begin
    var rowSum := 0;
    var colSum := 0;

    for var j := 0 to n - 1 do
    begin
      rowSum += board[i][j];
      colSum += board[j][i];
    end;

    if (rowSum > 1) or (colSum > 1) then
    begin
      Result := False;
      exit;
    end;
  end;

  // Check diagonals
  for var i := -n + 1 to n - 1 do
  begin
    var diagSum1 := 0;
    var diagSum2 := 0;

    for var j := 0 to n - 1 do
    begin
      if (i + j >= 0) and (i + j < n) then
        diagSum1 += board[i + j][j];

      if (j - i >= 0) and (j - i < n) then
        diagSum2 += board[j][j - i];
    end;

    if (diagSum1 > 1) or (diagSum2 > 1) then
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;

function CanSplitArray(arr: array of integer): boolean;
begin
  var totalSum := arr.Sum;

  if totalSum mod 2 <> 0 then
  begin
    Result := False;
    exit;
  end;

  var targetSum := totalSum div 2;
  var n := arr.Length;
  var dp := new boolean[n + 1, targetSum + 1];

  for var i := 0 to n do
    dp[i, 0] := True;

  for var i := 1 to n do
    for var j := 1 to targetSum do
      if j < arr[i-1] then
        dp[i, j] := dp[i-1, j]
      else
        dp[i, j] := dp[i-1, j] or dp[i-1, j - arr[i-1]];

  Result := dp[n, targetSum];
end;

var permResult: List<string>;
    permLst: array of string;

procedure GeneratePerm(current: List<string>; used: HashSet<integer>);
begin
  if current.Count = permLst.Length then
  begin
    permResult.Add(string.Join('', current));
    exit;
  end;

  for var i := 0 to permLst.Length - 1 do
  begin
    if not used.Contains(i) then
    begin
      used.Add(i);
      current.Add(permLst[i]);
      GeneratePerm(current, used);
      current.RemoveAt(current.Count - 1);
      used.Remove(i);
    end;
  end;
end;

