function IsValidBrackets(s: string): boolean;
begin
  var bracketMap := new Dictionary<char, char>;
  bracketMap.Add(')', '(');
  bracketMap.Add(']', '[');
  bracketMap.Add('}', '{');

  var openBrackets := new HashSet<char>('([{'.ToCharArray);
  var stack := new Stack<char>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];

    if openBrackets.Contains(ch) then
      stack.Push(ch)
    else if bracketMap.ContainsKey(ch) then
    begin
      if (stack.Count = 0) or (bracketMap[ch] <> stack.Pop) then
      begin
        Result := False;
        exit;
      end;
    end
    else
    begin
      Result := False;
      exit;
    end;
  end;

  Result := stack.Count = 0;
end;

