function BitwisePower(x, n: integer): int64;
begin
  var res: int64 := 1;
  var baseVal: int64 := x;
  var exp := n;

  while exp > 0 do
  begin
    if (exp and 1) = 1 then
      res := res * baseVal;

    baseVal := baseVal * baseVal;
    exp := exp shr 1;
  end;

  Result := res;
end;

