      targetCount[ch] += 1
    else
      targetCount[ch] := 1;

  foreach var ch in source do
    if sourceCount.ContainsKey(ch) then
      sourceCount[ch] += 1
    else
      sourceCount[ch] := 1;

  foreach var kv in targetCount do
    if not sourceCount.ContainsKey(kv.Key) or (sourceCount[kv.Key] < kv.Value) then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;

