type
  Node = auto class
    val: integer;
    left: Node;
    right: Node;
  end;

function SearchBST(root: Node; key: integer): Node;
begin
  if (root = nil) or (root.val = key) then
  begin
    Result := root;
    exit;
  end;

  if root.val < key then
    Result := SearchBST(root.right, key)
  else
    Result := SearchBST(root.left, key);
end;

