function MergeInterval(intervals: array of array of integer; newInterval: array of integer): array of array of integer;
begin
  var allIntervals := new List<array of integer>;
  allIntervals.AddRange(intervals);
  allIntervals.Add(newInterval);

  var sorted := allIntervals.OrderBy(x -> x[0]).ToList;
  var merged := new List<array of integer>;

  var current := sorted[0];

  for var i := 1 to sorted.Count - 1 do
  begin
    var interval := sorted[i];

    if current[1] >= interval[0] then
    begin
      if interval[1] >= current[1] then
        current[1] := interval[1];
    end
    else
    begin
      merged.Add(current);
      current := interval;
    end;
  end;

  merged.Add(current);
  Result := merged.ToArray;
end;

function MergeSortedArrays(arr1, arr2: array of integer): array of integer;
begin
  var merged := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < arr1.Length) and (j < arr2.Length) do
  begin
    if arr1[i] < arr2[j] then
    begin
      merged.Add(arr1[i]);
      i += 1;
    end
    else
    begin
      merged.Add(arr2[j]);
      j += 1;
    end;
  end;

  while i < arr1.Length do
  begin
    merged.Add(arr1[i]);
    i += 1;
  end;

  while j < arr2.Length do
  begin
    merged.Add(arr2[j]);
    j += 1;
  end;

  Result := merged.ToArray;
end;

