function TimeToMins(val: string): integer;
begin
  var hours := StrToInt(val.Substring(0, 2));
  var mins := StrToInt(val.Substring(3, 2));
  Result := hours * 60 + mins;
end;

function CheckTimeOverlap(interval1, interval2: array of string): boolean;
begin
  var a := TimeToMins(interval1[0]);
  var b := TimeToMins(interval1[1]);
  var c := TimeToMins(interval2[0]);
  var d := TimeToMins(interval2[1]);

  if a > b then
    b += 24 * 60;
  if c > d then
    d += 24 * 60;

  Result := Max(a, c) <= Min(b, d);
end;

