  var current := 1;

  for var i := 1 to rows do
  begin
    var row := new List<integer>;
    for var j := 1 to i do
    begin
      row.Add(current);
      current += 1;
    end;
    triangle.Add(row.ToArray);
  end;

  Result := triangle.ToArray;
end;

