function KadaneAlgorithm(arr: array of integer): integer;
begin
  var maxCurrent := arr[0];
  var maxGlobal := arr[0];

  for var i := 1 to arr.Length - 1 do
  begin
    maxCurrent := Max(arr[i], maxCurrent + arr[i]);
    if maxCurrent > maxGlobal then
      maxGlobal := maxCurrent;
  end;

  Result := maxGlobal;
end;

function IsRotated(str1, str2: string): boolean;
begin
  var n := str1.Length;

  if n <> str2.Length then
  begin
    Result := False;
    exit;
  end;

  // Check if str2 is obtained by rotating str1 to the left by 2 places
  var rotatedLeft := str1.Substring(2) + str1.Substring(0, 2);
  if str2 = rotatedLeft then
  begin
    Result := True;
    exit;
  end;

  // Check if str2 is obtained by rotating str1 to the right by 2 places
  var rotatedRight := str1.Substring(n - 2, 2) + str1.Substring(0, n - 2);
  if str2 = rotatedRight then
  begin
    Result := True;
    exit;
  end;

  Result := False;
end;

