function Intersect(nums1, nums2: array of integer): array of integer;
begin
  var count1 := new Dictionary<integer, integer>;
  var count2 := new Dictionary<integer, integer>;

  foreach var num in nums1 do
    if count1.ContainsKey(num) then
      count1[num] += 1
    else
      count1[num] := 1;

  foreach var num in nums2 do
    if count2.ContainsKey(num) then
      count2[num] += 1
    else
      count2[num] := 1;

  var intersection := new List<integer>;

  foreach var kv in count1 do
    if count2.ContainsKey(kv.Key) then
    begin
      var minCount := Min(kv.Value, count2[kv.Key]);
      for var i := 1 to minCount do
        intersection.Add(kv.Key);
    end;

  Result := intersection.ToArray;
end;

