  if counter.Count = 0 then
  begin
    Result := new char[0];
    exit;
  end;

  var maxCount := counter.Values.Max;
  var frequentChars := new List<char>;

  foreach var kv in counter do
    if kv.Value = maxCount then
      frequentChars.Add(kv.Key);

  Result := frequentChars.ToArray;
end;

