function PostorderTraversal(root: TreeNode): array of integer;
begin
  if root = nil then
  begin
    Result := new integer[0];
    exit;
  end;

  var stack := new Stack<TreeNode>;
  stack.Push(root);
  var values := new List<integer>;

  while stack.Count > 0 do
  begin
    var node := stack.Pop;
    values.Add(node.val);

    if node.left <> nil then
      stack.Push(node.left);
    if node.right <> nil then
      stack.Push(node.right);
  end;

  values.Reverse;
  Result := values.ToArray;
end;

function CountSmallestChar(str1: string): integer;
