  var count := new Dictionary<integer, integer>;

  foreach var num in list1 do
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count[num] := 1;

  foreach var num in list2 do
    if not count.ContainsKey(num) or (count[num] = 0) then
    begin
      Result := num;
      exit;
    end
    else
      count[num] -= 1;

  Result := nil;
end;

function FindMinRotatedArrayWithDuplicates(nums: array of integer): integer;
begin
  var left := 0;
  var right := nums.Length - 1;

  while left < right do
  begin
    var mid := (left + right) div 2;

    if nums[mid] > nums[right] then
      left := mid + 1
    else if nums[mid] < nums[right] then
      right := mid
    else
      right -= 1;
  end;

  Result := nums[left];
end;

