  var dp := new int64[n + 1];
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
    dp[i] := dp[i - 1] + dp[i - 2];

  Result := dp[n];
end;

function PalindromePermutation(str: string): boolean;
begin
  var cleaned := '';

  for var i := 1 to str.Length do
    if Char.IsLetter(str[i]) then
      cleaned += Char.ToLower(str[i]);

  var charCount := new Dictionary<char, integer>;

  for var i := 1 to cleaned.Length do
    if charCount.ContainsKey(cleaned[i]) then
      charCount[cleaned[i]] += 1
    else
      charCount[cleaned[i]] := 1;

  var oddCount := 0;

  foreach var cnt in charCount.Values do
    if cnt mod 2 <> 0 then
    begin
      oddCount += 1;
      if oddCount > 1 then
      begin
        Result := False;
        exit;
      end;
    end;

  Result := True;
end;

function HighestPowerOf2(n: integer): integer;
