    while charSet.Contains(s[j]) do
    begin
      charSet.Remove(s[i]);
      i += 1;
    end;

    charSet.Add(s[j]);
    maxLen := Max(maxLen, j - i + 1);
  end;

  Result := maxLen;
end;

