function IsValidISBN10(isbn: string): boolean;
begin
  if isbn.Length <> 10 then
  begin
    Result := False;
    exit;
  end;

  var sum := 0;

  for var i := 1 to 9 do
  begin
    if not Char.IsDigit(isbn[i]) then
    begin
      Result := False;
      exit;
    end;
    sum += StrToInt(isbn[i].ToString) * i;
  end;

  if Char.IsDigit(isbn[10]) then
    sum += StrToInt(isbn[10].ToString) * 10
  else if isbn[10] = 'X' then
    sum += 10 * 10
  else
  begin
    Result := False;
    exit;
  end;

  Result := sum mod 11 = 0;
end;

function CheckISBN(isbn: string): string;
begin
  if isbn.Length <> 10 then
  begin
    Result := 'No';
    exit;
  end;

  var sum := 0;

  for var i := 1 to 9 do
  begin
    if not Char.IsDigit(isbn[i]) then
    begin
      Result := 'No';
      exit;
    end;
    sum += StrToInt(isbn[i].ToString) * i;
  end;

  if Char.IsDigit(isbn[10]) then
    sum += StrToInt(isbn[10].ToString) * 10
  else if Char.ToUpper(isbn[10]) = 'X' then
    sum += 10 * 10
  else
  begin
    Result := 'No';
    exit;
  end;

  if sum mod 11 = 0 then
    Result := 'Yes'
  else
    Result := 'No';
end;

