function ConvertToRoman(num: integer): string;
begin
  var values := |1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1|;
  var symbols := |'M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I'|;

  var romanNum := new StringBuilder;
  var remaining := num;

  for var i := 0 to values.Length - 1 do
  begin
    while remaining >= values[i] do
    begin
      romanNum.Append(symbols[i]);
      remaining -= values[i];
    end;
  end;

  Result := romanNum.ToString;
end;

function FindNumberIndex(arr: array of integer; num: integer): integer;
begin
  var left := 0;
  var right := arr.Length - 1;
  var idx := -1;

  while left <= right do
  begin
    var mid := left + (right - left) div 2;

    if arr[mid] = num then
    begin
      idx := mid;
      right := mid - 1;
    end
    else if arr[mid] < num then
      left := mid + 1
    else
      right := mid - 1;
  end;

  Result := idx;
end;

