function IsTopologicalOrder(numCourses: integer; prerequisites: array of (integer, integer)): boolean;
begin
  var graph := new Dictionary<integer, List<integer>>;
  var indegree := new integer[numCourses];

  for var i := 0 to numCourses - 1 do
    graph[i] := new List<integer>;

  foreach var (course, prereq) in prerequisites do
  begin
    graph[prereq].Add(course);
    indegree[course] += 1;
  end;

  var queue := new Queue<integer>;
  for var i := 0 to numCourses - 1 do
    if indegree[i] = 0 then
      queue.Enqueue(i);

  var sortedOrder := new List<integer>;

  while queue.Count > 0 do
  begin
    var node := queue.Dequeue;
    sortedOrder.Add(node);

    foreach var neighbor in graph[node] do
    begin
      indegree[neighbor] -= 1;
      if indegree[neighbor] = 0 then
        queue.Enqueue(neighbor);
    end;
  end;

  Result := sortedOrder.Count = numCourses;
end;

