function BinSearch(arr: array of integer; start, &end, target: integer): integer;
begin
  var l := start;
  var r := &end;

  while l < r do
  begin
    var mid := l + (r - l) div 2;
    if arr[mid] = target then
    begin
      Result := mid;
      exit;
    end
    else if arr[mid] > target then
      r := mid
    else
      l := mid + 1;
  end;

  Result := l;
end;

function MaxEnvelopes(envelopes: array of array of integer): integer;
begin
  if envelopes.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sorted := envelopes.OrderBy(x -> x[0]).ThenByDescending(x -> x[1]).ToArray;
  var dp := new integer[sorted.Length];
  var maxLen := 0;

  for var i := 0 to sorted.Length - 1 do
  begin
    var index := BinSearch(dp, 0, maxLen, sorted[i][1]);
    dp[index] := sorted[i][1];

    if index = maxLen then
      maxLen += 1;
  end;

  Result := maxLen;
end;

function CheckBytes(data: array of integer; start, length: integer): boolean;
begin
  for var i := start + 1 to start + length do
  begin
    if (i >= data.Length) or ((data[i] and $C0) <> $80) then
    begin
      Result := False;
      exit;
    end;
  end;
  Result := True;
end;

function IsValidUTF8(data: array of integer): boolean;
begin
  var i := 0;
  while i < data.Length do
  begin
    if (data[i] and $80) = 0 then
      i += 1
    else if (data[i] and $E0) = $C0 then
    begin
      if not CheckBytes(data, i, 1) then
      begin
        Result := False;
        exit;
      end;
      i += 2;
    end
    else if (data[i] and $F0) = $E0 then
    begin
      if not CheckBytes(data, i, 2) then
      begin
        Result := False;
        exit;
      end;
      i += 3;
    end
    else if (data[i] and $F8) = $F0 then
    begin
      if not CheckBytes(data, i, 3) then
      begin
        Result := False;
        exit;
      end;
      i += 4;
    end
    else
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;

function LongestSubstringWithoutRepeat(s: string): string;
begin
  var maxLength := 0;
  var start := 1;
  var maxSubstring := '';
  var usedChars := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
  begin
    if usedChars.ContainsKey(s[i]) and (start <= usedChars[s[i]]) then
      start := usedChars[s[i]] + 1
    else if i - start + 1 > maxLength then
    begin
      maxLength := i - start + 1;
      maxSubstring := s.Substring(start-1, maxLength);
    end;

    usedChars[s[i]] := i;
  end;

  Result := maxSubstring;
end;

