    left: TreeNode;
    right: TreeNode;
  end;

function LCA(root, p, q: TreeNode): integer;
begin
  var smaller := p;
  var larger := q;

  if p.val > q.val then
  begin
    smaller := q;
    larger := p;
  end;

  var current := root;

  while current <> nil do
  begin
    if current.val < smaller.val then
      current := current.right
    else if current.val > larger.val then
      current := current.left
    else
    begin
      Result := current.val;
      exit;
    end;
  end;

  Result := -1;
end;

