function DictListToListDict(dictOfArrays: Dictionary<string, array of object>): array of Dictionary<string, object>;
begin
  if dictOfArrays.Count = 0 then
  begin
    Result := new Dictionary<string, object>[0];
    exit;
  end;

  var keys := dictOfArrays.Keys.ToList;
  var arrays := dictOfArrays.Values.ToList;

  // Check if all arrays have the same length
  var length := arrays[0].Length;
  for var i := 1 to arrays.Count - 1 do
    if arrays[i].Length <> length then
      raise new System.ArgumentException('All arrays must have the same length');

  var dictList := new List<Dictionary<string, object>>;

  for var i := 0 to length - 1 do
  begin
    var dict := new Dictionary<string, object>;
    for var j := 0 to keys.Count - 1 do
      dict[keys[j]] := arrays[j][i];
    dictList.Add(dict);
  end;

  Result := dictList.ToArray;
end;

function FindNextGreaterElement(arr: array of integer): array of integer;
begin
  var nextGreater := new integer[arr.Length];
  for var i := 0 to nextGreater.Length - 1 do
    nextGreater[i] := -1;

  var stack := new Stack<integer>;

  for var i := 0 to arr.Length - 1 do
  begin
    while (stack.Count > 0) and (arr[stack.Peek] < arr[i]) do
    begin
      nextGreater[stack.Pop] := arr[i];
    end;
    stack.Push(i);
  end;

  Result := nextGreater;
end;

function LargestHistogram(heights: array of integer): integer;
begin
  var stack := new Stack<integer>;
  var maxArea := 0;
  var index := 0;

  while index < heights.Length do
  begin
    if (stack.Count = 0) or (heights[stack.Peek] <= heights[index]) then
    begin
      stack.Push(index);
      index += 1;
    end
    else
    begin
      var topOfStack := stack.Pop;
      var area := heights[topOfStack] * 
                  (if stack.Count = 0 then index else index - stack.Peek - 1);
      maxArea := Max(maxArea, area);
    end;
  end;

  while stack.Count > 0 do
  begin
    var topOfStack := stack.Pop;
    var area := heights[topOfStack] * 
                (if stack.Count = 0 then index else index - stack.Peek - 1);
    maxArea := Max(maxArea, area);
  end;

  Result := maxArea;
end;

function FindZeroSumPairs(numbers: array of integer): array of (integer, integer);
