    if uniqueNumbers.Contains(-num) then
    begin
      var pair := (Min(num, -num), Max(num, -num));
      pairs.Add(pair);
    end;

  Result := pairs.OrderBy(p -> p.Item1).ToArray;
end;

function CountSubsequences(s: string): int64;
begin
  var dp := new int64[s.Length + 1];
  dp[0] := 1;
  var lastOccurrence := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
  begin
    dp[i] := 2 * dp[i - 1];
    if lastOccurrence.ContainsKey(s[i]) then
      dp[i] := dp[i] - dp[lastOccurrence[s[i]] - 1];
    lastOccurrence[s[i]] := i;
  end;

  Result := dp[s.Length] - 1;
end;

function SumTwoLargestNonConsecutive(arr: array of integer): integer;
begin
  if arr.Length < 2 then
  begin
    Result := 0;
    exit;
  end;

  var max1 := -MaxInt;
  var max2 := -MaxInt;
  var prev := -MaxInt;

  for var i := 0 to arr.Length - 1 do
  begin
    if (arr[i] > max1) and (arr[i] <> prev) then
    begin
      max2 := max1;
      max1 := arr[i];
    end
    else if (arr[i] > max2) and (arr[i] <> prev) then
      max2 := arr[i];
    prev := arr[i];
  end;

  Result := max1 + max2;
end;

function BalancedSubarrays(arr: array of integer): integer;
begin
  var count := 0;
  var oddSum := 0;
  var evenSum := 0;
  var prefixSum := new Dictionary<integer, integer>;
  prefixSum[0] := 1;

  foreach var num in arr do
  begin
    if num mod 2 = 0 then
      evenSum += num
    else
      oddSum += num;

    var diff := oddSum - evenSum;
    if prefixSum.ContainsKey(diff) then
      count += prefixSum[diff];

    if prefixSum.ContainsKey(diff) then
      prefixSum[diff] += 1
    else
      prefixSum[diff] := 1;
  end;

  Result := count;
end;

