function PaintHouses(n, k: integer): int64;
begin
  if n = 0 then
  begin
    Result := 0;
    exit;
  end;

  if n = 1 then
  begin
    Result := k;
    exit;
  end;

  var same: int64 := k;
  var diff: int64 := k * (k - 1);

  for var i := 3 to n do
  begin
    var newSame := diff;
    var newDiff := (same + diff) * (k - 1);
    same := newSame;
    diff := newDiff;
  end;

  Result := same + diff;
end;

function IsBipartite(edges: array of (integer, integer)): boolean;
begin
  var graph := new Dictionary<integer, List<integer>>;

  foreach var (u, v) in edges do
  begin
    if not graph.ContainsKey(u) then
      graph[u] := new List<integer>;
    if not graph.ContainsKey(v) then
      graph[v] := new List<integer>;
    graph[u].Add(v);
    graph[v].Add(u);
  end;

  var color := new Dictionary<integer, integer>;
  var queue := new Queue<integer>;

  foreach var node in graph.Keys do
  begin
    if color.ContainsKey(node) then
      continue;

    queue.Enqueue(node);
    color[node] := 1;

    while queue.Count > 0 do
    begin
      var cur := queue.Dequeue;
      foreach var neighbor in graph[cur] do
      begin
        if color.ContainsKey(neighbor) then
        begin
          if color[cur] = color[neighbor] then
          begin
            Result := False;
            exit;
          end;
        end
        else
        begin
          color[neighbor] := -color[cur];
          queue.Enqueue(neighbor);
        end;
      end;
    end;
  end;

  Result := True;
end;

function VersionSort(l: array of string): array of string;
