    var partsY := y.Split('.').Select(p -> StrToInt(p)).ToArray;
    var minLen := Min(partsX.Length, partsY.Length);

    for var i := 0 to minLen - 1 do
      if partsX[i] <> partsY[i] then
        Result := partsX[i].CompareTo(partsY[i]);

    Result := partsX.Length.CompareTo(partsY.Length);
  end);

  Result := versionList.ToArray;
end;

