function MaxSubarraySumOfLengthK(arr: array of integer; k: integer): integer;
begin
  var maxSum := -MaxInt;
  var windowSum := 0;
  var windowStart := 0;

  for var windowEnd := 0 to arr.Length - 1 do
  begin
    windowSum += arr[windowEnd];
    if windowEnd >= k - 1 then
    begin
      if windowSum > maxSum then
        maxSum := windowSum;
      windowSum -= arr[windowStart];
      windowStart += 1;
    end;
  end;

  Result := maxSum;
end;

