      count[num] += 1
    else
      count[num] := 1;

  foreach var num in count.Keys do
  begin
    if (k > 0) and count.ContainsKey(num + k) then
      pairCount += 1;
    if (k = 0) and (count[num] > 1) then
      pairCount += 1;
  end;

  Result := pairCount;
end;

