function CheckTriplet(nums: array of integer): boolean;
begin
  var sorted := nums.ToArray;
  sorted.Sort;

  if sorted.Length < 3 then
  begin
    Result := False;
    exit;
  end;

  var i := 0;
  while i < sorted.Length - 2 do
  begin
    if (sorted[i] > 0) or (sorted[i] + sorted[i + 1] + sorted[i + 2] > 0) then
    begin
      Result := False;
      exit;
    end;

    if (i > 0) and (sorted[i] = sorted[i - 1]) then
    begin
      i += 1;
      continue;
    end;

    var j := i + 1;
    var k := sorted.Length - 1;

    while j < k do
    begin
      if sorted[i] + sorted[j] > 0 then
      begin
        Result := False;
        exit;
      end;

      if (j > i + 1) and (sorted[j] = sorted[j - 1]) then
      begin
        j += 1;
        continue;
      end;

      var tmpSum := sorted[i] + sorted[j] + sorted[k];
      if tmpSum = 0 then
      begin
        Result := True;
        exit;
      end
      else if tmpSum > 0 then
      begin
        k -= 1;
        j -= 1;
      end;

      j += 1;
    end;

    i += 1;
  end;

  Result := False;
end;

function IndexFinder(nums: array of integer; num: integer): integer;
begin
  var left := 0;
  var right := nums.Length - 1;

  while right >= left do
  begin
    var middle := (left + right) div 2;

    if nums[middle] = num then
    begin
      Result := middle;
      exit;
    end
    else if nums[middle] < num then
      left := middle + 1
    else
      right := middle - 1;
  end;

  Result := -1;
end;

