procedure BacktrackUniq(remain: integer; combo: List<integer>; start: integer);
begin
  if remain = 0 then
  begin
    uniqResult.Add(combo.ToArray);
    exit;
  end;

  if remain < 0 then
    exit;

  var i := start;
  while i < uniqSorted.Length do
  begin
    combo.Add(uniqSorted[i]);
    BacktrackUniq(remain - uniqSorted[i], combo, i);
    combo.RemoveAt(combo.Count - 1);

    var currentVal := uniqSorted[i];
    while (i < uniqSorted.Length) and (uniqSorted[i] = currentVal) do
      i += 1;
  end;
end;

