function KthSmallestInBST(root: TreeNode; k: integer): integer?;
begin
  var stack := new Stack<TreeNode>;
  var current := root;
  var count := 0;

  while (stack.Count > 0) or (current <> nil) do
  begin
    while current <> nil do
    begin
      stack.Push(current);
      current := current.left;
    end;

    current := stack.Pop;
    count += 1;

    if count = k then
    begin
      Result := current.val;
      exit;
    end;

    current := current.right;
  end;

  Result := nil;
end;

