type
  CombinationGenerator<T> = class
  private
    class resultList: List<array of T>;
    class sourceArray: array of T;
    class combinationSize: integer;

    class procedure Generate(current: List<T>; start: integer);
    begin
      if current.Count = combinationSize then
      begin
        resultList.Add(current.ToArray);
        exit;
      end;

      for var i := start to sourceArray.Length - 1 do
      begin
        current.Add(sourceArray[i]);
        Generate(current, i);
        current.RemoveAt(current.Count - 1);
      end;
    end;
  public
    class function GetCombinations(arr: array of T; r: integer): array of array of T;
    begin
      resultList := new List<array of T>;
      sourceArray := arr;
      combinationSize := r;

      Generate(new List<T>, 0);
      Result := resultList.ToArray;
    end;
  end;

function PossibleCombinationsWithReplacement<T>(inputArray: array of T; r: integer): array of array of T;
begin
  Result := CombinationGenerator&<T>.GetCombinations(inputArray, r);
end;

