function LongestBalancedParentheses(s: string): integer;
begin
  var stack := new Stack<integer>;
  var maxLength := 0;
  var start := 0;

  for var i := 1 to s.Length do
  begin
    if s[i] = '(' then
      stack.Push(i)
    else
    begin
      if stack.Count > 0 then
      begin
        stack.Pop;
        if stack.Count = 0 then
          maxLength := Max(maxLength, i - start)
        else
          maxLength := Max(maxLength, i - stack.Peek);
      end
      else
        start := i;
    end;
  end;

  Result := maxLength;
end;

function LongestAlphaOrderSubstring(s: string): string;
begin
  if s.Length = 0 then
  begin
    Result := '';
    exit;
  end;

  var maxSubstring := s[1].ToString;
  var currentSubstring := s[1].ToString;

  for var i := 2 to s.Length do
  begin
    if s[i] >= s[i-1] then
    begin
      currentSubstring += s[i];
      if currentSubstring.Length > maxSubstring.Length then
        maxSubstring := currentSubstring;
    end
    else
      currentSubstring := s[i].ToString;
  end;

  Result := maxSubstring;
end;

