function FindZeroSumTriplets(nums: array of integer): array of array of integer;
begin
  var sorted := nums.ToArray;
  sorted.Sort;
  var uniqueTriplets := new HashSet<string>;
  var res := new List<array of integer>;

  if (sorted.Length < 3) or (sorted[0] > 0) or (sorted[sorted.Length - 1] < 0) then
  begin
    Result := [];
    exit;
  end;

  for var i := 0 to sorted.Length - 3 do
  begin
    if (i > 0) and (sorted[i] = sorted[i-1]) then
      continue;

    var left := i + 1;
    var right := sorted.Length - 1;

    while left < right do
    begin
      var tripletSum := sorted[i] + sorted[left] + sorted[right];

      if tripletSum < 0 then
        left += 1
      else if tripletSum > 0 then
        right -= 1
      else
      begin
        var triplet := |sorted[i], sorted[left], sorted[right]|;
        var key := $'{sorted[i]},{sorted[left]},{sorted[right]}';

        if not uniqueTriplets.Contains(key) then
        begin
          uniqueTriplets.Add(key);
          res.Add(triplet);
        end;

        left += 1;
      end;
    end;
  end;

  Result := res.ToArray;
end;

function FindRepeatedChars(s: string): array of char;
begin
  var charCount := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if charCount.ContainsKey(s[i]) then
      charCount[s[i]] += 1
    else
      charCount[s[i]] := 1;

  var repeatedChars := new List<char>;

  foreach var kv in charCount do
    if kv.Value > 1 then
      repeatedChars.Add(kv.Key);

  repeatedChars.Sort;
  Result := repeatedChars.ToArray;
end;

function LargestRectangle(matrix: array of array of integer): integer;
begin
  if matrix.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var m := matrix.Length;
  var n := matrix[0].Length;
  var heights := new integer[n + 1];
  var maxArea := 0;

  for var i := 0 to m - 1 do
  begin
    for var j := 0 to n - 1 do
      if matrix[i][j] = 1 then
        heights[j] := heights[j] + 1
      else
        heights[j] := 0;

    var stack := new Stack<integer>;
    stack.Push(-1);

    for var j := 0 to n do
    begin
      while (stack.Peek <> -1) and (heights[j] < heights[stack.Peek]) do
      begin
        var h := heights[stack.Pop];
        var w := j - stack.Peek - 1;
        maxArea := Max(maxArea, h * w);
      end;
      stack.Push(j);
    end;
  end;

  Result := maxArea;
end;

