function MergeSort(arr: array of integer): array of integer;
begin
  if arr.Length <= 1 then
  begin
    Result := arr;
    exit;
  end;

  var mid := arr.Length div 2;
  var leftArr := arr[:mid];
  var rightArr := arr[mid:];

  leftArr := MergeSort(leftArr);
  rightArr := MergeSort(rightArr);

  var merged := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < leftArr.Length) and (j < rightArr.Length) do
  begin
    if leftArr[i] < rightArr[j] then
    begin
      merged.Add(leftArr[i]);
      i += 1;
    end
    else
    begin
      merged.Add(rightArr[j]);
      j += 1;
    end;
  end;

  while i < leftArr.Length do
  begin
    merged.Add(leftArr[i]);
    i += 1;
  end;

  while j < rightArr.Length do
  begin
    merged.Add(rightArr[j]);
    j += 1;
  end;

  Result := merged.ToArray;
end;

function IsRepeatedSubstringPattern(s: string): boolean;
begin
  for var i := 1 to s.Length div 2 do
  begin
    if s.Length mod i = 0 then
    begin
      var pattern := s.Substring(0, i);
      var constructed := '';

      for var j := 1 to s.Length div i do
        constructed += pattern;

      if constructed = s then
      begin
        Result := True;
        exit;
      end;
    end;
  end;

  Result := False;
end;

