type
  TreeNode = auto class
    val: integer;
    left: TreeNode;
    right: TreeNode;
  end;

function MinDepth(root: TreeNode): integer;
begin
  if root = nil then
  begin
    Result := 0;
    exit;
  end;

  // If the node is a leaf node
  if (root.left = nil) and (root.right = nil) then
  begin
    Result := 1;
    exit;
  end;

  // If the left subtree is empty, recur for the right subtree
  if root.left = nil then
  begin
    Result := MinDepth(root.right) + 1;
    exit;
  end;

  // If the right subtree is empty, recur for the left subtree
  if root.right = nil then
  begin
    Result := MinDepth(root.left) + 1;
    exit;
  end;

  // If both subtrees are present, find the minimum of both and add 1
  Result := Min(MinDepth(root.left), MinDepth(root.right)) + 1;
end;

function IntersectionArrays(arr1, arr2: array of integer): array of integer;
begin
  var i := 0;
  var j := 0;
  var intersection := new List<integer>;

  while (i < arr1.Length) and (j < arr2.Length) do
  begin
    if arr1[i] < arr2[j] then
      i += 1
    else if arr1[i] > arr2[j] then
      j += 1
    else
    begin
      intersection.Add(arr1[i]);
      i += 1;
      j += 1;
    end;
  end;

  Result := intersection.ToArray;
end;

function MinTrioDegree(n: integer; edges: array of (integer, integer)): integer;
begin
  var graph := new Dictionary<integer, HashSet<integer>>;

  for var i := 1 to n do
    graph[i] := new HashSet<integer>;

  foreach var (u, v) in edges do
  begin
    graph[u].Add(v);
    graph[v].Add(u);
  end;

  var ans := MaxInt;

  for var i := 1 to n do
    for var j := i + 1 to n do
      for var k := j + 1 to n do
        if graph[i].Contains(j) and graph[j].Contains(k) and graph[i].Contains(k) then
        begin
          var degree := graph[i].Count + graph[j].Count + graph[k].Count - 6;
          if degree < ans then
            ans := degree;
        end;

  if ans = MaxInt then
    Result := -1
  else
    Result := ans;
end;

function LongestCommonIncreasingSubsequence(A, B: array of integer): integer;
begin
  var m := A.Length;
  var n := B.Length;
  var dp := new integer[m + 1, n + 1];
  var maxLen := 0;

  for var i := 1 to m do
    for var j := 1 to n do
      if A[i-1] = B[j-1] then
      begin
        dp[i, j] := dp[i-1, j-1] + 1;
        if dp[i, j] > maxLen then
          maxLen := dp[i, j];
      end
      else if A[i-1] > B[j-1] then
        dp[i, j] := dp[i-1, j]
      else
        dp[i, j] := dp[i, j-1];

  Result := maxLen;
end;

