    for var j := i to arr.Length - 1 do
    begin
      currentSum += arr[j];
      if currentSum = k then
      begin
        if dictSum.ContainsKey(currentSum) then
          dictSum[currentSum] += 1
        else
          dictSum[currentSum] := 1;
      end;
    end;
  end;

  var maxVal := 0;
  foreach var val in dictSum.Values do
    if val > maxVal then
      maxVal := val;

  Result := maxVal;
end;

