function FindTargetPairs(arr: array of integer; target: integer): integer;
begin
  var numCounts := new Dictionary<integer, integer>;
  var pairCount := 0;

  foreach var num in arr do
  begin
    var complement := target - num;
    if numCounts.ContainsKey(complement) then
      pairCount += numCounts[complement];

    if numCounts.ContainsKey(num) then
      numCounts[num] += 1
    else
      numCounts[num] := 1;
  end;

  Result := pairCount;
end;

function LargestSubarray(arr: array of integer): integer;
begin
  var maxLength := 0;
  var sumMap := new Dictionary<integer, integer>;
  var currentSum := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    currentSum += arr[i];

    if (arr[i] = 0) and (maxLength = 0) then
      maxLength := 1;

    if currentSum = 0 then
      maxLength := i + 1;

    if sumMap.ContainsKey(currentSum) then
    begin
      var len := i - sumMap[currentSum];
      if len > maxLength then
        maxLength := len;
    end
    else
      sumMap[currentSum] := i;
  end;

  Result := maxLength;
end;

function IsPrime(num: integer): boolean;
begin
  if num < 2 then
  begin
    Result := False;
    exit;
  end;

  for var i := 2 to Trunc(Sqrt(num)) do
    if num mod i = 0 then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;

