function ConvertToBits(A, B: integer): integer;
begin
  var xorResult := A xor B;
  var bitCount := 0;
  var temp := xorResult;

  while temp <> 0 do
  begin
    bitCount += temp and 1;
    temp := temp shr 1;
  end;

  Result := bitCount;
end;

function MaxNonOverlap(intervals: array of array of integer): integer;
begin
  var sorted := intervals.OrderBy(x -> x[1]).ToArray;
  var end_ := sorted[0][1];
  var answer := 1;

  for var i := 1 to sorted.Length - 1 do
  begin
    var intervalStart := sorted[i][0];
    var intervalEnd := sorted[i][1];

    if end_ <= intervalStart then
    begin
      end_ := intervalEnd;
      answer += 1;
    end;
  end;

  Result := answer;
end;

function MaxDistance(grid: array of array of integer): integer;
begin
  var yLen := grid.Length;
  var xLen := yLen;
  var foundWater := False;
  var foundLand := False;
  var visited := new HashSet<(integer, integer)>;
  var curList := new Queue<(integer, integer)>;

  for var y := 0 to yLen - 1 do
    for var x := 0 to xLen - 1 do
      if grid[y][x] = 1 then
      begin
        visited.Add((y, x));
        curList.Enqueue((y, x));
        foundLand := True;
      end
      else
        foundWater := True;

  if foundWater and foundLand then
  begin
    var nextCoords := |(0, 1), (0, -1), (1, 0), (-1, 0)|;
    var curStep := 0;

    while True do
    begin
      var nextList := new Queue<(integer, integer)>;

      while curList.Count > 0 do
      begin
        var curCell := curList.Dequeue;

        foreach var nextCoord in nextCoords do
        begin
          var nextCellY := curCell.Item1 + nextCoord.Item1;
          var nextCellX := curCell.Item2 + nextCoord.Item2;

          if (nextCellY >= 0) and (nextCellY < yLen) and 
             (nextCellX >= 0) and (nextCellX < xLen) and 
             not visited.Contains((nextCellY, nextCellX)) then
          begin
            visited.Add((nextCellY, nextCellX));
            nextList.Enqueue((nextCellY, nextCellX));
          end;
        end;
      end;

      if nextList.Count = 0 then
        break
      else
      begin
        curList := nextList;
        curStep += 1;
      end;
    end;

    Result := curStep;
  end
  else
    Result := -1;
end;

