var memoDict: Dictionary<integer, List<List<string>>>;
var wordSet: HashSet<string>;
var sGlobal: string;

function SentencesStartingAt(position: integer): List<List<string>>;
begin
  if memoDict.ContainsKey(position) then
  begin
    Result := memoDict[position];
    exit;
  end;

  if position = sGlobal.Length then
  begin
    var empty := new List<List<string>>;
    empty.Add(new List<string>);
    memoDict[position] := empty;
    Result := empty;
    exit;
  end;

  var sentences := new List<List<string>>;
  var word := '';
  var pos := position;

  while pos < sGlobal.Length do
  begin
    word += sGlobal[pos + 1];
    if wordSet.Contains(word) then
    begin
      var subSentences := SentencesStartingAt(pos + 1);
      foreach var sub in subSentences do
      begin
        var newSentence := new List<string>;
        newSentence.Add(word);
        newSentence.AddRange(sub);
        sentences.Add(newSentence);
      end;
    end;
    pos += 1;
  end;

  memoDict[position] := sentences;
  Result := sentences;
end;

function StringConstruct(s: string; wordDict: array of string): array of string;
begin
  memoDict := new Dictionary<integer, List<List<string>>>;
  wordSet := new HashSet<string>(wordDict);
  sGlobal := s;

  var allSentences := SentencesStartingAt(0);
  var output := new List<string>;

  foreach var sentence in allSentences do
    output.Add(string.Join(' ', sentence));

  Result := output.ToArray;
end;

var memoScramble: Dictionary<string, boolean>;

function ScrambleCheck(s1, s2: string): boolean;
begin
  var key := s1 + '#' + s2;
  if memoScramble.ContainsKey(key) then
  begin
    Result := memoScramble[key];
    exit;
  end;

  if s1 = s2 then
  begin
    memoScramble[key] := True;
    Result := True;
    exit;
  end;

  var len := s1.Length;

  for var i := 1 to len - 1 do
  begin
    if (ScrambleCheck(s1.Substring(0, i), s2.Substring(0, i)) and 
        ScrambleCheck(s1.Substring(i), s2.Substring(i))) or
       (ScrambleCheck(s1.Substring(0, i), s2.Substring(len - i)) and 
        ScrambleCheck(s1.Substring(i), s2.Substring(0, len - i))) then
    begin
      memoScramble[key] := True;
      Result := True;
      exit;
    end;
  end;

  memoScramble[key] := False;
  Result := False;
end;

function IsScramble(str1, str2: string): boolean;
begin
  if str1 = str2 then
  begin
    Result := True;
    exit;
  end;

  var chars1 := str1.ToCharArray;
  var chars2 := str2.ToCharArray;
  &Array.Sort(chars1);
  &Array.Sort(chars2);

  if not chars1.SequenceEqual(chars2) then
  begin
    Result := False;
    exit;
  end;

  memoScramble := new Dictionary<string, boolean>;

  Result := ScrambleCheck(str1, str2);
end;

function RotateImage(A: array[,] of integer): array[,] of integer;
begin
  var n := A.GetLength(0);
  var rotated := new integer[n, n];

  // Transpose and then reverse each row for clockwise rotation
  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      rotated[j, n - 1 - i] := A[i, j];

  Result := rotated;
end;

