function BFS(i, j, targetX, targetY: integer): integer;
begin
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((i, j, 0));
  var seen := new HashSet<(integer, integer)>;
  seen.Add((i, j));
  var moves := |(1,2), (2,1), (1,-2), (2,-1), (-1,2), (-2,1), (-1,-2), (-2,-1)|;

  while queue.Count > 0 do
  begin
    var (curX, curY, dist) := queue.Dequeue;

    foreach var (dx, dy) in moves do
    begin
      var nextX := curX + dx;
      var nextY := curY + dy;

      if not seen.Contains((nextX, nextY)) and (nextX > -4) and (nextY > -4) then
      begin
        if (nextX = targetX) and (nextY = targetY) then
        begin
          Result := dist + 1;
          exit;
        end;

        seen.Add((nextX, nextY));
        queue.Enqueue((nextX, nextY, dist + 1));
      end;
    end;
  end;

  Result := -1;
end;

function MinKnightMoves(x, y: integer): integer;
