function StringReverse(s: string): string;
begin
  var stack := new Stack<char>;

  for var i := 1 to s.Length do
    stack.Push(s[i]);

  var reversed := new StringBuilder;

  while stack.Count > 0 do
    reversed.Append(stack.Pop);

  Result := reversed.ToString;
end;

function ZigzagString(s: string; numRows: integer): string;
begin
  if (numRows = 1) or (s.Length <= numRows) then
  begin
    Result := s;
    exit;
  end;

  var patternNumb := numRows * 2 - 2;
  var sb := new StringBuilder;

  for var i := 0 to numRows - 1 do
  begin
    if i = 0 then
    begin
      sb.Append(s[i + 1]);
      var startPoint := patternNumb;

      while startPoint < s.Length do
      begin
        sb.Append(s[startPoint + 1]);
        startPoint += patternNumb;
      end;
    end
    else if i = numRows - 1 then
    begin
      sb.Append(s[i + 1]);
      var startPoint := i + patternNumb;

      while startPoint < s.Length do
      begin
        sb.Append(s[startPoint + 1]);
        startPoint += patternNumb;
      end;
    end
    else
    begin
      sb.Append(s[i + 1]);
      var step1 := 2 * (numRows - i - 1);
      var step2 := patternNumb - step1;
      var pos := i;

      while True do
      begin
        pos += step1;
        if pos >= s.Length then break;
        sb.Append(s[pos + 1]);

        pos += step2;
        if pos >= s.Length then break;
        sb.Append(s[pos + 1]);
      end;
    end;
  end;

  Result := sb.ToString;
end;

var towerInfo: array of List<integer>;

function Search(cutA, cutB: integer): integer;
begin
  var visited := new HashSet<integer>;
  var queue := new Queue<integer>;

  visited.Add(cutA);

  foreach var i in towerInfo[cutA] do
    if i <> cutB then
      queue.Enqueue(i);

  while queue.Count > 0 do
  begin
    var node := queue.Dequeue;
    visited.Add(node);

    foreach var i in towerInfo[node] do
      if not visited.Contains(i) then
        queue.Enqueue(i);
  end;

  Result := visited.Count;
end;

function PowerGridDiff(n: integer; wires: array of (integer, integer)): integer;
begin
  towerInfo := new List<integer>[n + 1];
  for var i := 0 to n do
    towerInfo[i] := new List<integer>;

  foreach var (a, b) in wires do
  begin
    towerInfo[a].Add(b);
    towerInfo[b].Add(a);
  end;

  var minDiff := MaxInt;

  foreach var (a, b) in wires do
  begin
    var aVal := Search(a, b);
    var bVal := Search(b, a);
    var abVal := Abs(aVal - bVal);

    if abVal < minDiff then
      minDiff := abVal;
  end;

  Result := minDiff;
end;

function LongestCommonSuffix(strs: array of string): string;
begin
  if strs.Length = 0 then
  begin
    Result := '';
    exit;
  end;

  var reverseStrs := new List<string>;
  foreach var s in strs do
    reverseStrs.Add(s.Inverse);

  var common := '';

  for var i := 1 to reverseStrs[0].Length do
  begin
    var ch := reverseStrs[0][i];
    var flag := True;

    for var j := 1 to reverseStrs.Count - 1 do
    begin
      if (i > reverseStrs[j].Length) or (reverseStrs[j][i] <> ch) then
      begin
        flag := False;
        break;
      end;
    end;

    if flag then
      common := ch + common
    else
      break;
  end;

  Result := common;
end;

