function FindKthLargest(nums: array of integer; k: integer): integer;
begin
  var heap := new List<integer>;

  foreach var num in nums do
  begin
    heap.Add(num);
    var i := heap.Count - 1;

    // Heapify up (min-heap)
    while (i > 0) and (heap[i] < heap[(i - 1) div 2]) do
    begin
      heap.Swap(i, (i - 1) div 2);
      i := (i - 1) div 2;
    end;

    if heap.Count > k then
    begin
      // Remove smallest element (root)
      heap[0] := heap[heap.Count - 1];
      heap.RemoveAt(heap.Count - 1);

      // Heapify down
      i := 0;
      while True do
      begin
        var left := 2 * i + 1;
        var right := 2 * i + 2;
        var smallest := i;

        if (left < heap.Count) and (heap[left] < heap[smallest]) then
          smallest := left;
        if (right < heap.Count) and (heap[right] < heap[smallest]) then
          smallest := right;

        if smallest = i then
          break;

        heap.Swap(i, smallest);
        i := smallest;
      end;
    end;
  end;

  Result := heap[0];
end;

function IsPrime(num: int64): boolean;
begin
  if num < 2 then
  begin
    Result := False;
    exit;
  end;

  for var i := 2 to Trunc(Sqrt(num)) do
    if num mod i = 0 then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;

function PrimeFibonacci(n: integer): int64;
begin
  var found := 0;
  var a: int64 := 0;
  var b: int64 := 1;

  while found < n do
  begin
    var c := a + b;
    a := b;
    b := c;

    if IsPrime(b) then
      found += 1;
  end;

  Result := b;
end;

var bracketResult: List<string>;
    bracketN: integer;

procedure GenerateBrackets(current: string; left, right: integer);
begin
  if (left = 0) and (right = 0) then
  begin
    bracketResult.Add(current);
    exit;
  end;

  if left > 0 then
    GenerateBrackets(current + '(', left - 1, right);

  if right > left then
    GenerateBrackets(current + ')', left, right - 1);
end;

function GenerateBalancedBrackets(n: integer): array of string;
begin
  bracketResult := new List<string>;
  bracketN := n;

  GenerateBrackets('', n, n);
  Result := bracketResult.ToArray;
end;

function LongestUniqueSub(s: string): integer;
begin
  var charMap := new Dictionary<char, integer>;
  var subStart := 1;
  var maxLen := 0;

  for var i := 1 to s.Length do
  begin
    if charMap.ContainsKey(s[i]) and (charMap[s[i]] >= subStart) then
    begin
      subStart := charMap[s[i]] + 1;
      charMap[s[i]] := i;
    end
    else
      charMap[s[i]] := i;

    var currentLen := i - subStart + 1;
    if currentLen > maxLen then
      maxLen := currentLen;
  end;

  Result := maxLen;
end;

function CheckPythagoreanTriplet(nums: array of integer): boolean;
begin
  var uniqueNums := new HashSet<integer>(nums);
  var sorted := uniqueNums.ToList;
  sorted.Sort;

  for var i := 0 to sorted.Count - 1 do
    for var j := i + 1 to sorted.Count - 1 do
      for var k := j + 1 to sorted.Count - 1 do
        if sorted[i] * sorted[i] + sorted[j] * sorted[j] = sorted[k] * sorted[k] then
        begin
          Result := True;
          exit;
        end;

  Result := False;
end;

function CheckAscendingOrder(arr: array of integer): boolean;
begin
  for var i := 0 to arr.Length - 2 do
    if arr[i] > arr[i + 1] then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;

function CountTrailingZeroesInFactorial(n: integer): integer;
begin
  var count := 0;
  var num := n;

  while num >= 5 do
  begin
    num := num div 5;
    count += num;
  end;

  Result := count;
end;

function LexicographicallyNext(w: string): string;
begin
  var chars := w.ToCharArray;
  var n := chars.Length;

  // Check if string is sorted in descending order
  var sortedDesc := True;
  for var i := 1 to n - 1 do
    if chars[i] > chars[i - 1] then
    begin
      sortedDesc := False;
      break;
    end;

  if sortedDesc then
  begin
    Result := 'no answer';
    exit;
  end;

  // Find the first character that is smaller than the next character from the right
  var k := n - 2;
  while (k >= 0) and (chars[k] >= chars[k + 1]) do
    k -= 1;

  // Find the smallest character to the right of k that is greater than chars[k]
  var l := n - 1;
  while (l > k) and (chars[l] <= chars[k]) do
    l -= 1;

  // Swap chars[k] and chars[l]
  Swap(chars[k], chars[l]);

  // Reverse the suffix starting at k+1
  var left := k + 1;
  var right := n - 1;
  while left < right do
  begin
    Swap(chars[left], chars[right]);
    left += 1;
    right -= 1;
  end;

  Result := new string(chars);
end;

function MaxSubArray(nums: array of integer): integer;
begin
  var currentSum := nums[0];
  var maxSum := nums[0];

  for var i := 1 to nums.Length - 1 do
  begin
    currentSum := Max(nums[i], currentSum + nums[i]);
    maxSum := Max(maxSum, currentSum);
  end;

  Result := maxSum;
end;

