function CountIncreasingPairs(nums: array of integer): integer;
begin
  var count := 0;

  for var i := 0 to nums.Length - 1 do
    for var j := i + 1 to nums.Length - 1 do
      if nums[j] > nums[i] then
        count += 1;

  Result := count;
end;

function MaxNum(nums: array of integer): integer;
begin
  var maxVal := nums[0];

  for var i := 1 to nums.Length - 1 do
    if nums[i] > maxVal then
      maxVal := nums[i];

  Result := maxVal;
end;

function IsPalindromeIgnoringCaseAndNonAlphanumeric(s: string): boolean;
begin
  var cleaned := new StringBuilder;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    if Char.IsLetterOrDigit(ch) then
      cleaned.Append(Char.ToLower(ch));
  end;

  var cleanedStr := cleaned.ToString;
  var reversed := cleanedStr.Inverse;

  Result := cleanedStr = reversed;
end;

