  foreach var num in integerList do
    if num = integerVal then
      count += 1;

  Result := count;
end;

function MinDelToPalindrome(s: string): integer;
begin
  var n := s.Length;
  var dp := new integer[n, n];

  for var gap := 1 to n - 1 do
    for var i := 0 to n - gap - 1 do
    begin
      var j := i + gap;
      if s[i + 1] = s[j + 1] then
        dp[i, j] := dp[i + 1, j - 1]
      else
        dp[i, j] := Min(dp[i + 1, j], dp[i, j - 1]) + 1;
    end;

  Result := dp[0, n - 1];
end;

function SmallestSubarray(arr: array of integer; S: integer): integer;
begin
  var minLength := MaxInt;
  var currentSum := 0;
  var windowStart := 0;

  for var windowEnd := 0 to arr.Length - 1 do
  begin
    currentSum += arr[windowEnd];

    while currentSum >= S do
    begin
      var len := windowEnd - windowStart + 1;
      if len < minLength then
        minLength := len;

      currentSum -= arr[windowStart];
      windowStart += 1;
    end;
  end;

  if minLength = MaxInt then
    Result := 0
  else
    Result := minLength;
end;

function SumOfDigits(number: integer): integer;
begin
  var sum := 0;
  var num := Abs(number);

  while num > 0 do
  begin
    sum += num mod 10;
    num := num div 10;
  end;

  Result := sum;
end;

function FindRotations(arr: array of integer): integer;
begin
  if arr[0] <= arr[arr.Length - 1] then
  begin
    Result := 0;
    exit;
  end;

  var low := 0;
  var high := arr.Length - 1;

  while low <= high do
  begin
    var mid := (low + high) div 2;

    if arr[mid] >= arr[0] then
      low := mid + 1
    else
      high := mid - 1;
  end;

  Result := low;
end;

function FindFirstOccurrence(nums: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := nums.Length - 1;
  var idx := -1;

  while left <= right do
  begin
    var mid := left + (right - left) div 2;

    if nums[mid] = target then
    begin
      idx := mid;
      right := mid - 1;
    end
    else if nums[mid] < target then
      left := mid + 1
    else
      right := mid - 1;
  end;

  Result := idx;
end;

function BinaryGridToStringRepresentation(grid: array of array of integer): array of string;
begin
  var rows := new List<string>;

  foreach var row in grid do
  begin
    var strRow := new StringBuilder;

    foreach var cell in row do
      if cell = 1 then
        strRow.Append('X')
      else
        strRow.Append('-');

    rows.Add(strRow.ToString);
  end;

  Result := rows.ToArray;
end;

function GCD(a, b: integer): integer;
begin
  var x := a;
  var y := b;

  while y <> 0 do
  begin
    var temp := y;
    y := x mod y;
    x := temp;
  end;

  Result := x;
end;

function FindSubstringIndices(s: string; words: array of string): array of integer;
begin
  if words.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var lenWord := words[0].Length;
  var lenCombo := lenWord * words.Length;

  if s.Length < lenCombo then
  begin
    Result := new integer[0];
    exit;
  end;

  var indices := new List<integer>;
  var wordDict := new Dictionary<string, integer>;

  foreach var w in words do
    if wordDict.ContainsKey(w) then
      wordDict[w] += 1
    else
      wordDict[w] := 1;

  for var i := 0 to s.Length - lenCombo do
  begin
    var seen := new Dictionary<string, integer>;
    var start := i;
    var count := words.Length;

    while count > 0 do
    begin
      var substr := s.Substring(start, lenWord);

      if (not wordDict.ContainsKey(substr)) or 
         ((seen.ContainsKey(substr)) and (seen[substr] = wordDict[substr])) then
        break;

      if seen.ContainsKey(substr) then
        seen[substr] += 1
      else
        seen[substr] := 1;

      start += lenWord;
      count -= 1;
    end;

    if count = 0 then
      indices.Add(i);
  end;

  Result := indices.ToArray;
end;

