function WeaveArrays<T>(arr1, arr2: array of T): array of T;
begin
  var woven := new List<T>;
  var maxLen := Max(arr1.Length, arr2.Length);

  for var i := 0 to maxLen - 1 do
  begin
    if i < arr1.Length then
      woven.Add(arr1[i]);
    if i < arr2.Length then
      woven.Add(arr2[i]);
  end;

  Result := woven.ToArray;
end;

function EvaluatePostfix(expression: string): integer;
begin
  var stack := new Stack<integer>;
  var tokens := expression.Split;

  foreach var token in tokens do
  begin
    if (token.Length = 1) and (token[1] in ['+', '-', '*', '/']) then
    begin
      var y := stack.Pop;
      var x := stack.Pop;

      case token[1] of
        '+': stack.Push(x + y);
        '-': stack.Push(x - y);
        '*': stack.Push(x * y);
        '/': stack.Push(x div y);
      end;
    end
    else
    begin
      var num: integer;
      if integer.TryParse(token, num) then
        stack.Push(num);
    end;
  end;

  Result := stack.Pop;
end;

function MaxTurbulenceSize(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var ans := 1;
  var cnt := 1;

  // First pattern: even index > previous, odd index < previous
  for var i := 1 to arr.Length - 1 do
  begin
    if (i mod 2 = 1) and (arr[i] > arr[i - 1]) or
       (i mod 2 = 0) and (arr[i] < arr[i - 1]) then
      cnt += 1
    else
    begin
      if cnt > ans then
        ans := cnt;
      cnt := 1;
    end;
  end;

  if cnt > ans then
    ans := cnt;

  cnt := 1;

  // Second pattern: even index < previous, odd index > previous
  for var i := 1 to arr.Length - 1 do
  begin
    if (i mod 2 = 1) and (arr[i] < arr[i - 1]) or
       (i mod 2 = 0) and (arr[i] > arr[i - 1]) then
      cnt += 1
    else
    begin
      if cnt > ans then
        ans := cnt;
      cnt := 1;
    end;
  end;

  if cnt > ans then
    ans := cnt;

  Result := ans;
end;

