function FibonacciSum(n: integer): int64;
begin
  if n <= 0 then
  begin
    Result := 0;
    exit;
  end;

  var a: int64 := 0;
  var b: int64 := 1;
  var total: int64 := 1;

  for var i := 3 to n do
  begin
    var c := a + b;
    a := b;
    b := c;
    total += b;
  end;

  if n = 1 then
    Result := 1
  else
    Result := total;
end;

function NthUglyNumber(n: integer): int64;
begin
  var ugly := new List<int64>;
  ugly.Add(1);

  var i2 := 0;
  var i3 := 0;
  var i5 := 0;

  var nextMultipleOf2: int64 := 2;
  var nextMultipleOf3: int64 := 3;
  var nextMultipleOf5: int64 := 5;

  while ugly.Count < n do
  begin
    var nextUglyNo := Min(Min(nextMultipleOf2, nextMultipleOf3), nextMultipleOf5);
    ugly.Add(nextUglyNo);

    if nextUglyNo = nextMultipleOf2 then
    begin
      i2 += 1;
      nextMultipleOf2 := ugly[i2] * 2;
    end;

    if nextUglyNo = nextMultipleOf3 then
    begin
      i3 += 1;
      nextMultipleOf3 := ugly[i3] * 3;
    end;

    if nextUglyNo = nextMultipleOf5 then
    begin
      i5 += 1;
      nextMultipleOf5 := ugly[i5] * 5;
    end;
  end;

  Result := ugly.Last;
end;

function HalvesSumEqual(num: int64): boolean;
begin
  var numStr := num.ToString;
  var halfLen := numStr.Length div 2;

  if numStr.Length mod 2 <> 0 then
  begin
    Result := False;
    exit;
  end;

  var firstHalf := numStr.Substring(0, halfLen);
  var secondHalf := numStr.Substring(halfLen);

  var sumFirstHalf := 0;
  for var i := 1 to firstHalf.Length do
    sumFirstHalf += StrToInt(firstHalf[i].ToString);

  var sumSecondHalf := 0;
  for var i := 1 to secondHalf.Length do
    sumSecondHalf += StrToInt(secondHalf[i].ToString);

  Result := sumFirstHalf = sumSecondHalf;
end;

function ClosestCost(baseCosts, toppingCosts: array of integer; target: integer): integer;
begin
  var toppingCombinations := new List<integer>;
  toppingCombinations.Add(0);

  // Generate all possible topping combinations (0, 1, or 2 of each topping)
  for var i := 0 to toppingCosts.Length - 1 do
  begin
    var currentCount := toppingCombinations.Count;
    for var j := 0 to currentCount - 1 do
    begin
      var val := toppingCombinations[j];
      toppingCombinations.Add(val + toppingCosts[i]);
      toppingCombinations.Add(val + 2 * toppingCosts[i]);
    end;
  end;

  var closestSum := MaxInt;

  foreach var base_ in baseCosts do
    foreach var toppingSum in toppingCombinations do
    begin
      var currentSum := base_ + toppingSum;
      if (Abs(target - currentSum) < Abs(target - closestSum)) or
         ((Abs(target - currentSum) = Abs(target - closestSum)) and (currentSum < closestSum)) then
        closestSum := currentSum;
    end;

  Result := closestSum;
end;

function ValidString(S: string): boolean;
begin
  if (S.Length = 0) or (S.Length < 3) then
  begin
    Result := False;
    exit;
  end;

  var stack := new Stack<char>;

  for var i := 1 to S.Length do
  begin
    stack.Push(S[i]);

    if stack.Count >= 3 then
    begin
      var arr := stack.ToArray;

      // Check if last three are 'a', 'b', 'c'
      if (arr[stack.Count - 3] = 'a') and 
         (arr[stack.Count - 2] = 'b') and 
         (arr[stack.Count - 1] = 'c') then
      begin
        stack.Pop;
        stack.Pop;
        stack.Pop;
      end;
    end;
  end;

  Result := stack.Count = 0;
end;

function IsBalancedString(s: string): integer;
begin
  var charCount := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if charCount.ContainsKey(s[i]) then
      charCount[s[i]] += 1
    else
      charCount[s[i]] := 1;

  foreach var kv in charCount do
    if kv.Value mod 2 <> 0 then
    begin
      Result := 0;
      exit;
    end;

  Result := 1;
end;

function TwoSum(nums: array of integer; target: integer): array of integer;
begin
  var numDict := new Dictionary<integer, integer>;

  for var i := 0 to nums.Length - 1 do
  begin
    var complement := target - nums[i];

    if numDict.ContainsKey(complement) then
    begin
      Result := |numDict[complement], i|;
      exit;
    end;

    numDict[nums[i]] := i;
  end;

  Result := new integer[0];
end;

