function MaximalSquare(matrix: array of array of char): integer;
begin
  if matrix.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var m := matrix.Length;
  var n := matrix[0].Length;
  var dp := new integer[m, n];
  var maxSide := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if matrix[i][j] = '1' then
      begin
        if (i = 0) or (j = 0) then
          dp[i, j] := 1
        else
          dp[i, j] := Min(Min(dp[i-1, j], dp[i, j-1]), dp[i-1, j-1]) + 1;

        if dp[i, j] > maxSide then
          maxSide := dp[i, j];
      end;

  Result := maxSide * maxSide;
end;

function MinSwapsToSort(arr: array of integer): integer;
begin
  var n := arr.Length;
  var count := 0;

  // Create a list of pairs (value, index)
  var pairs := new List<(integer, integer)>;
  for var i := 0 to n - 1 do
    pairs.Add((arr[i], i));

  // Sort by value
  pairs.Sort((x, y) -> x.Item1.CompareTo(y.Item1));

  var visited := new boolean[n];

  for var i := 0 to n - 1 do
  begin
    if visited[i] or (pairs[i].Item2 = i) then
      continue;

    var cycleSize := 0;
    var j := i;

    while not visited[j] do
    begin
      visited[j] := True;
      j := pairs[j].Item2;
      cycleSize += 1;
    end;

    if cycleSize > 0 then
      count += cycleSize - 1;
  end;

  Result := count;
end;

function SqrtBinarySearch(x: integer): integer;
begin
  if (x = 0) or (x = 1) then
  begin
    Result := x;
    exit;
  end;

  var start := 1;
  var &end := x;
  var ans := 0;

  while start <= &end do
  begin
    var mid := (start + &end) div 2;

    if mid * mid = x then
    begin
      Result := mid;
      exit;
    end;

    if mid * mid < x then
    begin
      start := mid + 1;
      ans := mid;
    end
    else
      &end := mid - 1;
  end;

  Result := ans;
end;

