function GroupStrings(strings: array of string): Dictionary<char, List<string>>;
begin
  var grouped := new Dictionary<char, List<string>>;

  foreach var str in strings do
  begin
    if str.Length = 0 then
      continue;

    var firstChar := str[1];

    if grouped.ContainsKey(firstChar) then
      grouped[firstChar].Add(str)
    else
      grouped[firstChar] := new List<string>([str]);
  end;

  Result := grouped;
end;

function SmallestRange(nums: array of integer; k: integer): integer;
begin
  var minNum := nums.Min;
  var maxNum := nums.Max;
  var diff := maxNum - minNum;

  if diff <= 2 * k then
    Result := 0
  else
    Result := diff - 2 * k;
end;

function MostRepeatedChar(s: string): char;
begin
  var freq := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if freq.ContainsKey(s[i]) then
      freq[s[i]] += 1
    else
      freq[s[i]] := 1;

  var maxChar := s[1];
  var maxCount := freq[s[1]];

  foreach var kv in freq do
    if kv.Value > maxCount then
    begin
      maxCount := kv.Value;
      maxChar := kv.Key;
    end;

  Result := maxChar;
end;

