    if charDict.ContainsKey(firstChar) then
      charDict[firstChar].Add(word)
    else
      charDict[firstChar] := new List<string>([word]);
  end;

  Result := new Dictionary<char, array of string>;

  foreach var kv in charDict do
  begin
    kv.Value.Sort;
    Result[kv.Key] := kv.Value.ToArray;
  end;
end;

function CheckSubsequence(s1, s2: string): boolean;
begin
  var s1Index := 1;

  for var i := 1 to s2.Length do
  begin
    if (s1Index <= s1.Length) and (s1[s1Index] = s2[i]) then
      s1Index += 1;
  end;

  Result := s1Index > s1.Length;
end;

function NumSubarraySum(nums: array of integer; k: integer): integer;
begin
  var count := 0;
  var sum := 0;
  var hashMap := new Dictionary<integer, integer>;
  hashMap[0] := 1;

  foreach var num in nums do
  begin
    sum += num;

    if hashMap.ContainsKey(sum - k) then
      count += hashMap[sum - k];

    if hashMap.ContainsKey(sum) then
      hashMap[sum] += 1
    else
      hashMap[sum] := 1;
  end;

  Result := count;
end;

function OptimizedBubbleSort(nums: array of integer): array of integer;
begin
  var arr := nums.ToArray;
  var n := arr.Length;

  if n <= 1 then
  begin
    Result := arr;
    exit;
  end;

  for var i := 0 to n - 2 do
  begin
    var swapped := False;

    for var j := 0 to n - 2 - i do
    begin
      if arr[j] > arr[j + 1] then
      begin
        Swap(arr[j], arr[j + 1]);
        swapped := True;
      end;
    end;

    if not swapped then
      break;
  end;

  Result := arr;
end;

function LongestSubseq(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var asc := new integer[arr.Length];
  var desc := new integer[arr.Length];

  for var i := 0 to arr.Length - 1 do
  begin
    asc[i] := 1;
    desc[i] := 1;
  end;

  for var i := 1 to arr.Length - 1 do
  begin
    if arr[i] > arr[i - 1] then
      asc[i] := asc[i - 1] + 1
    else if arr[i] < arr[i - 1] then
      desc[i] := desc[i - 1] + 1;
  end;

  var maxLen := Max(asc[arr.Length - 1], desc[arr.Length - 1]);

  for var i := arr.Length - 2 downto 0 do
  begin
    if ((arr[i] > arr[i + 1]) and (desc[i] < asc[i + 1] + 1)) or
       ((arr[i] < arr[i + 1]) and (asc[i] < desc[i + 1] + 1)) then
    begin
      maxLen := Max(maxLen, Max(asc[i + 1] + 1, desc[i + 1] + 1));
    end;
  end;

  Result := maxLen;
end;

function LongestSubstringWithTwoDistinctCharacters(s: string): integer;
begin
  var maxLen := 0;
  var start := 1;
  var freq := new Dictionary<char, integer>;

  for var &end := 1 to s.Length do
  begin
    if freq.ContainsKey(s[&end]) then
      freq[s[&end]] += 1
    else
      freq[s[&end]] := 1;

    while freq.Count > 2 do
    begin
      freq[s[start]] -= 1;
      if freq[s[start]] = 0 then
        freq.Remove(s[start]);
      start += 1;
    end;

    maxLen := Max(maxLen, &end - start + 1);
  end;

  Result := maxLen;
end;

function IsSubSequence(s, t: string): boolean;
begin
  var i := 1;
  var j := 1;

  while (i <= s.Length) and (j <= t.Length) do
  begin
    if s[i] = t[j] then
    begin
      i += 1;
      j += 1;
    end
    else
      j += 1;
  end;

  Result := i > s.Length;
end;

