    exit;
  end;

  var letters := new HashSet<char>;

  for var i := 1 to sentence.Length do
    if Char.IsLetter(sentence[i]) then
      letters.Add(Char.ToLower(sentence[i]));

  Result := letters.Count = 26;
end;

function MinimumLengthEncoding(words: array of string): integer;
begin
  var wordSet := new HashSet<string>;

  // Add all words to a set
  foreach var w in words do
    wordSet.Add(w);

  // Remove words that are suffixes of other words
  foreach var w in words do
    for var i := 1 to w.Length - 1 do
      if wordSet.Contains(w.Substring(i)) then
        wordSet.Remove(w.Substring(i));

  var totalLength := 0;
  foreach var w in wordSet do
    totalLength += w.Length + 1; // +1 for '#'

  Result := totalLength;
end;

function FindConsecutiveOnes(n: integer): integer;
begin
  var binary := Convert.ToString(n, 2);
  var maxCount := 0;
  var currentCount := 0;

  for var i := 1 to binary.Length do
  begin
    if binary[i] = '1' then
    begin
      currentCount += 1;
      if currentCount > maxCount then
        maxCount := currentCount;
    end
    else
      currentCount := 0;
  end;

  Result := maxCount;
end;

function CountWaysToExpress(n: integer): integer;
begin
  var ways := 0;

  for var i := 1 to n do
  begin
    var sum := 0;
    var j := i;

    while sum < n do
    begin
      sum += j;
      j += 1;
    end;

    if sum = n then
      ways += 1;
  end;

  Result := ways;
end;

function SortZeroOneTwo(arr: array of integer): array of integer;
begin
  var sorted := arr.ToArray;
  var low := 0;
  var mid := 0;
  var high := sorted.Length - 1;

  while mid <= high do
  begin
    case sorted[mid] of
      0:
      begin
        Swap(sorted[low], sorted[mid]);
        low += 1;
        mid += 1;
      end;
      1:
        mid += 1;
      2:
      begin
        Swap(sorted[mid], sorted[high]);
        high -= 1;
      end;
    end;
  end;

  Result := sorted;
end;

type
  Node = auto class
    value: integer;
    left: Node;
    right: Node;
  end;

function CheckBST(_node: Node): boolean;
begin
  var stack := new Stack<Node>;
  var current := _node;
  var prev: Node := nil;

  while (stack.Count > 0) or (current <> nil) do
  begin
    while current <> nil do
    begin
      stack.Push(current);
      current := current.left;
    end;

    current := stack.Pop;

    if (prev <> nil) and (current.value <= prev.value) then
    begin
      Result := False;
      exit;
    end;

    prev := current;
    current := current.right;
  end;

  Result := True;
end;

