  var numStr := Abs(num).ToString;
  var digits := numStr.ToCharArray;
  &Array.Sort(digits);

  var sortedNumStr := new string(digits);

  if sortedNumStr[1] = '0' then
  begin
    for var i := 2 to sortedNumStr.Length do
      if sortedNumStr[i] <> '0' then
      begin
        sortedNumStr := sortedNumStr[i] + sortedNumStr.Substring(1, i-2) + '0' + sortedNumStr.Substring(i);
        break;
      end;
  end;

  var val := StrToInt64(sortedNumStr);
  if num < 0 then
    Result := -val
  else
    Result := val;
end;

