function ShortestRoute(grid: array[,] of integer): integer;
begin
  var m := grid.GetLength(0);
  var n := grid.GetLength(1);
  var dx := |0, 1, 0, -1|;
  var dy := |1, 0, -1, 0|;

  // Min-heap priority queue using List with custom sorting
  var pq := new List<(integer, integer, integer)>;
  pq.Add((grid[0, 0], 0, 0));

  var visited := new boolean[m, n];

  while pq.Count > 0 do
  begin
    // Sort to get the minimum cost (simulating priority queue)
    pq.Sort((x, y) -> x.Item1.CompareTo(y.Item1));
    var (cost, x, y) := pq[0];
    pq.RemoveAt(0);

    if (x = m - 1) and (y = n - 1) then
    begin
      Result := cost;
      exit;
    end;

    for var i := 0 to 3 do
    begin
      var nx := x + dx[i];
      var ny := y + dy[i];

      if (nx >= 0) and (nx < m) and (ny >= 0) and (ny < n) and not visited[nx, ny] then
      begin
        visited[nx, ny] := True;
        pq.Add((cost + grid[nx, ny], nx, ny));
      end;
    end;
  end;

  Result := -1;
end;

function CanAttendMeetings(intervals: array of array of integer): boolean;
begin
  var sorted := intervals.OrderBy(x -> x[0]).ToArray;
  var latestEnd := 0;

  for var i := 0 to sorted.Length - 1 do
  begin
    var start := sorted[i][0];
    var &end := sorted[i][1];

    if start < latestEnd then
    begin
      Result := False;
      exit;
    end;

    latestEnd := &end;
  end;

  Result := True;
end;

