function IsPalindromeRearrangement(s: string): boolean;
begin
  var charCount := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if charCount.ContainsKey(s[i]) then
      charCount[s[i]] += 1
    else
      charCount[s[i]] := 1;

  var oddCount := 0;

  foreach var val in charCount.Values do
    if val mod 2 <> 0 then
      oddCount += 1;

  Result := oddCount <= 1;
end;

