function FindFirstUnique(arr: array of integer): integer;
begin
  var temp := new integer[arr.Length + 1];
  var temp2 := 0;

  for var i := 0 to arr.Length - 1 do
    temp[i] := arr[i];

  temp[arr.Length] := arr[0];

  for var i := 0 to arr.Length - 1 do
  begin
    var idx := temp[i];

    while (idx <> -1) and (temp[idx] <> -1) do
    begin
      temp2 := temp[idx];
      temp[idx] := -1;
      idx := temp2;
    end;
  end;

  for var i := 0 to arr.Length - 1 do
    if temp[i] <> -1 then
    begin
      Result := i;
      exit;
    end;

  Result := arr.Length;
end;

