function CountBalancedBinaryTrees(n: integer): int64;
begin
  if n = 0 then
    Result := 1
  else if n = 1 then
    Result := 1
  else if n mod 2 = 0 then
  begin
    var half := n div 2;
    Result := CountBalancedBinaryTrees(half) * CountBalancedBinaryTrees(half - 1) + 
              CountBalancedBinaryTrees(half) * CountBalancedBinaryTrees(half);
  end
  else
  begin
    var half := n div 2;
    Result := CountBalancedBinaryTrees(half) * CountBalancedBinaryTrees(half) * 2 - 
              CountBalancedBinaryTrees(half);
  end;
end;

function FindThreeNumbers(arr: array of integer): (integer, integer, integer);
begin
  if arr.Length < 2 then
  begin
    Result := (arr[0], arr[0], arr[0]);
    exit;
  end;

  var largest := arr[0];
  var secondLargest := arr[0];
  var smallest := arr[0];

  for var i := 1 to arr.Length - 1 do
  begin
    if arr[i] > largest then
    begin
      secondLargest := largest;
      largest := arr[i];
    end
    else if (arr[i] > secondLargest) and (arr[i] <> largest) then
      secondLargest := arr[i];

    if arr[i] < smallest then
      smallest := arr[i];
  end;

  Result := (largest, secondLargest, smallest);
end;

function SubarrayDivisible(nums: array of integer; k: integer): boolean;
begin
  var prefixSum := new Dictionary<integer, integer>;
  prefixSum[0] := -1;
  var currentSum := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    currentSum += nums[i];

    if k <> 0 then
      currentSum := currentSum mod k;

    if prefixSum.ContainsKey(currentSum) then
    begin
      if i - prefixSum[currentSum] > 1 then
      begin
        Result := True;
        exit;
      end;
    end
    else
      prefixSum[currentSum] := i;
  end;

  Result := False;
end;

