function MaxSelection(arr: array of integer): integer;
begin
  var count := new Dictionary<integer, integer>;

  foreach var num in arr do
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count[num] := 1;

  var maxSelection := 0;

  foreach var num in count.Keys do
  begin
    var current := count[num];
    if count.ContainsKey(num + 1) then
      current += count[num + 1];

    if current > maxSelection then
      maxSelection := current;
  end;

  Result := maxSelection;
end;

function FindEquilibriumIndex(arr: array of integer): integer;
begin
  var totalSum := arr.Sum;
  var leftSum := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    totalSum -= arr[i];

    if leftSum = totalSum then
    begin
      Result := i;
      exit;
    end;

    leftSum += arr[i];
  end;

  Result := -1;
end;

function KnightPath(n: integer): int64;
begin
  if n = 1 then
  begin
    Result := 10;
    exit;
  end;

  var modVal := 1000000007;
  var curr := new int64[10];

  for var i := 0 to 9 do
    if i = 5 then
      curr[i] := 0
    else
      curr[i] := 1;

  for var i := 2 to n do
  begin
    var next := new int64[10];
    next[0] := (curr[4] + curr[6]) mod modVal;
    next[1] := (curr[6] + curr[8]) mod modVal;
    next[2] := (curr[7] + curr[9]) mod modVal;
    next[3] := (curr[4] + curr[8]) mod modVal;
    next[4] := (curr[3] + curr[9] + curr[0]) mod modVal;
    next[6] := (curr[1] + curr[7] + curr[0]) mod modVal;
    next[7] := (curr[2] + curr[6]) mod modVal;
    next[8] := (curr[1] + curr[3]) mod modVal;
    next[9] := (curr[2] + curr[4]) mod modVal;
    curr := next;
  end;

  var sum: int64 := 0;
  for var i := 0 to 9 do
    sum := (sum + curr[i]) mod modVal;

  Result := sum;
end;

