type
  TreeNode = auto class
    val: integer;
    left: TreeNode;
    right: TreeNode;
  end;

function BuildBST(nums: array of integer): TreeNode;
begin
  if nums.Length = 0 then
  begin
    Result := nil;
    exit;
  end;

  var root := new TreeNode(nums[0], nil, nil);

  for var i := 1 to nums.Length - 1 do
  begin
    var current := root;

    while True do
    begin
      if nums[i] < current.val then
      begin
        if current.left = nil then
        begin
          current.left := new TreeNode(nums[i], nil, nil);
          break;
        end
        else
          current := current.left;
      end
      else
      begin
        if current.right = nil then
        begin
          current.right := new TreeNode(nums[i], nil, nil);
          break;
        end
        else
          current := current.right;
      end;
    end;
  end;

  Result := root;
end;

function MaxInBST(nums: array of integer): integer;
begin
  var root := BuildBST(nums);
  var current := root;

  while current.right <> nil do
    current := current.right;

  Result := current.val;
end;

