function PartitionEqualSum(nums: array of integer): boolean;
begin
  var totalSum := nums.Sum;

  // If total sum is odd, it cannot be partitioned into two equal sum subsets
  if totalSum mod 2 <> 0 then
  begin
    Result := False;
    exit;
  end;

  var target := totalSum div 2;
  var dp := new boolean[target + 1];
  dp[0] := True;

  // For each number in nums, update dp
  foreach var num in nums do
    for var i := target downto num do
      dp[i] := dp[i] or dp[i - num];

  Result := dp[target];
end;

function BuySellStock(prices: array of integer): integer;
begin
  if prices.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var minPrice := prices[0];
  var maxProfit := 0;

  for var i := 1 to prices.Length - 1 do
  begin
    if prices[i] < minPrice then
      minPrice := prices[i]
    else
    begin
      var profit := prices[i] - minPrice;
      if profit > maxProfit then
        maxProfit := profit;
    end;
  end;

  Result := maxProfit;
end;

function MinUniqueInts(arr: array of integer; n: integer): integer;
begin
  var counts := new Dictionary<integer, integer>;

  foreach var num in arr do
    if counts.ContainsKey(num) then
      counts[num] += 1
    else
      counts[num] := 1;

  var sortedCounts := counts.Values.OrderBy(x -> x).ToList;
  var remaining := n;
  var removed := 0;

  for var i := 0 to sortedCounts.Count - 1 do
  begin
    if sortedCounts[i] <= remaining then
    begin
      remaining -= sortedCounts[i];
      removed += 1;
    end
    else
      break;
  end;

  Result := counts.Count - removed;
end;

function CheckFiniteDecimal(a, b: integer): boolean;
begin
  var denom := b;

  // Simplify fraction by dividing by GCD
  var gcd := GCD(a, b);
  denom := denom div gcd;

  // Remove factors of 2 and 5
  while denom mod 2 = 0 do
    denom := denom div 2;

  while denom mod 5 = 0 do
    denom := denom div 5;

  Result := denom = 1;
end;

