function NumberOfBoats(people: array of integer; limit: integer): integer;
begin
  var answer := 0;
  var sorted := people.ToArray;
  sorted.Sort;

  var left := 0;
  var right := sorted.Length - 1;

  while left <= right do
  begin
    if left = right then
    begin
      answer += 1;
      break;
    end;

    if sorted[left] + sorted[right] <= limit then
    begin
      left += 1;
      right -= 1;
    end
    else
      right -= 1;

    answer += 1;
  end;

  Result := answer;
end;

