function ChunkArray(numList: array of integer; n: integer): array of array of integer?;
begin
  var chunks := new List<array of integer?>;
  var temp := new List<integer?>;

  for var i := 0 to numList.Length - 1 do
  begin
    temp.Add(numList[i]);

    if (i + 1) mod n = 0 then
    begin
      chunks.Add(temp.ToArray);
      temp.Clear;
    end;
  end;

  if temp.Count > 0 then
  begin
    while temp.Count < n do
      temp.Add(nil);

    chunks.Add(temp.ToArray);
  end;

  Result := chunks.ToArray;
end;

function IsVowelPalindrome(s: string): boolean;
