    if vowels.Contains(ch) then
      foundVowels.Add(ch);
    cleaned.Append(ch);
  end;

  var cleanedStr := cleaned.ToString;
  var isPalindrome := cleanedStr = cleanedStr.Inverse;
  var allVowelsFound := foundVowels.Count = 5;

  Result := isPalindrome and allVowelsFound;
end;

function GetNext(n: integer): integer;
begin
  var totalSum := 0;
  var num := n;

  while num > 0 do
  begin
    var digit := num mod 10;
    totalSum += digit * digit;
    num := num div 10;
  end;

  Result := totalSum;
end;

function HappyNumber(number: integer): boolean;
begin
  var seen := new HashSet<integer>;
  var current := number;

  while not seen.Contains(current) do
  begin
    seen.Add(current);
    current := GetNext(current);

    if current = 1 then
    begin
      Result := True;
      exit;
    end;
  end;

  Result := False;
end;

