    permSourceArray: array of integer;

procedure GeneratePermutations(current: List<integer>; used: HashSet<integer>);
begin
  if current.Count = permSourceArray.Length then
  begin
    permResults.Add(current.ToArray);
    exit;
  end;

  for var i := 0 to permSourceArray.Length - 1 do
  begin
    if not used.Contains(i) then
    begin
      used.Add(i);
      current.Add(permSourceArray[i]);
      GeneratePermutations(current, used);
      current.RemoveAt(current.Count - 1);
      used.Remove(i);
    end;
  end;
end;

