end;

function MinBurnTime(edges: array of (integer, integer, integer); startNode: integer): integer;
begin
  var graph := new Dictionary<integer, List<(integer, integer)>>;

  // Build graph
  foreach var (u, v, time) in edges do
  begin
    if not graph.ContainsKey(u) then
      graph[u] := new List<(integer, integer)>;
    if not graph.ContainsKey(v) then
      graph[v] := new List<(integer, integer)>;

    graph[u].Add((v, time));
    graph[v].Add((u, time));
  end;

  // BFS to find maximum distance from startNode
  var queue := new Queue<(integer, integer)>;
  var visited := new HashSet<integer>;
  var time := new Dictionary<integer, integer>;

  queue.Enqueue((startNode, 0));
  visited.Add(startNode);
  time[startNode] := 0;

  while queue.Count > 0 do
  begin
    var (node, currentTime) := queue.Dequeue;

    if graph.ContainsKey(node) then
    begin
      foreach var (neighbor, edgeTime) in graph[node] do
      begin
        if not visited.Contains(neighbor) then
        begin
          visited.Add(neighbor);
          time[neighbor] := currentTime + edgeTime;
          queue.Enqueue((neighbor, currentTime + edgeTime));
        end;
      end;
    end;
  end;

  // Find maximum time
  var maxTime := 0;
  foreach var kv in time do
    if kv.Value > maxTime then
      maxTime := kv.Value;

  Result := maxTime;
end;

