function FindSubArrays(A: array of integer; target: integer): integer;
begin
  var count := 0;
  var currSum := 0;
  var hashMap := new Dictionary<integer, integer>;
  hashMap[0] := 1;

  foreach var num in A do
  begin
    currSum += num;

    if hashMap.ContainsKey(currSum - target) then
      count += hashMap[currSum - target];

    if hashMap.ContainsKey(currSum) then
      hashMap[currSum] += 1
    else
      hashMap[currSum] := 1;
  end;

  Result := count;
end;

function CountUniqueBST(n: integer): int64;
begin
  if (n = 0) or (n = 1) then
  begin
    Result := 1;
    exit;
  end;

  var total: int64 := 0;

  for var i := 1 to n do
    total += CountUniqueBST(i - 1) * CountUniqueBST(n - i);

  Result := total;
end;

function ExpandAroundCenter(s: string; left, right: integer): integer;
begin
  var count := 0;
  var l := left;
  var r := right;

  while (l >= 1) and (r <= s.Length) and (s[l] = s[r]) do
  begin
    count += 1;
    l -= 1;
    r += 1;
  end;

  Result := count;
end;

function CountPalindromes(s: string): integer;
begin
  var totalCount := 0;

  for var i := 1 to s.Length do
  begin
    // Odd length palindromes
    totalCount += ExpandAroundCenter(s, i, i);
    // Even length palindromes
    if i < s.Length then
      totalCount += ExpandAroundCenter(s, i, i + 1);
  end;

  Result := totalCount;
end;

function LengthOfLongestNonRepeatSubstring(s: string): integer;
begin
  var maxLen := 0;
  var start := 1;
  var seen := new HashSet<char>;

  for var &end := 1 to s.Length do
  begin
    var ch := s[&end];

    while seen.Contains(ch) do
    begin
      seen.Remove(s[start]);
      start += 1;
    end;

    seen.Add(ch);
    maxLen := Max(maxLen, &end - start + 1);
  end;

  Result := maxLen;
end;

function CountReversePairs(lst: array of string): integer;
begin
  var seen := new HashSet<string>;
  var count := 0;

  foreach var s in lst do
  begin
    var reverseS := s.Inverse;

    if seen.Contains(reverseS) then
      count += 1;

    seen.Add(s);
  end;

  Result := count;
end;

