function TripletProduct(arr: array of integer): int64;
begin
  var sorted := arr.ToArray;
  sorted.Sort;
  var n := sorted.Length;

  var product1 := int64(sorted[0]) * sorted[1] * sorted[n-1];
  var product2 := int64(sorted[n-1]) * sorted[n-2] * sorted[n-3];

  Result := Max(product1, product2);
end;

type
  NumMatrix = class
  private
    dp: array[,] of integer;
  public
    constructor Create(matrix: array[,] of integer);
    begin
      if (matrix.Length = 0) then
        exit;

      var rows := matrix.GetLength(0);
      var cols := matrix.GetLength(1);
      dp := new integer[rows, cols];

      // Initialize 0,0
      dp[0, 0] := matrix[0, 0];

      // Initialize first row
      for var j := 1 to cols - 1 do
        dp[0, j] := dp[0, j-1] + matrix[0, j];

      // Initialize first column
      for var i := 1 to rows - 1 do
        dp[i, 0] := dp[i-1, 0] + matrix[i, 0];

      for var i := 1 to rows - 1 do
        for var j := 1 to cols - 1 do
          dp[i, j] := dp[i-1, j] + dp[i, j-1] - dp[i-1, j-1] + matrix[i, j];
    end;

    function SumRegion(row1, col1, row2, col2: integer): integer;
    begin
      if row1 = 0 then
      begin
        if col1 = 0 then
          Result := dp[row2, col2]
        else
          Result := dp[row2, col2] - dp[row2, col1-1];
      end
      else if col1 = 0 then
        Result := dp[row2, col2] - dp[row1-1, col2]
      else
        Result := dp[row2, col2] - dp[row2, col1-1] - dp[row1-1, col2] + dp[row1-1, col1-1];
    end;
  end;

function SumRegion(matrix: array[,] of integer; row1, col1, row2, col2: integer): integer;
begin
  var obj := new NumMatrix(matrix);
  Result := obj.SumRegion(row1, col1, row2, col2);
end;

function FindMaxAnagrams(words: array of string): string;
begin
  var anagramGroups := new Dictionary<string, List<string>>;

  foreach var word in words do
  begin
    var chars := word.ToCharArray;
    &Array.Sort(chars);
    var sortedWord := new string(chars);

    if not anagramGroups.ContainsKey(sortedWord) then
      anagramGroups[sortedWord] := new List<string>;

    anagramGroups[sortedWord].Add(word);
  end;

  var maxLength := 0;
  var maxAnagram := '';

  foreach var group in anagramGroups.Values do
    if group.Count > maxLength then
    begin
      maxLength := group.Count;
      maxAnagram := group[0];
    end;

  Result := maxAnagram;
end;

function CountSingleCharSubstrings(s: string): integer;
begin
