  var currentChar := #0;
  var currentCount := 0;

  for var i := 1 to s.Length do
  begin
    if s[i] = currentChar then
      currentCount += 1
    else
    begin
      if currentChar <> #0 then
        totalCount += currentCount * (currentCount + 1) div 2;
      currentChar := s[i];
      currentCount := 1;
    end;
  end;

  if currentChar <> #0 then
    totalCount += currentCount * (currentCount + 1) div 2;

  Result := totalCount;
end;

function CountCoinCombinations(amount: integer; coins: array of integer): int64;
begin
  var dp := new int64[amount + 1];
  dp[0] := 1;

  foreach var coin in coins do
    for var x := coin to amount do
      dp[x] += dp[x - coin];

  Result := dp[amount];
end;

var graphDFS: array of List<integer>;

function Dfs(node, parent: integer; var visited: array of boolean): boolean;
begin
  visited[node] := True;

  foreach var neighbor in graphDFS[node] do
  begin
    if not visited[neighbor] then
    begin
      if Dfs(neighbor, node, visited) then
      begin
        Result := True;
        exit;
      end;
    end
    else if neighbor <> parent then
    begin
      Result := True;
      exit;
    end;
  end;

  Result := False;
end;

function DetectCycleUndirected(n: integer; edges: array of (integer, integer); vertexCount, edgeCount: integer): boolean;
begin
  graphDFS := new List<integer>[vertexCount + 1];
  for var i := 0 to vertexCount do
    graphDFS[i] := new List<integer>;

  foreach var (u, v) in edges do
  begin
    graphDFS[u].Add(v);
    graphDFS[v].Add(u);
  end;

  var visited := new boolean[vertexCount + 1];

  for var i := 1 to vertexCount do
    if not visited[i] then
      if Dfs(i, -1, visited) then
      begin
        Result := True;
        exit;
      end;

  Result := False;
end;

function WaterTrapped(height: array of integer): integer;
begin
  if height.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var leftMax := new integer[height.Length];
  var rightMax := new integer[height.Length];
  var water := 0;

  leftMax[0] := height[0];
  for var i := 1 to height.Length - 1 do
    leftMax[i] := Max(leftMax[i-1], height[i]);

  rightMax[height.Length - 1] := height[height.Length - 1];
  for var i := height.Length - 2 downto 0 do
    rightMax[i] := Max(rightMax[i+1], height[i]);

  for var i := 0 to height.Length - 1 do
    water += Min(leftMax[i], rightMax[i]) - height[i];

  Result := water;
end;

function MaxSubarrayProduct(nums: array of integer): int64;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var maxProd := int64(nums[0]);
  var minProd := int64(nums[0]);
  var overallMax := int64(nums[0]);

  for var i := 1 to nums.Length - 1 do
  begin
    var temp := maxProd;
    maxProd := Max(int64(nums[i]), Max(maxProd * nums[i], minProd * nums[i]));
    minProd := Min(int64(nums[i]), Min(temp * nums[i], minProd * nums[i]));
    overallMax := Max(overallMax, maxProd);
  end;

  Result := overallMax;
end;

