function ArrangeByFreq(arr: array of integer): array of integer;
begin
  var freq := new Dictionary<integer, integer>;

  foreach var num in arr do
    if freq.ContainsKey(num) then
      freq[num] += 1
    else
      freq[num] := 1;

  var list := arr.ToList;
  list.Sort((x, y) -> 
  begin
    if freq[x] <> freq[y] then
      Result := freq[y].CompareTo(freq[x])
    else
      Result := x.CompareTo(y);
  end);

  Result := list.ToArray;
end;

function SubarrayTargetSum(nums: array of integer; target: integer): integer;
begin
  var hashMap := new Dictionary<integer, integer>;
  hashMap[0] := 1;

  var cumSum := 0;
  var ans := 0;

  foreach var num in nums do
  begin
    cumSum += num;

    if hashMap.ContainsKey(cumSum - target) then
      ans += hashMap[cumSum - target];

    if hashMap.ContainsKey(cumSum) then
      hashMap[cumSum] += 1
    else
      hashMap[cumSum] := 1;
  end;

  Result := ans;
end;

function ConsecutiveSum(target: integer): integer;
begin
  var ways := 0;
  var i := 1;

  while target > i * (i - 1) div 2 do
  begin
    if (target - i * (i - 1) div 2) mod i = 0 then
      ways += 1;
    i += 1;
  end;

  Result := ways;
end;

procedure Dfs(grid: array[,] of integer; i, j: integer);
begin
  if (i < 0) or (j < 0) or (i >= grid.GetLength(0)) or (j >= grid.GetLength(1)) or (grid[i, j] <> 1) then
    exit;

  grid[i, j] := 0;
  Dfs(grid, i+1, j);
  Dfs(grid, i-1, j);
  Dfs(grid, i, j+1);
  Dfs(grid, i, j-1);
end;

function CountIslands(grid: array[,] of integer): integer;
begin
  var count := 0;

  for var i := 0 to grid.GetLength(0) - 1 do
    for var j := 0 to grid.GetLength(1) - 1 do
      if grid[i, j] = 1 then
      begin
        Dfs(grid, i, j);
        count += 1;
      end;

  Result := count;
end;

function FindTwoSum(numbers: array of integer; target: integer): array of integer;
begin
  var numDict := new Dictionary<integer, integer>;

  for var i := 0 to numbers.Length - 1 do
  begin
    var complement := target - numbers[i];

    if numDict.ContainsKey(complement) then
    begin
      Result := [numDict[complement], i];
      exit;
    end;

    numDict[numbers[i]] := i;
  end;

  Result := new integer[0]; // Empty array indicates not found
end;

function DecimalToBase5(num: integer): string;
begin
  if num = 0 then
  begin
    Result := '0';
    exit;
  end;

  var digits := '01234';
  var n := Abs(num);
  var s := new StringBuilder;

  while n > 0 do
  begin
    s.Insert(0, digits[n mod 5 + 1]);
    n := n div 5;
  end;

  if num < 0 then
    s.Insert(0, '-');

  Result := s.ToString;
end;

function MinimumSum(num: integer): integer;
begin
  var digits := new List<integer>;
  var n := Abs(num);

  while n > 0 do
  begin
    digits.Add(n mod 10);
    n := n div 10;
  end;

  digits.Sort;

  if digits.Count < 4 then
  begin
    Result := -1;
    exit;
  end;

  var num1 := digits[0] * 10 + digits[2];
  var num2 := digits[1] * 10 + digits[3];

  Result := num1 + num2;
end;

function FindMostFrequentCharacter(s: string): char;
