  for var i := 1 to s.Length do
    if charCount.ContainsKey(s[i]) then
      charCount[s[i]] += 1
    else
      charCount[s[i]] := 1;

  var maxCount := 0;
  var mostFrequentChar := s[1];

  foreach var kv in charCount do
    if kv.Value > maxCount then
    begin
      maxCount := kv.Value;
      mostFrequentChar := kv.Key;
    end;

  Result := mostFrequentChar;
end;

function KWeakestRows(mat: array of array of integer; k: integer): array of integer;
begin
  var m := mat.Length;
  var n := mat[0].Length;
  var strength := new List<integer>;
  var indices := new List<integer>;

  for var i := 0 to m - 1 do
  begin
    var count := 0;
    for var j := 0 to n - 1 do
      if mat[i][j] = 1 then
        count += 1;

    strength.Add(count);
    indices.Add(i);
  end;

  // Sort indices by strength
  var pairs := new List<(integer, integer)>;
  for var i := 0 to m - 1 do
    pairs.Add((strength[i], indices[i]));

  pairs.Sort((x, y) -> begin
    if x.Item1 <> y.Item1 then
       Result := x.Item1.CompareTo(y.Item1)
    else
      Result := x.Item2.CompareTo(y.Item2) end);

