  var n := s.Length;
  var dp := new integer[n + 1];
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
  begin
    var single := StrToInt(s.Substring(i-1, 1));
    var double_ := StrToInt(s.Substring(i-2, 2));

    if (single >= 1) and (single <= 9) then
      dp[i] += dp[i-1];

    if (double_ >= 10) and (double_ <= 26) then
      dp[i] += dp[i-2];
  end;

  Result := dp[n];
end;

