function MinPathCost(grid: array of array of integer): integer;
begin
  if (grid.Length = 0) or (grid[0].Length = 0) then
  begin
    Result := 0;
    exit;
  end;

  var m := grid.Length;
  var n := grid[0].Length;

  // Create a copy of the grid to avoid modifying the original
  var dp := new integer[m, n];
  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      dp[i, j] := grid[i][j];

  // Initialize first row
  for var j := 1 to n - 1 do
    dp[0, j] := dp[0, j] + dp[0, j-1];

  // Initialize first column
  for var i := 1 to m - 1 do
    dp[i, 0] := dp[i, 0] + dp[i-1, 0];

  for var i := 1 to m - 1 do
    for var j := 1 to n - 1 do
      dp[i, j] := dp[i, j] + Min(dp[i-1, j], dp[i, j-1]);

  Result := dp[m-1, n-1];
end;

