function LongSubstringLength(s: string; k: integer): integer;
begin
  var count := new Dictionary<char, integer>;
  var maxLen := 0;
  var left := 1;

  for var right := 1 to s.Length do
  begin
    if count.ContainsKey(s[right]) then
      count[s[right]] += 1
    else
      count[s[right]] := 1;

    while count.Count > k do
    begin
      count[s[left]] -= 1;
      if count[s[left]] = 0 then
        count.Remove(s[left]);
      left += 1;
    end;

    maxLen := Max(maxLen, right - left + 1);
  end;

  Result := maxLen;
end;

