  var n := nums.Length;
  var dp := new boolean[n + 1, k + 1];

  for var i := 0 to n do
    dp[i, 0] := True;

  for var i := 1 to n do
    for var j := 1 to k do
      if nums[i-1] <= j then
        dp[i, j] := dp[i-1, j] or dp[i-1, j - nums[i-1]]
      else
        dp[i, j] := dp[i-1, j];

  Result := dp[n, k];
end;

function FindLongestSubstringWithKUniqueChars(s: string; k: integer): string;
begin
  var ans := '';
  var left := 1;
  var lastOccurrence := new Dictionary<char, integer>;
  var uniqueCount := 0;

  for var right := 1 to s.Length do
  begin
    var nextChar := s[right];

    if lastOccurrence.ContainsKey(nextChar) then
      lastOccurrence[nextChar] := right
    else
    begin
      uniqueCount += 1;
      lastOccurrence[nextChar] := right;

      while uniqueCount > k do
      begin
        var backChar := s[left];
        if left = lastOccurrence[backChar] then
        begin
          uniqueCount -= 1;
          lastOccurrence.Remove(backChar);
        end;
        left += 1;
      end;
    end;

    var currentSubstr := s.Substring(left - 1, right - left + 1);
    if currentSubstr.Length > ans.Length then
      ans := currentSubstr;
  end;

  if uniqueCount <> k then
    Result := 'Error'
  else
    Result := ans;
end;

function Enough(arr: array of integer; k, threshold: integer): boolean;
begin
  var count := 1;
  var currentSum := 0;

  foreach var num in arr do
  begin
    if currentSum + num > threshold then
    begin
      currentSum := num;
      count += 1;
      if count > k then
      begin
        Result := False;
        exit;
      end;
    end
    else
      currentSum += num;
  end;

  Result := True;
end;

function MinimumLargestValue(arr: array of integer; k: integer): integer;
begin
  var low := arr.Max;
  var high := arr.Sum;

  while low < high do
  begin
    var mid := (low + high) div 2;

    if Enough(arr, k, mid) then
      high := mid
    else
      low := mid + 1;
  end;

  Result := low;
end;

