function ConveyorBelt(matrix: array of string; start, &end: array of integer): integer;
begin
  var R := matrix.Length;
  var C := matrix[0].Length;
  var dirs := |(0, 1), (0, -1), (1, 0), (-1, 0)|;
  var signals := |'>', '<', 'v', '^'|;
  var distances := new integer[R, C];

  for var i := 0 to R - 1 do
    for var j := 0 to C - 1 do
      distances[i, j] := MaxInt;

  // Min-heap priority queue using List
  var pq := new List<(integer, integer, integer)>;
  pq.Add((0, start[0], start[1]));

  while pq.Count > 0 do
  begin
    pq.Sort((x, y) -> x.Item1.CompareTo(y.Item1));
    var (dis, row, col) := pq[0];
    pq.RemoveAt(0);

    if (row = &end[0]) and (col = &end[1]) then
    begin
      Result := dis;
      exit;
    end;

    for var idx := 0 to 3 do
    begin
      var (dr, dc) := dirs[idx];
      var nr := row + dr;
      var nc := col + dc;

      if (nr >= 0) and (nr < R) and (nc >= 0) and (nc < C) then
      begin
        var w := 0;
        var signalIdx := signals.IndexOf(matrix[r][c]);
        if signalIdx <> idx then
          w := 1;

        if dis + w < distances[nr, nc] then
        begin
          distances[nr, nc] := dis + w;
          pq.Add((dis + w, nr, nc));
        end;
      end;
    end;
  end;

  Result := -1;
end;

