    exit;
  end;

  var ans := new List<integer>;
  var total := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    total += nums[i];

    if i >= k then
      total -= nums[i - k];

    if i >= k - 1 then
      ans.Add(total);
  end;

  Result := ans.ToArray;
end;

