  var squares := new List<integer>;

  for var i := 1 to Trunc(Sqrt(n)) do
    squares.Add(i * i);

  var dp := new integer[n + 1];

  for var i := 1 to n do
    dp[i] := MaxInt;

  dp[0] := 0;

  for var i := 1 to n do
    foreach var sq in squares do
      if i >= sq then
        dp[i] := Min(dp[i], dp[i - sq] + 1);

  Result := dp[n];
end;

