function NumPairsDivisibleBy60(nums: array of integer): integer;
begin
  var a := 0;
  var arr := new integer[nums.Length];

  for var i := 0 to nums.Length - 1 do
    arr[i] := nums[i] mod 60;

  var dict := new Dictionary<integer, integer>;

  for var i := 0 to arr.Length - 1 do
  begin
    var req := (60 - arr[i]) mod 60;

    if dict.ContainsKey(req) then
      a += dict[req];

    if dict.ContainsKey(arr[i]) then
      dict[arr[i]] += 1
    else
      dict[arr[i]] := 1;
  end;

  Result := a;
end;

function CanDivideIntoGroups(nums: array of integer; k: integer): boolean;
begin
  var dict := new Dictionary<integer, integer>;

  foreach var num in nums do
    if dict.ContainsKey(num) then
      dict[num] += 1
    else
      dict[num] := 1;

  var sorted := dict.Keys.ToList;
  sorted.Sort;

  foreach var val in sorted do
  begin
    var cnt := dict[val];

    if cnt > 0 then
    begin
      for var inc := 0 to k - 1 do
      begin
        if not dict.ContainsKey(val + inc) or (dict[val + inc] < cnt) then
        begin
          Result := False;
          exit;
        end;
        dict[val + inc] -= cnt;
      end;
    end;
  end;

  Result := True;
end;

