function NumberOfArithmeticSlices(A: array of integer): integer;
begin
  var n := A.Length;
  var dp := new Dictionary<integer, integer>[n];
  for var i := 0 to n - 1 do
    dp[i] := new Dictionary<integer, integer>;

  var total := 0;

  for var i := 0 to n - 1 do
    for var j := 0 to i - 1 do
    begin
      var diff := int64(A[i]) - A[j];
      if diff < -1000000000 then diff := -1000000000;
      if diff > 1000000000 then diff := 1000000000;

      var diffKey := integer(diff);
      var prev := 0;
      if dp[j].ContainsKey(diffKey) then
        prev := dp[j][diffKey];

      if dp[i].ContainsKey(diffKey) then
        dp[i][diffKey] := dp[i][diffKey] + prev + 1
      else
        dp[i][diffKey] := prev + 1;

      total += prev;
    end;

  Result := total;
end;

type
  TreeNode = auto class
    val: integer;
    left: TreeNode;
    right: TreeNode;
  end;

function LevelOrderSum(root: TreeNode): array of integer;
begin
  if root = nil then
  begin
    Result := new integer[0];
    exit;
  end;

  var levelSums := new List<integer>;
  var queue := new Queue<TreeNode>;
  queue.Enqueue(root);

  while queue.Count > 0 do
  begin
    var levelSize := queue.Count;
    var levelSum := 0;

    for var i := 1 to levelSize do
    begin
      var node := queue.Dequeue;
      levelSum += node.val;

      if node.left <> nil then
        queue.Enqueue(node.left);
      if node.right <> nil then
        queue.Enqueue(node.right);
    end;

    levelSums.Add(levelSum);
  end;

  Result := levelSums.ToArray;
end;

