function IsValidBracketString(s: string): boolean;
begin
  var stack := new Stack<char>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];

    if (ch = '{') or (ch = '[') or (ch = '(') then
      stack.Push(ch)
    else if stack.Count > 0 then
    begin
      var top := stack.Peek;
      if ((top = '(') and (Ord(top) + 1 = Ord(ch))) or 
         ((top = '[') and (Ord(top) + 2 = Ord(ch))) or
         ((top = '{') and (Ord(top) + 2 = Ord(ch))) then
        stack.Pop
      else
      begin
        Result := False;
        exit;
      end;
    end
    else
    begin
      Result := False;
      exit;
    end;
  end;

  Result := stack.Count = 0;
end;

