var remainingArray: array of boolean;
var AGlobal: array of integer;
var targetSum: integer;

function FindPartition(start: integer; remainingSum: integer; remainingPartitions: integer): boolean;
begin
  if remainingPartitions = 1 then
  begin
    Result := True;
    exit;
  end;

  if remainingSum = targetSum then
  begin
    Result := FindPartition(0, 0, remainingPartitions - 1);
    exit;
  end;

  for var i := start to AGlobal.Length - 1 do
  begin
    if (not remainingArray[i]) and (remainingSum + AGlobal[i] <= targetSum) then
    begin
      remainingArray[i] := True;
      if FindPartition(i + 1, remainingSum + AGlobal[i], remainingPartitions) then
      begin
        Result := True;
        exit;
      end;
      remainingArray[i] := False;
    end;
  end;

  Result := False;
end;

function CanKPartitions(A: array of integer; K: integer): boolean;
begin
  var totalSum := A.Sum;

  if totalSum mod K <> 0 then
  begin
    Result := False;
    exit;
  end;

  targetSum := totalSum div K;
  remainingArray := new boolean[A.Length];
  AGlobal := A;

  Result := FindPartition(0, 0, K);
end;

function LongestSubarray1s(nums: array of integer): integer;
begin
  var left := 0;
  var right := 0;
  var length := nums.Length;
  var zeros := 0;
  var maxRes := 0;

  while right < length do
  begin
    if nums[right] = 0 then
      zeros += 1;

    while zeros > 1 do
    begin
      if nums[left] = 0 then
        zeros -= 1;
      left += 1;
    end;

    if right - left > maxRes then
      maxRes := right - left;

    right += 1;
  end;

  Result := maxRes;
end;

function FindLargestSmaller(arr: array of integer; target: integer): integer;
begin
  var sorted := arr.ToArray;
  sorted.Sort;

  for var i := sorted.Length - 1 downto 0 do
    if sorted[i] < target then
