function MinRotations(s: string): integer;
begin
  var n := s.Length;
  var rotations := 1;
  var temp := s;

  while rotations <= n do
  begin
    temp := temp.Substring(temp.Length - 1) + temp.Substring(0, temp.Length - 1);
    if temp = s then
    begin
      Result := rotations;
      exit;
    end;
    rotations += 1;
  end;

  Result := n;
end;

