function BinarySearchRecursive(arr: array of integer; target: integer; low: integer := 0; high: integer := -1): integer;
begin
  if high = -1 then
    high := arr.Length - 1;

  if low > high then
  begin
    Result := -1;
    exit;
  end;

  var mid := (low + high) div 2;

  if arr[mid] = target then
    Result := mid
  else if arr[mid] > target then
    Result := BinarySearchRecursive(arr, target, low, mid - 1)
  else
    Result := BinarySearchRecursive(arr, target, mid + 1, high);
end;

function NumDiffInt(word: string): integer;
begin
  var n := word.Length;
  var count := new HashSet<integer>;
  var i := 1;

  while i <= n do
  begin
    while (i <= n) and not Char.IsDigit(word[i]) do
      i += 1;

    var j := i;
    while (j <= n) and Char.IsDigit(word[j]) do
      j += 1;

    if i <> j then
    begin
      var numStr := word.Substring(i-1, j-i);
      // Remove leading zeros
      var k := 1;
      while (k <= numStr.Length) and (numStr[k] = '0') do
        k += 1;

      if k <= numStr.Length then
        numStr := numStr.Substring(k-1)
      else
        numStr := '0';

      var num := StrToInt(numStr);
      count.Add(num);
    end;

    i := j;
  end;

  Result := count.Count;
end;

function FindQuadruplets(nums: array of integer; n: integer): array of array of integer;
begin
  var sorted := nums.ToArray;
  sorted.Sort;
  var quadruplets := new List<array of integer>;

  for var i := 0 to sorted.Length - 4 do
  begin
    if (i > 0) and (sorted[i] = sorted[i-1]) then
      continue;

    for var j := i + 1 to sorted.Length - 3 do
    begin
      if (j > i + 1) and (sorted[j] = sorted[j-1]) then
        continue;

      var left := j + 1;
      var right := sorted.Length - 1;

      while left < right do
      begin
        var sum := sorted[i] + sorted[j] + sorted[left] + sorted[right];

        if sum < 0 then
          left += 1
        else if sum > 0 then
          right -= 1
        else
        begin
          quadruplets.Add(|sorted[i], sorted[j], sorted[left], sorted[right]|);

          while (left < right) and (sorted[left] = sorted[left + 1]) do
            left += 1;
          while (left < right) and (sorted[right] = sorted[right - 1]) do
            right -= 1;

          left += 1;
          right -= 1;
        end;
      end;
    end;
  end;

  Result := quadruplets.ToArray;
end;

var taskUsed: array of boolean;
    taskEnergy: integer;
    taskItems: array of (integer, integer);
    taskMaxCompleted: integer;
    taskN: integer;

procedure BacktrackTasks(currentEnergy: integer; count: integer);
begin
  if count > taskMaxCompleted then
    taskMaxCompleted := count;

  for var i := 0 to taskN - 1 do
  begin
    if not taskUsed[i] then
    begin
      var (requiredEnergy, energyCost) := taskItems[i];
      if currentEnergy >= requiredEnergy then
      begin
        taskUsed[i] := True;
        BacktrackTasks(currentEnergy - energyCost, count + 1);
        taskUsed[i] := False;
      end;
    end;
  end;
end;

function MaxCompletedTasks(energy: integer; tasks: array of (integer, integer)): integer;
begin
  taskMaxCompleted := 0;
  taskN := tasks.Length;
  taskUsed := new boolean[taskN];
  taskEnergy := energy;
  taskItems := tasks;

  BacktrackTasks(energy, 0);
  Result := taskMaxCompleted;
end;

function GetSublists<T>(lst: array of T): array of array of T;
begin
  var subarrays := new List<array of T>;

  for var i := 0 to lst.Length - 1 do
    for var j := i to lst.Length - 1 do
    begin
      var subarray := new T[j - i + 1];
      for var k := i to j do
        subarray[k - i] := lst[k];
      subarrays.Add(subarray);
    end;

  Result := subarrays.ToArray;
end;

