end;

function LeastIntervals(tasks: array of string; n: integer): integer;
begin
  var counter := new Dictionary<string, integer>;

  foreach var t in tasks do
    if counter.ContainsKey(t) then
      counter[t] += 1
    else
      counter[t] := 1;

  var maxCount := 0;
  var maxFreq := 0;

  foreach var kv in counter do
  begin
    if kv.Value > maxCount then
    begin
      maxCount := kv.Value;
      maxFreq := 1;
    end
    else if kv.Value = maxCount then
      maxFreq += 1;
  end;

  Result := Max(tasks.Length, (maxCount - 1) * (n + 1) + maxFreq);
end;

