  for var i := 0 to listOfLists.Length - 1 do
  begin
    var sum := listOfLists[i].Sum;
    if sum > maxSum then
    begin
      maxSum := sum;
      maxIndex := i;
    end;
  end;

  Result := listOfLists[maxIndex];
end;

