function MaxMinStack(arr: array of integer): (integer, integer);
begin
  var stack := new Stack<integer>;

  if arr.Length = 0 then
  begin
    Result := (0, 0);
    exit;
  end;

  var maxVal := arr[0];
  var minVal := arr[0];

  foreach var num in arr do
  begin
    stack.Push(num);
    if num > maxVal then
      maxVal := num
    else if num < minVal then
      minVal := num;
  end;

  Result := (maxVal, minVal);
end;

function FindFirstAndLast(nums: array of integer; target: integer): array of integer;
begin
  if nums.Length = 0 then
  begin
    Result := |-1, -1|;
    exit;
  end;

  var left := 0;
  var right := nums.Length - 1;
  var first := -1;
  var last := -1;

  // Find first occurrence
  while left <= right do
  begin
    var mid := (left + right) div 2;
    if nums[mid] < target then
      left := mid + 1
    else if nums[mid] > target then
      right := mid - 1
    else
    begin
      first := mid;
      right := mid - 1;
    end;
  end;

  if first = -1 then
  begin
    Result := |-1, -1|;
    exit;
  end;

  // Find last occurrence
  left := first;
  right := nums.Length - 1;

  while left <= right do
  begin
    var mid := (left + right) div 2;
    if nums[mid] < target then
      left := mid + 1
    else if nums[mid] > target then
      right := mid - 1
    else
    begin
      last := mid;
      left := mid + 1;
    end;
  end;

  Result := |first, last|;
end;

function IntersectionSumDicts<K, V>(dict1, dict2: Dictionary<K, V>): Dictionary<K, V>;
begin
  var intersection := new Dictionary<K, V>;

  foreach var kv in dict1 do
    if dict2.ContainsKey(kv.Key) then
    begin
      // This requires that V supports addition
      // For numeric types, we can use dynamic
      var val1 := kv.Value;
      var val2 := dict2[kv.Key];
      // Assuming V is numeric, we use Convert
      var sum := Convert.ChangeType(
        Convert.ToDouble(val1) + Convert.ToDouble(val2), 
        typeof(V)
      );
      intersection[kv.Key] := V(sum);
    end;

  Result := intersection;
end;

