function IsLexicoSorted(words: array of string; order: string): boolean;
begin
  var mapping := new Dictionary<char, integer>;

  for var i := 1 to order.Length do
    mapping[order[i]] := i - 1;

  for var i := 1 to words.Length - 1 do
  begin
    var prev := words[i-1];
    var cur := words[i];
    var minLen := Min(prev.Length, cur.Length);

    // Check if prev is prefix of cur and prev is longer
    if (prev.Substring(0, minLen) = cur.Substring(0, minLen)) and (prev.Length > cur.Length) then
    begin
      Result := False;
      exit;
    end;

    for var j := 1 to minLen do
    begin
      var p := mapping[prev[j]];
      var c := mapping[cur[j]];

      if p < c then
        break
      else if p > c then
      begin
        Result := False;
        exit;
      end;
    end;
  end;

  Result := True;
end;

function CanDivideIntoConsecutiveSubsequences(nums: array of integer): boolean;
begin
  var countMap := new Dictionary<integer, integer>;
  var endMap := new Dictionary<integer, integer>;

  foreach var x in nums do
    if countMap.ContainsKey(x) then
      countMap[x] += 1
    else
      countMap[x] := 1;

  foreach var x in nums do
  begin
    if countMap[x] > 0 then
    begin
      if endMap.ContainsKey(x - 1) and (endMap[x - 1] > 0) then
      begin
        countMap[x] -= 1;
        endMap[x - 1] -= 1;
        if endMap.ContainsKey(x) then
          endMap[x] += 1
        else
          endMap[x] := 1;
      end
      else
      begin
        if (countMap.Get(x + 1, 0) > 0) and (countMap.Get(x + 2, 0) > 0) then
        begin
          countMap[x] -= 1;
          countMap[x + 1] -= 1;
          countMap[x + 2] -= 1;
          if endMap.ContainsKey(x + 2) then
            endMap[x + 2] += 1
          else
            endMap[x + 2] := 1;
        end
        else
        begin
          Result := False;
          exit;
        end;
      end;
    end;
  end;

  Result := True;
end;

