function DailyTemperatures(temperatures: array of integer): array of integer;
begin
  var answer := new integer[temperatures.Length];
  var stack := new Stack<integer>;

  for var idx := 0 to temperatures.Length - 1 do
  begin
    while (stack.Count > 0) and (temperatures[stack.Peek] < temperatures[idx]) do
    begin
      var last := stack.Pop;
      answer[last] := idx - last;
    end;
    stack.Push(idx);
  end;

  Result := answer;
end;

