end;

function CheckWays(pairs: array of (integer, integer)): integer;
begin
  if pairs.Length = 1 then
  begin
    Result := 2;
    exit;
  end;

  var ancestorDict := new Dictionary<integer, HashSet<integer>>;

  foreach var (u, v) in pairs do
  begin
    if not ancestorDict.ContainsKey(u) then
      ancestorDict[u] := new HashSet<integer>;
    if not ancestorDict.ContainsKey(v) then
      ancestorDict[v] := new HashSet<integer>;

    ancestorDict[u].Add(v);
    ancestorDict[v].Add(u);
  end;

  var possibleRoot := new List<integer>;

  foreach var kv in ancestorDict do
    if kv.Value.Count = ancestorDict.Count - 1 then
      possibleRoot.Add(kv.Key);

  if possibleRoot.Count = 0 then
  begin
    Result := 0;
    exit;
  end;

  var rootNode := possibleRoot[0];
  var res := 1;

  foreach var kv in ancestorDict do
  begin
    if kv.Key = rootNode then
      continue;

    var curAncestorNodeLen := kv.Value.Count;
    var parentNode := -1;
    var parentAncestorNodeLen := MaxInt;

    foreach var ancestorNode in kv.Value do
    begin
      if (curAncestorNodeLen <= ancestorDict[ancestorNode].Count) and 
         (ancestorDict[ancestorNode].Count < parentAncestorNodeLen) then
      begin
        parentNode := ancestorNode;
        parentAncestorNodeLen := ancestorDict[ancestorNode].Count;
      end;
    end;

    if parentNode < 0 then
    begin
      Result := 0;
      exit;
    end;

    foreach var ancestorNode in kv.Value do
    begin
      if (ancestorNode <> parentNode) and 
         (not ancestorDict[parentNode].Contains(ancestorNode)) then
      begin
        Result := 0;
        exit;
      end;
    end;

    if curAncestorNodeLen = parentAncestorNodeLen then
      res := 2;
  end;

  Result := res;
end;

function CommonDescSort(X, Y: string): string;
begin
  var answer := new StringBuilder;

  for var i := 9 downto 0 do
  begin
    var num := i.ToString;

    var xCount := 0;
    for var j := 1 to X.Length do
      if X[j] = num[1] then
        xCount += 1;

    var yCount := 0;
    for var j := 1 to Y.Length do
      if Y[j] = num[1] then
        yCount += 1;

    if (xCount > 0) and (yCount > 0) then
    begin
      var minCount := Min(xCount, yCount);
      for var j := 1 to minCount do
        answer.Append(num);
    end;
  end;

  if answer.Length = 0 then
    answer.Append('-1')
  else if answer[1] = '0' then
  begin
    answer.Clear;
    answer.Append('0');
  end;

  Result := answer.ToString;
end;

