function FindPrimeRange(start, &end: integer): array of integer;
begin
  var primeNumbers := new List<integer>;

  for var num := start to &end do
  begin
    if num > 1 then
    begin
      var isPrime := True;
      for var i := 2 to Trunc(Sqrt(num)) do
        if num mod i = 0 then
        begin
          isPrime := False;
          break;
        end;

      if isPrime then
        primeNumbers.Add(num);
    end;
  end;

  Result := primeNumbers.ToArray;
end;

