function MaxSubarraySum(arr: array of integer; target: integer): integer;
begin
  var maxLen := 0;
  var sumMap := new Dictionary<integer, integer>;
  sumMap[0] := -1;
  var curSum := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    curSum += arr[i];

    if not sumMap.ContainsKey(curSum) then
      sumMap[curSum] := i;

    if sumMap.ContainsKey(curSum - target) then
    begin
      var len := i - sumMap[curSum - target];
      if len > maxLen then
        maxLen := len;
    end;
  end;

  Result := maxLen;
end;

function SortStringByFrequency(s: string): string;
begin
  var frequency := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if frequency.ContainsKey(s[i]) then
      frequency[s[i]] += 1
    else
      frequency[s[i]] := 1;

  var chars := s.ToCharArray;

  // Sort characters based on frequency and then alphabetically
  for var i := 0 to chars.Length - 2 do
    for var j := i + 1 to chars.Length - 1 do
    begin
      var freqI := frequency[chars[i]];
      var freqJ := frequency[chars[j]];

      if (freqI < freqJ) or 
         ((freqI = freqJ) and (chars[i] > chars[j])) then
        Swap(chars[i], chars[j]);
    end;

  Result := new string(chars);
end;

