      transformed.Add(int64(i) * i * i)
    else
      transformed.Add(int64(i) * i);

  Result := transformed.ToArray;
end;

function CheckBalanced(word: string): boolean;
begin
  var stack := new Stack<char>;

  for var i := 1 to word.Length do
  begin
    if word[i] = '(' then
      stack.Push(word[i])
    else if word[i] = ')' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;

  Result := stack.Count = 0;
end;

function FindPowerfulIntegers(x, y, bound: integer): array of integer;
begin
  var ans := new HashSet<integer>;

  for var i := 0 to 20 do
  begin
    var xi := Round(Power(x, i));
    if xi > bound then break;

    for var j := 0 to 20 do
    begin
      var yj := Round(Power(y, j));
      var val := xi + yj;
      if val <= bound then
        ans.Add(val)
      else
        break;
    end;
  end;

  Result := ans.ToArray;
end;

function MissingPositive(nums: array of integer): integer;
begin
  var n := nums.Length;
  var arr := nums.ToArray;

  for var i := 0 to n - 1 do
  begin
    while (arr[i] >= 1) and (arr[i] <= n) and (arr[arr[i] - 1] <> arr[i]) do
    begin
      var temp := arr[arr[i] - 1];
      arr[arr[i] - 1] := arr[i];
      arr[i] := temp;
    end;
  end;

  for var i := 0 to n - 1 do
    if arr[i] <> i + 1 then
    begin
      Result := i + 1;
      exit;
    end;

  Result := n + 1;
end;

function MinPalindromeOperations(s: string): integer;
begin
  var n := s.Length;
  var dp := new integer[n, n];

  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 1;
    for var j := i + 1 to n - 1 do
    begin
      if s[i+1] = s[j+1] then
        dp[i, j] := dp[i+1, j-1] + 2
      else
        dp[i, j] := Max(dp[i+1, j], dp[i, j-1]);
    end;
  end;

  Result := n - dp[0, n-1];
end;

function FindSmallestRepeatingSubstring(str: string): string;
