function FindMinHeap(numbers: array of integer): integer;
begin
  // Create a min-heap using List and custom comparison
  var heap := new List<integer>(numbers);

  // Build min-heap
  for var i := heap.Count div 2 - 1 downto 0 do
  begin
    var j := i;
    while True do
    begin
      var left := 2 * j + 1;
      var right := 2 * j + 2;
      var smallest := j;

      if (left < heap.Count) and (heap[left] < heap[smallest]) then
        smallest := left;
      if (right < heap.Count) and (heap[right] < heap[smallest]) then
        smallest := right;

      if smallest = j then
        break;

      heap.Swap(j, smallest);
      j := smallest;
    end;
  end;

  Result := heap[0];
end;

