function FindLongestSequence(nums: array of integer): integer;
begin
  var numSet := new HashSet<integer>(nums);
  var longestStreak := 0;

  foreach var num in numSet do
  begin
    if not numSet.Contains(num - 1) then
    begin
      var currentNum := num;
      var currentStreak := 1;

      while numSet.Contains(currentNum + 1) do
      begin
        currentNum += 1;
        currentStreak += 1;
      end;

      if currentStreak > longestStreak then
        longestStreak := currentStreak;
    end;
  end;

  Result := longestStreak;
end;

