function IncrementNumber(num: int64): int64;
begin
  var digits := new List<integer>;
  var n := num;

  while n > 0 do
  begin
    digits.Insert(0, n mod 10);
    n := n div 10;
  end;

  if digits.Count = 0 then
    digits.Add(0);

  var carry := 1;
  for var i := digits.Count - 1 downto 0 do
  begin
    if carry = 0 then break;

    if digits[i] = 9 then
    begin
      digits[i] := 0;
      carry := 1;
    end
    else
    begin
      digits[i] += carry;
      carry := 0;
    end;
  end;

  if carry = 1 then
    digits.Insert(0, 1);

  var incremented: int64 := 0;
  foreach var d in digits do
    incremented := incremented * 10 + d;

  Result := incremented;
end;

