end;

function FindTargetInRotatedArray(nums: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := nums.Length - 1;

  while left <= right do
  begin
    var mid := (left + right) div 2;

    if nums[mid] = target then
    begin
      Result := mid;
      exit;
    end;

    // Check if left half is sorted
    if nums[left] <= nums[mid] then
    begin
      if (nums[left] <= target) and (target < nums[mid]) then
        right := mid - 1
      else
        left := mid + 1;
    end
    // Right half is sorted
    else
    begin
      if (nums[mid] < target) and (target <= nums[right]) then
        left := mid + 1
      else
        right := mid - 1;
    end;
  end;

  Result := -1;
end;

function LargestProductOfThree(nums: array of integer): int64;
begin
  var sorted := nums.ToArray;
  sorted.Sort;
  var n := sorted.Length;

  var product1 := int64(sorted[0]) * sorted[1] * sorted[n-1];
  var product2 := int64(sorted[n-1]) * sorted[n-2] * sorted[n-3];

  Result := Max(product1, product2);
end;

function PrintBin(num: real): string;
