  while (binary.Length <= 32) and (n <> 0) do
  begin
    n := n * 2;
    var digit := Trunc(n);
    binary += digit.ToString;
    n := n - digit;
  end;

  if binary.Length <= 32 then
    Result := binary
  else
    Result := 'ERROR';
end;

var permResults: List<array of integer>;
    permSource: array of integer;
    permUsed: array of boolean;

procedure GeneratePermutations(path: List<integer>);
begin
  if path.Count = permSource.Length then
  begin
    permResults.Add(path.ToArray);
    exit;
  end;

  for var i := 0 to permSource.Length - 1 do
  begin
    if permUsed[i] then
      continue;

    path.Add(permSource[i]);
    permUsed[i] := True;
    GeneratePermutations(path);
    path.RemoveAt(path.Count - 1);
    permUsed[i] := False;
  end;
end;

function DfsPermutations(nums: array of integer): array of array of integer;
begin
  permResults := new List<array of integer>;
  permSource := nums;
  permUsed := new boolean[nums.Length];

  GeneratePermutations(new List<integer>);
  Result := permResults.ToArray;
end;

