var sortedMatchsticks: array of integer;
var usedMatchsticks: array of boolean;
var sideLength: integer;

function Dfs(i: integer; sum: integer; group: integer): boolean;
begin
  if group = 4 then
  begin
    Result := True;
    exit;
  end;

  if sum > sideLength then
  begin
    Result := False;
    exit;
  end;

  if sum = sideLength then
  begin
    Result := Dfs(0, 0, group + 1);
    exit;
  end;

  for var j := i to sortedMatchsticks.Length - 1 do
  begin
    if not usedMatchsticks[j] then
    begin
      usedMatchsticks[j] := True;
      if Dfs(j + 1, sum + sortedMatchsticks[j], group) then
      begin
        Result := True;
        exit;
      end;
      usedMatchsticks[j] := False;
    end;
  end;

  Result := False;
end;

