function MaximizeArray(arr: array of integer; k: integer): integer;
begin
  var a := arr.ToArray;

  // Calculate the bitwise OR of all elements in the array
  var orSum := 0;
  foreach var num in a do
    orSum := orSum or num;

  // Perform the specified number of operations
  for var op := 1 to k do
  begin
    var maxChange := 0;
    var maxIndex := 0;

    for var i := 0 to a.Length - 1 do
    begin
      // Calculate the change in the OR sum if this element were replaced
      var change := orSum xor a[i];
      if change > maxChange then
      begin
        maxChange := change;
        maxIndex := i;
      end;
    end;

    // Replace the element that maximizes the OR sum
    a[maxIndex] := orSum;
  end;

  // Return the maximum value in the array
  Result := a.Max;
end;

