function BinarySearchFirstOccurrence(arr: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := arr.Length - 1;
  var idx := -1;

  while left <= right do
  begin
    var mid := (left + right) div 2;

    if arr[mid] = target then
    begin
      idx := mid;
      right := mid - 1;
    end
    else if arr[mid] < target then
      left := mid + 1
    else
      right := mid - 1;
  end;

  Result := idx;
end;

