function MaxDepthBFS(tree: array of integer?): integer;
begin
  if tree.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var queue := new Queue<(integer, integer)>;
  queue.Enqueue((0, 1));
  var maxDepth := 0;

  while queue.Count > 0 do
  begin
    var (index, depth) := queue.Dequeue;

    if depth > maxDepth then
      maxDepth := depth;

    var leftIndex := 2 * index + 1;
    var rightIndex := 2 * index + 2;

    if (leftIndex < tree.Length) and tree[leftIndex].HasValue then
      queue.Enqueue((leftIndex, depth + 1));

    if (rightIndex < tree.Length) and tree[rightIndex].HasValue then
      queue.Enqueue((rightIndex, depth + 1));
  end;

  Result := maxDepth;
end;

function ValidAnagramPalindrome(str: string): boolean;
