      charDict[str[i]] += 1
    else
      charDict[str[i]] := 1;

  var oddCount := 0;

  foreach var count in charDict.Values do
    if count mod 2 <> 0 then
      oddCount += 1;

  Result := oddCount <= 1;
end;

function JumpWays(n: integer): int64;
begin
  if n <= 1 then
  begin
    Result := 1;
    exit;
  end;

  var first: int64 := 1;
  var second: int64 := 1;
  var third: int64 := 2;

  for var i := 4 to n do
  begin
    var current := first + second + third;
    first := second;
    second := third;
    third := current;
  end;

  if n = 2 then
    Result := 2
  else if n = 3 then
    Result := 4
  else
    Result := third;
end;

type
  Node = auto class
    val: integer;
    left: Node;
    right: Node;
  end;

function Insert(root: Node; key: integer): Node;
begin
  if root = nil then
    Result := new Node(key, nil, nil)
  else
  begin
    if root.val < key then
      root.right := Insert(root.right, key)
    else
      root.left := Insert(root.left, key);
    Result := root;
  end;
end;

function MinValueNode(_node: Node): Node;
begin
  var current := _node;
  while current.left <> nil do
    current := current.left;
  Result := current;
end;

function SmallestElementInBST(arr: array of integer): integer;
begin
  var root := new Node(arr[0], nil, nil);

  for var i := 1 to arr.Length - 1 do
    root := Insert(root, arr[i]);

  Result := MinValueNode(root).val;
end;

