function TopThreeScores(ids: array of integer; scores: array of integer): (array of integer, array of integer);
begin
  var scoreDict := new Dictionary<integer, List<integer>>;

  for var i := 0 to ids.Length - 1 do
  begin
    if not scoreDict.ContainsKey(ids[i]) then
      scoreDict[ids[i]] := new List<integer>;

    scoreDict[ids[i]].Add(scores[i]);
  end;

  var sumScore := new Dictionary<integer, integer>;

  foreach var kv in scoreDict do
  begin
    kv.Value.Sort;
    kv.Value.Reverse;
    var sum := 0;

    for var i := 0 to Min(2, kv.Value.Count - 1) do
      sum += kv.Value[i];

    sumScore[kv.Key] := sum;
  end;

  var idSet := ids.ToHashSet.ToList;
  idSet.Sort;

  var resultIds := new List<integer>;
  var resultScores := new List<integer>;

  while idSet.Count > 0 do
  begin
    var maxSum := 0;
    var maxId := 0;

    foreach var idNum in idSet do
    begin
      if sumScore[idNum] >= maxSum then
      begin
        maxSum := sumScore[idNum];
        maxId := idNum;
      end;
    end;

    resultIds.Add(maxId);
    resultScores.Add(maxSum);
    idSet.Remove(maxId);
  end;

  Result := (resultIds.ToArray, resultScores.ToArray);
end;

var islandGrid: array of array of integer;

procedure DfsIsland(r, c: integer);
begin
  if (r < 0) or (c < 0) or (r >= islandGrid.Length) or (c >= islandGrid[0].Length) or (islandGrid[r][c] <> 1) then
    exit;

  islandGrid[r][c] := -1;
  DfsIsland(r + 1, c);
  DfsIsland(r - 1, c);
  DfsIsland(r, c + 1);
  DfsIsland(r, c - 1);
end;

