function CountDistinctSubsequences(s: string): integer;
begin
  var MOD_ := 1000000007;
  var dp := new integer[s.Length + 1];
  dp[0] := 1;
  var last := new integer[26];
  for var i := 0 to 25 do
    last[i] := -1;

  for var i := 1 to s.Length do
  begin
    dp[i] := (2 * dp[i - 1]) mod MOD_;
    var idx := Ord(s[i]) - Ord('a');

    if last[idx] <> -1 then
    begin
      dp[i] := (dp[i] - dp[last[idx]] + MOD_) mod MOD_;
    end;

    last[idx] := i - 1;
  end;

  Result := (dp[s.Length] - 1) mod MOD_;
end;

