function KnightDialer(n: integer): int64;
begin
  var directions := |(2, 1), (1, 2), (2, -1), (1, -2), (-1, -2), (-2, -1), (-2, 1), (-1, 2)|;
  var r := 4;
  var c := 3;
  var dp := new int64[r, c];
  var dpNext := new int64[r, c];
  var MOD_ := Round(Power(10, 9) + 7);

  for var i := 0 to r - 1 do
    for var j := 0 to c - 1 do
    begin
      dp[i, j] := 1;
      dpNext[i, j] := 1;
    end;

  var forbid := new HashSet<(integer, integer)>;
  forbid.Add((3, 0));
  forbid.Add((3, 2));

  for var step := 2 to n do
  begin
    // Swap dp and dpNext
    var temp := dp;
    dp := dpNext;
    dpNext := temp;

    for var i := 0 to r - 1 do
      for var j := 0 to c - 1 do
      begin
        if forbid.Contains((i, j)) then
          continue;

        var curJumps: int64 := 0;

        foreach var (di, dj) in directions do
        begin
          var ti := i + di;
          var tj := j + dj;

          if (ti >= 0) and (ti < r) and (tj >= 0) and (tj < c) and not forbid.Contains((ti, tj)) then
            curJumps := (curJumps + dp[ti, tj]) mod MOD_;
        end;

        dpNext[i, j] := curJumps;
      end;
  end;

  var total: int64 := 0;
  for var i := 0 to r - 1 do
    for var j := 0 to c - 1 do
      if not forbid.Contains((i, j)) then
        total := (total + dpNext[i, j]) mod MOD_;

  Result := total;
end;

function IsDivisibleIntoConsecutiveSubsequences(nums: array of integer): boolean;
begin
  var count := new Dictionary<integer, integer>;

  foreach var num in nums do
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count[num] := 1;

  var starts := new HashSet<integer>;

  foreach var num in count.Keys do
    if not count.ContainsKey(num - 1) then
      starts.Add(num);

  foreach var start in starts do
  begin
    var val := start;
    while count.ContainsKey(val) and (count[val] > 0) do
    begin
      count[val] -= 1;
      val += 1;

      if (count.ContainsKey(val)) and (count[val] = 0) and (val - start < 3) then
      begin
        Result := False;
        exit;
      end;
    end;
  end;

  Result := True;
end;

