function LongestUniqueSubarray(nums: array of integer): integer;
begin
  var start := 0;
  var maxLength := 0;
  var seen := new Dictionary<integer, integer>;

  for var i := 0 to nums.Length - 1 do
  begin
    if seen.ContainsKey(nums[i]) and (start <= seen[nums[i]]) then
      start := seen[nums[i]] + 1
    else
    begin
      var len := i - start + 1;
      if len > maxLength then
        maxLength := len;
    end;

    seen[nums[i]] := i;
  end;

  Result := maxLength;
end;

function MinSubsequence(nums: array of integer): array of integer;
begin
  var subsequence := new List<integer>;
  var sorted := nums.ToArray;
  sorted.Sort;
  sorted := sorted.Reverse.ToArray;

  for var i := 0 to sorted.Length - 1 do
  begin
    subsequence.Add(sorted[i]);
    var sumSubseq := subsequence.Sum;
    var remainingSum := sorted.Skip(i + 1).Sum;

    if sumSubseq > remainingSum then
      break;
  end;

  Result := subsequence.ToArray;
end;

function MinFlipsAlternating(s: string): integer;
begin
  var count1 := 0;  // Count of flips required to make string starting with '1'
  var count2 := 0;  // Count of flips required to make string starting with '0'

  for var i := 1 to s.Length do
  begin
    if i mod 2 = 1 then  // odd position (1-indexed)
    begin
      if s[i] = '1' then
        count1 += 1
      else
        count2 += 1;
    end
    else  // even position
    begin
      if s[i] = '1' then
        count2 += 1
      else
        count1 += 1;
    end;
  end;

  Result := Min(count1, count2);
end;

