function PalindromeSubstring(s: string): string;
begin
  if s.Length = 1 then
  begin
    Result := s;
    exit;
  end;

  var longest := '';

  for var i := 1 to s.Length do
  begin
    // odd length palindromes
    var left := i;
    var right := i;

    while (left >= 1) and (right <= s.Length) and (s[left] = s[right]) do
    begin
      var len := right - left + 1;
      if len > longest.Length then
        longest := s.Substring(left - 1, len);
      left -= 1;
      right += 1;
    end;

    // even length palindromes
    left := i;
    right := i + 1;

    while (left >= 1) and (right <= s.Length) and (s[left] = s[right]) do
    begin
      var len := right - left + 1;
      if len > longest.Length then
        longest := s.Substring(left - 1, len);
      left -= 1;
      right += 1;
    end;
  end;

  Result := longest;
end;

var memoBST: Dictionary<integer, int64>;

function DfsBST(nodes: integer): int64;
begin
  if nodes <= 1 then
  begin
    Result := 1;
    exit;
  end;

  if memoBST.ContainsKey(nodes) then
  begin
    Result := memoBST[nodes];
    exit;
  end;

  var count: int64 := 0;

  for var root := 1 to nodes do
  begin
    var leftSubtrees := DfsBST(root - 1);
    var rightSubtrees := DfsBST(nodes - root);
    count += leftSubtrees * rightSubtrees;
  end;

  memoBST[nodes] := count;
  Result := count;
end;

function NumUniqueBST(n: integer): int64;
begin
  memoBST := new Dictionary<integer, int64>;
  Result := DfsBST(n);
end;

