function MyAtoi(str: string): integer;
begin
  var s := str.TrimStart;

  if s.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sign := 1;
  var startIdx := 1;

  if s[1] = '-' then
  begin
    sign := -1;
    startIdx := 2;
  end
  else if s[1] = '+' then
    startIdx := 2;

  var value: int64 := 0;

  for var i := startIdx to s.Length do
  begin
    if not Char.IsDigit(s[i]) then
      break;

    value := value * 10 + (Ord(s[i]) - Ord('0'));

    if sign * value > int64(2147483647) then
    begin
      Result := 2147483647;
      exit;
    end;

    if sign * value < int64(-2147483648) then
    begin
      Result := -2147483648;
      exit;
    end;
  end;

  Result := integer(sign * value);
end;

function ShortestPathAllKeys(grid: array of string): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var queue := new Queue<(integer, integer, integer, integer)>;
  var numOfKeys := 0;
  var keys := new Dictionary<char, integer>;

  for var ch := 'a' to 'f' do
    keys[ch] := Ord(ch) - Ord('a');

  var locks := new Dictionary<char, integer>;
  for var ch := 'A' to 'F' do
    locks[ch] := Ord(ch) - Ord('A');

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if grid[i][j+1] = '@' then
        queue.Enqueue((i, j, 0, 0));

      if (grid[i][j+1] >= 'a') and (grid[i][j+1] <= 'f') then
        numOfKeys += 1;
    end;

  var visited := new HashSet<(integer, integer, integer)>;

  while queue.Count > 0 do
  begin
    var (i, j, found, steps) := queue.Dequeue;
    var curr := grid[i][j+1];

    if ((curr >= 'A') and (curr <= 'F')) and (((found shr locks[curr]) and 1) = 0) then
      continue;

    if curr = '#' then
      continue;

    if (curr >= 'a') and (curr <= 'f') then
    begin
      var newFound := found or (1 shl keys[curr]);
      if newFound = (1 shl numOfKeys) - 1 then
      begin
        Result := steps;
        exit;
      end;
      found := newFound;
    end;

    var dirs := |(1, 0), (0, 1), (-1, 0), (0, -1)|;

    foreach var (di, dj) in dirs do
    begin
      var ni := i + di;
      var nj := j + dj;

      if (ni >= 0) and (ni < m) and (nj >= 0) and (nj < n) and 
         not visited.Contains((ni, nj, found)) then
      begin
        visited.Add((ni, nj, found));
        queue.Enqueue((ni, nj, found, steps + 1));
      end;
    end;
  end;

  Result := -1;
end;

