function PascalsTriangle(n: integer): array of array of integer;
begin
  var triangle := new List<array of integer>;

  for var i := 0 to n - 1 do
  begin
    var row := new List<integer>;

    for var j := 0 to i do
    begin
      if (j = 0) or (j = i) then
        row.Add(1)
      else
      begin
        var prevRow := triangle[i-1];
        row.Add(prevRow[j-1] + prevRow[j]);
      end;
    end;

    triangle.Add(row.ToArray);
  end;

  Result := triangle.ToArray;
end;

function SmallestSubstringWithPattern(str1, pattern: string): string;
begin
  var windowStart := 1;
  var matched := 0;
  var charFrequency := new Dictionary<char, integer>;

  for var i := 1 to pattern.Length do
    if charFrequency.ContainsKey(pattern[i]) then
      charFrequency[pattern[i]] += 1
    else
      charFrequency[pattern[i]] := 1;

  var strMinLength := str1.Length + 1;
  var subStr := '';

  for var windowEnd := 1 to str1.Length do
  begin
    var rightChar := str1[windowEnd];

    if charFrequency.ContainsKey(rightChar) then
    begin
      charFrequency[rightChar] -= 1;
      if charFrequency[rightChar] >= 0 then
        matched += 1;
    end;

    while matched = pattern.Length do
    begin
      var currentLength := windowEnd - windowStart + 1;

      if currentLength < strMinLength then
      begin
        strMinLength := currentLength;
        subStr := str1.Substring(windowStart - 1, currentLength);
      end;

      var leftChar := str1[windowStart];
      windowStart += 1;

      if charFrequency.ContainsKey(leftChar) then
      begin
        if charFrequency[leftChar] = 0 then
          matched -= 1;
        charFrequency[leftChar] += 1;
      end;
    end;
  end;

  Result := subStr;
end;

function SmallestRepeatingSeq(s: string): string;
begin
  var length := s.Length;

  for var i := 1 to length div 2 do
  begin
    if length mod i = 0 then
    begin
      var pattern := s.Substring(0, i);
      var repeated := '';

      for var j := 1 to length div i do
        repeated += pattern;

      if repeated = s then
      begin
        Result := pattern;
        exit;
      end;
    end;
  end;

  Result := s;
end;

