function MaxMin(list1: array of array of integer): (array of integer, array of integer);
begin
  var maxList := list1[0];
  var minList := list1[0];

  foreach var sublist in list1 do
  begin
    if sublist.Min > maxList.Max then
      maxList := sublist;
    if sublist.Max < minList.Min then
      minList := sublist;
  end;

  Result := (maxList, minList);
end;

function MaximumSubarraySum(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var maxSum := nums[0];
  var currentSum := nums[0];

  for var i := 1 to nums.Length - 1 do
  begin
    currentSum := Max(nums[i], currentSum + nums[i]);
    maxSum := Max(maxSum, currentSum);
  end;

  Result := maxSum;
end;

function FindFirstMissing(nums: array of integer): integer;
begin
  var n := nums.Length;
  var arr := nums.ToArray;

  for var i := 0 to n - 1 do
  begin
    while (arr[i] > 0) and (arr[i] <= n) and (arr[arr[i] - 1] <> arr[i]) do
    begin
      var temp := arr[arr[i] - 1];
      arr[arr[i] - 1] := arr[i];
      arr[i] := temp;
    end;
  end;

  for var i := 0 to n - 1 do
    if arr[i] <> i + 1 then
    begin
      Result := i + 1;
      exit;
    end;

  Result := n + 1;
end;

function MaxUniqueSubseq(s: string): integer;
begin
  var used := new Dictionary<char, integer>;
  var maxLength := 0;
  var start := 0;

  for var i := 0 to s.Length - 1 do
  begin
    if used.ContainsKey(s[i+1]) and (start <= used[s[i+1]]) then
      start := used[s[i+1]] + 1
    else
    begin
      var len := i - start + 1;
      if len > maxLength then
        maxLength := len;
    end;

    used[s[i+1]] := i;
  end;

  Result := maxLength;
end;

function Fibonacci(n: integer; memo: Dictionary<integer, int64> := nil): int64;
begin
  if memo = nil then
    memo := new Dictionary<integer, int64>;

  if n = 0 then
    Result := 0
  else if n = 1 then
    Result := 1
  else if memo.ContainsKey(n) then
    Result := memo[n]
  else
  begin
    var val := Fibonacci(n-1, memo) + Fibonacci(n-2, memo);
    memo[n] := val;
    Result := val;
  end;
end;

function Narcissistic(n: integer): boolean;
begin
  var numStr := n.ToString;
  var pow := numStr.Length;
  var sumOfPowers := 0;

  for var i := 1 to numStr.Length do
  begin
    var digit := StrToInt(numStr[i].ToString);
    sumOfPowers += Round(Power(digit, pow));
  end;

  Result := sumOfPowers = n;
end;

function KSmallestTuples(tuplesList: array of (integer, integer); k: integer): array of (integer, integer);
begin
  var heap := new List<(integer, (integer, integer))>;

  foreach var t in tuplesList do
  begin
    var sum := t.Item1 + t.Item2;
    heap.Add((sum, t));
  end;

  heap.Sort((x, y) -> x.Item1.CompareTo(y.Item1));

  var smallest := new List<(integer, integer)>;
  for var i := 0 to Min(k, heap.Count) - 1 do
    smallest.Add(heap[i].Item2);

  Result := smallest.ToArray;
end;

function MatrixMultiply(matrix1, matrix2: array[,] of integer): array[,] of integer;
begin
  var rows1 := matrix1.GetLength(0);
  var cols1 := matrix1.GetLength(1);
  var rows2 := matrix2.GetLength(0);
  var cols2 := matrix2.GetLength(1);

  if cols1 <> rows2 then
    raise new System.ArgumentException('Matrix dimensions are not compatible for multiplication');

  var product := new integer[rows1, cols2];

  for var i := 0 to rows1 - 1 do
    for var j := 0 to cols2 - 1 do
      for var k := 0 to cols1 - 1 do
        product[i, j] += matrix1[i, k] * matrix2[k, j];

  Result := product;
end;

function FindTwoLargestNumbers(nums: array of integer): array of integer;
