  var sorted := nums.ToArray;
  sorted.Sort;

  Result := [sorted[sorted.Length - 1], sorted[sorted.Length - 2]];
end;

function CasePermutations(S: string): array of string;
begin
  if S.Length = 0 then
  begin
    Result := new string[0];
    exit;
  end;

  if S.All(ch -> Char.IsDigit(ch)) then
  begin
    Result := |S|;
    exit;
  end;

  var results := new List<string>;
  results.Add('');

  for var i := 1 to S.Length do
  begin
    var ch := S[i];
    var newResults := new List<string>;

    if Char.IsLetter(ch) then
    begin
      foreach var r in results do
      begin
        newResults.Add(r + Char.ToLower(ch));
        newResults.Add(r + Char.ToUpper(ch));
      end;
    end
    else
    begin
      foreach var r in results do
        newResults.Add(r + ch);
    end;

    results := newResults;
  end;

  Result := results.ToArray;
end;

function ClimbingStairs(n: integer): int64;
begin
  var first: int64 := 1;
  var second: int64 := 1;

  for var i := 1 to n - 1 do
  begin
    var temp := second;
    second := first + second;
    first := temp;
  end;

  Result := second;
end;

function MergeTriplets(triplets: array of (integer, integer, integer); target: (integer, integer, integer)): boolean;
begin
  var (x, y, z) := target;
  var i := 0;
  var j := 0;
  var k := 0;

  foreach var (tx, ty, tz) in triplets do
  begin
    if (tx <= x) and (ty <= y) and (tz <= z) then
    begin
      i := Max(i, tx);
      j := Max(j, ty);
      k := Max(k, tz);
    end;
  end;

  Result := (i = x) and (j = y) and (k = z);
end;

function NumWaysToPaintFence(n, k: integer): int64;
begin
  if n = 0 then
  begin
    Result := 0;
    exit;
  end;

  if n = 1 then
  begin
    Result := k;
    exit;
  end;

  var same: int64 := k;
  var different: int64 := k * (k - 1);
  var MOD_ := Round(Power(10, 9) + 7);

  for var i := 3 to n do
  begin
    var newSame := different;
    var newDifferent := ((same + different) * (k - 1)) mod MOD_;
    same := newSame;
    different := newDifferent;
  end;

  Result := (same + different) mod MOD_;
end;

function GetMaxMin(params numbers: array of integer): (integer, integer);
begin
