  var minNum := numbers.Min;
  Result := (maxNum, minNum);
end;

function CalculateLevenshteinDistance(s, t: string): integer;
begin
  if s = '' then
  begin
    Result := t.Length;
    exit;
  end;

  if t = '' then
  begin
    Result := s.Length;
    exit;
  end;

  var cost := 0;
  if s[s.Length] <> t[t.Length] then
    cost := 1;

  var res := Min(Min(
    CalculateLevenshteinDistance(s.Substring(0, s.Length-1), t) + 1,
    CalculateLevenshteinDistance(s, t.Substring(0, t.Length-1)) + 1),
    CalculateLevenshteinDistance(s.Substring(0, s.Length-1), t.Substring(0, t.Length-1)) + cost);

  Result := res;
end;

function FindMinDiff(arr: array of integer): integer;
begin
  var sorted := arr.ToArray;
  sorted.Sort;
  var minDiff := MaxInt;

  for var i := 1 to sorted.Length - 1 do
  begin
    var diff := sorted[i] - sorted[i-1];
    if diff < minDiff then
      minDiff := diff;
  end;

  Result := minDiff;
end;

function CheckLine(line: string): boolean;
begin
  var xCount := 0;
  var oCount := 0;
  for var i := 1 to line.Length do
  begin
    if line[i] = 'X' then xCount += 1;
    if line[i] = 'O' then oCount += 1;
  end;
  Result := (xCount <= 3) and (oCount <= 3);
end;

function IsValidTicTacToe(board: array of string): boolean;
begin
  // Check rows
  for var i := 0 to 2 do
    if not CheckLine(board[i]) then
    begin
      Result := False;
      exit;
    end;

  // Check columns
  for var j := 1 to 3 do
  begin
    var colLine := board[0][j].ToString + board[1][j].ToString + board[2][j].ToString;
    if not CheckLine(colLine) then
    begin
      Result := False;
      exit;
    end;
  end;

  // Check diagonals
  var diag1 := board[0][1].ToString + board[1][2].ToString + board[2][3].ToString;
  var diag2 := board[0][3].ToString + board[1][2].ToString + board[2][1].ToString;

  if (not CheckLine(diag1)) or (not CheckLine(diag2)) then
  begin
    Result := False;
    exit;
  end;

  // Check X and O quantity
  var xCount := 0;
  var oCount := 0;

  for var i := 0 to 2 do
    for var j := 1 to 3 do
    begin
      if board[i][j] = 'X' then xCount += 1;
      if board[i][j] = 'O' then oCount += 1;
    end;

  Result := (xCount = oCount) or (xCount = oCount + 1);
end;

function ConvertWordToList(wordList: array of string): array of array of char;
