function CanPartition(nums: array of integer): boolean;
begin
  var total := nums.Sum;

  if total mod 2 <> 0 then
  begin
    Result := False;
    exit;
  end;

  var target := total div 2;
  var sums := new HashSet<integer>;
  sums.Add(0);

  foreach var n in nums do
  begin
    var newSums := new HashSet<integer>;

    foreach var el in sums do
    begin
      if el + n = target then
      begin
        Result := True;
        exit;
      end;
      newSums.Add(el);
      newSums.Add(el + n);
    end;

    sums := newSums;
  end;

  Result := False;
end;

function HasArithmeticSlice(A: array of integer): boolean;
begin
  if A.Length < 3 then
  begin
    Result := False;
    exit;
  end;

  var diff := A[1] - A[0];
  var count := 2;

  for var i := 2 to A.Length - 1 do
  begin
    if A[i] - A[i-1] = diff then
    begin
      count += 1;
      if count >= 3 then
      begin
        Result := True;
        exit;
      end;
    end
    else
    begin
      if count >= 3 then
      begin
        Result := True;
        exit;
      end;
      diff := A[i] - A[i-1];
      count := 2;
    end;
  end;

  Result := count >= 3;
end;

function UniqueCharStrings(strings: array of string): array of string;
begin
  var unique := new List<string>;

  foreach var s in strings do
  begin
    var charSet := new HashSet<char>(s.ToCharArray);
    if charSet.Count = s.Length then
      unique.Add(s);
  end;

  Result := unique.ToArray;
end;

function SwapFirstLast(s: string): string;
begin
  if s.Length <= 1 then
    Result := s
  else
    Result := s[s.Length] + s.Substring(1, s.Length - 2) + s[1];
end;

function FindMeetingRooms(intervals: array of (integer, integer); n: integer): integer;
begin
  var startTimes := new List<integer>;
  var endTimes := new List<integer>;

  foreach var (s, e) in intervals do
  begin
    startTimes.Add(s);
    endTimes.Add(e);
  end;

  startTimes.Sort;
  endTimes.Sort;

  var i := 0;
  var j := 0;
  var requiredRooms := 0;
  var maxRooms := 0;

  while (i < n) and (j < n) do
  begin
    if startTimes[i] < endTimes[j] then
    begin
      requiredRooms += 1;
      i += 1;
      if requiredRooms > maxRooms then
        maxRooms := requiredRooms;
    end
    else
    begin
      requiredRooms -= 1;
      j += 1;
    end;
  end;

  Result := maxRooms;
end;

function FindMaxPalindromeProduct(n: integer): int64;
begin
  if n = 1 then
  begin
    Result := 9;
    exit;
  end;

  var maxNum := StrToInt64(string.Create('9', n));
  var minNum := StrToInt64('1' + string.Create('0', n - 1));
  var maxPalindrome: int64 := 0;

  for var i := maxNum downto minNum do
  begin
    for var j := i downto minNum do
    begin
      var product := i * j;
      if product <= maxPalindrome then
        break;

      var prodStr := product.ToString;
      var isPalindrome := True;

      for var k := 1 to prodStr.Length div 2 do
        if prodStr[k] <> prodStr[prodStr.Length - k + 1] then
        begin
          isPalindrome := False;
          break;
        end;

      if isPalindrome then
        maxPalindrome := product;
    end;
  end;

  Result := maxPalindrome;
end;

function FindMaxNonOverlappingIntervals(intervals: array of array of integer): integer;
begin
  if intervals.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sorted := intervals.OrderBy(x -> x[1]).ToArray;
  var count := 1;
  var &end := sorted[0][1];

  for var i := 1 to sorted.Length - 1 do
  begin
    if sorted[i][0] >= &end then
    begin
      count += 1;
      &end := sorted[i][1];
    end;
  end;

  Result := count;
end;

function ToLowercase(A: string): string;
begin
  var sb := new StringBuilder;

  for var i := 1 to A.Length do
  begin
    var ch := A[i];
    if (Ord(ch) >= 65) and (Ord(ch) < 91) then
      sb.Append(Chr(Ord(ch) + 32))
    else
      sb.Append(ch);
  end;

  Result := sb.ToString;
end;

function LongestSubarrayEqual(arr: array of integer): integer;
begin
  var maxLen := 0;
  var sumMap := new Dictionary<integer, integer>;
  sumMap[0] := -1;
  var sum := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    if arr[i] = 1 then
      sum += 1
    else
      sum -= 1;

    if sumMap.ContainsKey(sum) then
    begin
      var len := i - sumMap[sum];
      if len > maxLen then
        maxLen := len;
    end
    else
      sumMap[sum] := i;
  end;

  Result := maxLen;
end;

function CheckSubarrayDivisible(nums: array of integer; k: integer): boolean;
begin
  var indexMap := new Dictionary<integer, integer>;
  var remainder := 0;
  indexMap[0] := -1;

  for var i := 0 to nums.Length - 1 do
  begin
    remainder := (remainder + nums[i]) mod k;

    if indexMap.ContainsKey(remainder) then
    begin
      if i - indexMap[remainder] > 1 then
      begin
        Result := True;
        exit;
      end;
    end
    else
      indexMap[remainder] := i;
  end;

  Result := False;
end;

function BinarySearch(nums: array of integer; target: integer; leftFlag: boolean): integer;
begin
  var lo := 0;
  var hi := nums.Length;

  while lo < hi do
  begin
    var mid := (lo + hi) div 2;
    if (nums[mid] > target) or (leftFlag and (nums[mid] = target)) then
      hi := mid
    else
      lo := mid + 1;
  end;

  Result := lo;
end;

function FirstLastPosition(nums: array of integer; target: integer): array of integer;
begin
  var leftIdx := BinarySearch(nums, target, True);
  if (leftIdx = nums.Length) or (nums[leftIdx] <> target) then
    Result := |-1, -1|
  else
  begin
    var rightIdx := BinarySearch(nums, target, False) - 1;
    Result := |leftIdx, rightIdx|;
  end;
end;

