function WaysToMakeFair(nums: array of integer): integer;
begin
  var n := nums.Length;
  var even := new List<integer>;
  var odd := new List<integer>;
  var evenSum := 0;
  var oddSum := 0;

  for var i := 0 to n - 1 do
  begin
    if i mod 2 = 0 then
      evenSum += nums[i]
    else
      oddSum += nums[i];

    even.Add(evenSum);
    odd.Add(oddSum);
  end;

  var ans := 0;

  for var i := 0 to n - 1 do
  begin
    if i = 0 then
    begin
      evenSum := odd[n - 1] - odd[i];
      oddSum := even[n - 1] - even[i];
      if evenSum = oddSum then
        ans += 1;
    end
    else
    begin
      evenSum := even[i - 1] + (odd[n - 1] - odd[i]);
      oddSum := odd[i - 1] + (even[n - 1] - even[i]);
      if evenSum = oddSum then
        ans += 1;
    end;
  end;

  Result := ans;
end;

