function InPlaceReverse(s: string): string;
begin
  var chars := s.ToCharArray;
  var left := 0;
  var right := chars.Length - 1;

  while left < right do
  begin
    var temp := chars[left];
    chars[left] := chars[right];
    chars[right] := temp;
    left += 1;
    right -= 1;
  end;

  Result := new string(chars);
end;

function FindLongestHarmoniousSubarray(nums: array of integer): integer;
begin
  var tracking := new Dictionary<integer, integer>;
  var ans := 0;

  foreach var num in nums do
    if tracking.ContainsKey(num) then
      tracking[num] += 1
    else
      tracking[num] := 1;

  foreach var kv in tracking do
  begin
    if tracking.ContainsKey(kv.Key + 1) then
    begin
      var sum := kv.Value + tracking[kv.Key + 1];
      if sum > ans then
        ans := sum;
    end;
  end;

  Result := ans;
end;

