function MinStepsToPalindrome(s: string): integer;
begin
  var n := s.Length;
  var dp := new integer[n, n];

  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 0;
    for var j := i + 1 to n - 1 do
    begin
      if s[i+1] = s[j+1] then
        dp[i, j] := dp[i+1, j-1]
      else
        dp[i, j] := Min(dp[i+1, j], dp[i, j-1]) + 1;
    end;
  end;

  Result := dp[0, n-1];
end;

type
  TreeNode = auto class
    val: integer;
    left: TreeNode;
    right: TreeNode;
  end;

function CreateTree(nodes: array of integer?): TreeNode;
begin
  if nodes.Length = 0 then
  begin
    Result := nil;
    exit;
  end;

  var root := new TreeNode(nodes[0].Value, nil, nil);
  var queue := new List<TreeNode>;
  queue.Add(root);
  var i := 1;

  while (queue.Count > 0) and (i < nodes.Length) do
  begin
    var node := queue[0];
    queue.RemoveAt(0);

    if (i < nodes.Length) and nodes[i].HasValue then
    begin
      node.left := new TreeNode(nodes[i].Value, nil, nil);
      queue.Add(node.left);
    end;
    i += 1;

    if (i < nodes.Length) and nodes[i].HasValue then
    begin
      node.right := new TreeNode(nodes[i].Value, nil, nil);
      queue.Add(node.right);
    end;
    i += 1;
  end;

  Result := root;
end;

function FindLCA(root: TreeNode; p, q: integer): integer?;
begin
  if root = nil then
  begin
    Result := nil;
    exit;
  end;

  if (root.val = p) or (root.val = q) then
  begin
    Result := root.val;
    exit;
  end;

  var left := FindLCA(root.left, p, q);
  var right := FindLCA(root.right, p, q);

  if left.HasValue and right.HasValue then
    Result := root.val
  else if left.HasValue then
    Result := left
  else
    Result := right;
end;

