var boardGlobal: array of array of char;
var wordGlobal: string;
var rowsBoard: integer;
var colsBoard: integer;
var visitedBoard: HashSet<(integer, integer)>;
var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;

function DfsBoard(x, y, index: integer): boolean;
begin
  if index = wordGlobal.Length then
  begin
    Result := True;
    exit;
  end;

  if (x < 0) or (x >= rowsBoard) or (y < 0) or (y >= colsBoard) or 
     visitedBoard.Contains((x, y)) or (boardGlobal[x][y] <> wordGlobal[index+1]) then
  begin
    Result := False;
    exit;
  end;

  visitedBoard.Add((x, y));

  foreach var (dx, dy) in directions do
  begin
    var nx := x + dx;
    var ny := y + dy;
    if DfsBoard(nx, ny, index + 1) then
    begin
      Result := True;
      exit;
    end;
  end;

  visitedBoard.Remove((x, y));
  Result := False;
end;

function FindWordInBoard(board: array of array of char; word: string): boolean;
begin
  if word.Length > board.Length * board[0].Length then
  begin
    Result := False;
    exit;
  end;

  var wordCount := new Dictionary<char, integer>;
  for var i := 1 to word.Length do
    if wordCount.ContainsKey(word[i]) then
      wordCount[word[i]] += 1
    else
      wordCount[word[i]] := 1;

  var boardCount := new Dictionary<char, integer>;
  for var i := 0 to board.Length - 1 do
    for var j := 0 to board[0].Length - 1 do
    begin
      var ch := board[i][j];
      if boardCount.ContainsKey(ch) then
        boardCount[ch] += 1
      else
        boardCount[ch] := 1;
    end;

  foreach var kv in wordCount do
    if not boardCount.ContainsKey(kv.Key) or (boardCount[kv.Key] < kv.Value) then
    begin
      Result := False;
      exit;
    end;

  boardGlobal := board;
  wordGlobal := word;
  rowsBoard := board.Length;
  colsBoard := board[0].Length;
  visitedBoard := new HashSet<(integer, integer)>;

  for var i := 0 to rowsBoard - 1 do
    for var j := 0 to colsBoard - 1 do
      if board[i][j] = word[1] then
      begin
        visitedBoard.Clear;
        if DfsBoard(i, j, 0) then
        begin
          Result := True;
          exit;
        end;
      end;

  Result := False;
end;

function FibonacciRecursion(n: integer): int64;
begin
  if n <= 0 then
    Result := 0
  else if n = 1 then
    Result := 1
  else
    Result := FibonacciRecursion(n-1) + FibonacciRecursion(n-2);
end;

var beautifulResult: integer;
