procedure SolveBeautiful(currentArr: List<integer>; idx: integer);
begin
  if idx = beautifulN + 1 then
  begin
    beautifulResult += 1;
    exit;
  end;

  for var j := 0 to currentArr.Count - 1 do
  begin
    var num := currentArr[j];
    if (num mod idx = 0) or (idx mod num = 0) then
    begin
      var newArr := new List<integer>(currentArr);
      newArr.RemoveAt(j);
      SolveBeautiful(newArr, idx + 1);
    end;
  end;
end;

