function SentenceToWords(sentence: string): array of string;
begin
  var numberWords := new Dictionary<string, string>;
  numberWords['0'] := 'zero';
  numberWords['1'] := 'one';
  numberWords['2'] := 'two';
  numberWords['3'] := 'three';
  numberWords['4'] := 'four';
  numberWords['5'] := 'five';
  numberWords['6'] := 'six';
  numberWords['7'] := 'seven';
  numberWords['8'] := 'eight';
  numberWords['9'] := 'nine';
  numberWords['10'] := 'ten';
  numberWords['11'] := 'eleven';
  numberWords['12'] := 'twelve';
  numberWords['13'] := 'thirteen';
  numberWords['14'] := 'fourteen';
  numberWords['15'] := 'fifteen';
  numberWords['16'] := 'sixteen';
  numberWords['17'] := 'seventeen';
  numberWords['18'] := 'eighteen';
  numberWords['19'] := 'nineteen';
  numberWords['20'] := 'twenty';
  numberWords['30'] := 'thirty';
  numberWords['40'] := 'forty';
  numberWords['50'] := 'fifty';
  numberWords['60'] := 'sixty';
  numberWords['70'] := 'seventy';
  numberWords['80'] := 'eighty';
  numberWords['90'] := 'ninety';

  var words := sentence.Split;
  var output := new List<string>;

  foreach var word in words do
  begin
    var isNumber := True;
    for var i := 1 to word.Length do
      if not Char.IsDigit(word[i]) then
      begin
        isNumber := False;
        break;
      end;

    if isNumber then
    begin
      var num := StrToInt(word);
      if num < 20 then
        output.Add(numberWords[word])
      else if num < 100 then
      begin
        var tens := (num div 10).ToString + '0';
        output.Add(numberWords[tens]);
        if num mod 10 <> 0 then
          output.Add(numberWords[(num mod 10).ToString]);
      end
      else if num < 1000 then
      begin
        output.Add(numberWords[word[1].ToString] + ' hundred');
        var tensPart := num mod 100;
        if tensPart > 0 then
        begin
          if tensPart < 20 then
            output.Add(numberWords[tensPart.ToString])
          else
          begin
            var tens := (tensPart div 10).ToString + '0';
            output.Add(numberWords[tens]);
            if tensPart mod 10 <> 0 then
              output.Add(numberWords[(tensPart mod 10).ToString]);
          end;
        end;
      end;
    end
    else
      output.Add(word);
  end;

  Result := output.ToArray;
end;

function ToWeirdCase(str: string): string;
