    for var i := 1 to word.Length do
    begin
      if i mod 2 = 1 then
        sb.Append(Char.ToUpper(word[i]))
      else
        sb.Append(Char.ToLower(word[i]));
    end;
    if w < words.Length - 1 then
      sb.Append(' ');
  end;

  Result := sb.ToString;
end;

function FindSmallestRepeatingSubsequence(s: string): string;
begin
  for var i := 1 to s.Length div 2 do
  begin
    var sub := s.Substring(0, i);
    var repeated := '';

    for var j := 1 to s.Length div sub.Length do
      repeated += sub;

    repeated := repeated + sub.Substring(0, s.Length mod sub.Length);

    if repeated = s then
    begin
      Result := sub;
      exit;
    end;
  end;

  Result := s;
end;

