function MinimumCapacity(tasks: array of integer; timeSlots: integer): integer;
begin
  var left := tasks.Max;
  var right := tasks.Sum;

  while left < right do
  begin
    var mid := (left + right) div 2;
    var need := 1;
    var load := 0;

    foreach var task in tasks do
    begin
      if load + task > mid then
      begin
        need += 1;
        load := 0;
      end;
      load += task;
    end;

    if need <= timeSlots then
      right := mid
    else
      left := mid + 1;
  end;

  Result := left;
end;

