  var platformEndTimes := new List<integer>;
  platformEndTimes.Add(sorted[0].Item2);

  for var i := 1 to sorted.Length - 1 do
  begin
    platformEndTimes.Sort;

    if sorted[i].Item1 > platformEndTimes[0] then
      platformEndTimes.RemoveAt(0)
    else
      platformsNeeded += 1;

    platformEndTimes.Add(sorted[i].Item2);

    if platformsNeeded > maxPlatforms then
      maxPlatforms := platformsNeeded;
  end;

  Result := maxPlatforms;
end;

