function RearrangeElements(arr: array of integer): array of integer;
begin
  var count := new Dictionary<integer, integer>;

  // Count frequency of each element
  foreach var num in arr do
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count[num] := 1;

  // Find the element with maximum frequency
  var maxFreq := 0;
  var maxElem := 0;
  foreach var kv in count do
    if kv.Value > maxFreq then
    begin
      maxFreq := kv.Value;
      maxElem := kv.Key;
    end;

  // If max frequency exceeds half of array length (+1 for odd length), impossible
  if maxFreq > (arr.Length + 1) div 2 then
  begin
    Result := nil;
    exit;
  end;

  // Create result array
  Result := new integer[arr.Length];
  var index := 0;

  // Place the most frequent element at even positions
  for var i := 1 to count[maxElem] do
  begin
    Result[index] := maxElem;
    index += 2;
  end;

  // Remove the most frequent element from dictionary
  count.Remove(maxElem);

  // Place remaining elements
  foreach var kv in count do
  begin
    for var i := 1 to kv.Value do
    begin
      if index >= arr.Length then
        index := 1;
      Result[index] := kv.Key;
      index += 2;
    end;
  end;
end;

function ModifiedMergeSort(array_: array of integer): array of integer;
begin
  if array_.Length < 2 then
  begin
    Result := array_;
    exit;
  end;

  var leftSide := ModifiedMergeSort(array_[:array_.Length div 2]);
  var rightSide := ModifiedMergeSort(array_[array_.Length div 2:]);

  var elementInLeft := 0;
  var elementInRight := 0;
  var merged := new List<integer>;

  while (elementInLeft < leftSide.Length) and (elementInRight < rightSide.Length) do
  begin
    if leftSide[elementInLeft] <= rightSide[elementInRight] then
    begin
      merged.Add(leftSide[elementInLeft]);
      elementInLeft += 1;
    end
    else
    begin
      merged.Add(rightSide[elementInRight]);
      elementInRight += 1;
    end;
  end;

  for var i := elementInLeft to leftSide.Length - 1 do
    merged.Add(leftSide[i]);

  for var i := elementInRight to rightSide.Length - 1 do
    merged.Add(rightSide[i]);

  Result := merged.ToArray;
end;

function StringToPigLatin(s: string): string;
begin
  var vowels := new HashSet<char>('aeiouAEIOU'.ToCharArray);

  // Check if the word ends with punctuation
  var lastChar := s[s.Length];
  var hasPunctuation := not Char.IsLetterOrDigit(lastChar);
  var word := s;
  var punctuation := '';

  if hasPunctuation then
  begin
    word := s.Substring(0, s.Length - 1);
    punctuation := lastChar.ToString;
  end;

  if vowels.Contains(word[1]) then
  begin
    // Rule 1: Starts with a vowel
    Result := word + 'way';
  end
  else
  begin
    // Rule 2: Starts with a consonant
    var i := 1;
    while (i <= word.Length) and not vowels.Contains(word[i]) do
      i += 1;

    if i <= word.Length then
      Result := word.Substring(i-1) + word.Substring(0, i-1) + 'ay'
    else
      // If no vowel is found, treat the whole word as a consonant cluster
      Result := word + 'ay';
  end;

  // Re-add punctuation if it existed
  if hasPunctuation then
    Result := Result + punctuation;

  Result := Result;
end;

function SortDutchFlag(arr: array of integer): array of integer;
begin
  var sorted := arr.ToArray;
  var low := 0;
  var mid := 0;
  var high := sorted.Length - 1;

  while mid <= high do
  begin
    case sorted[mid] of
      0:
      begin
        Swap(sorted[low], sorted[mid]);
        low += 1;
        mid += 1;
      end;
      1:
        mid += 1;
      2:
      begin
        Swap(sorted[mid], sorted[high]);
        high -= 1;
      end;
    end;
  end;

  Result := sorted;
end;

