var islandCharGrid: array of array of char;
var islandVisit: HashSet<(integer, integer)>;
var islandRows: integer;
var islandCols: integer;

procedure DfsIslandChar(r, c: integer);
begin
  if (r < 0) or (c < 0) or (r >= islandRows) or (c >= islandCols) or (islandCharGrid[r][c] = '0') or islandVisit.Contains((r, c)) then
    exit;

  islandVisit.Add((r, c));
  var directions := |(0, 1), (1, 0), (-1, 0), (0, -1)|;

  foreach var (dr, dc) in directions do
    DfsIslandChar(r + dr, c + dc);
end;

function FindNumberOfIslands(grid: array of array of char): integer;
begin
  if grid.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  islandRows := grid.Length;
  islandCols := grid[0].Length;
  islandCharGrid := grid;
  islandVisit := new HashSet<(integer, integer)>;
  var islands := 0;

  for var r := 0 to islandRows - 1 do
    for var c := 0 to islandCols - 1 do
      if (grid[r][c] = '1') and not islandVisit.Contains((r, c)) then
      begin
        DfsIslandChar(r, c);
        islands += 1;
      end;

  Result := islands;
end;

