function ReachTarget(target: integer): integer;
begin
  var t := Abs(target);
  var k := 0;
  var sum := 0;

  while sum < t do
  begin
    k += 1;
    sum += k;
  end;

  while (sum - t) mod 2 <> 0 do
  begin
    k += 1;
    sum += k;
  end;

  Result := k;
end;

function ContinuousSubarraySum(nums: array of integer; k: integer): boolean;
begin
  var hashMap := new Dictionary<integer, integer>;
  hashMap[0] := -1;
  var total := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    total += nums[i];

    if k <> 0 then
      total := total mod k;

    if hashMap.ContainsKey(total) then
    begin
      if i - hashMap[total] > 1 then
      begin
        Result := True;
        exit;
