function VersionCompare(version1, version2: string): integer;
begin
  var parts1 := version1.Split('.');
  var parts2 := version2.Split('.');
  var maxLen := Max(parts1.Length, parts2.Length);

  for var i := 0 to maxLen - 1 do
  begin
    var v1 := 0;
    var v2 := 0;

    if i < parts1.Length then
      v1 := StrToInt(parts1[i]);

    if i < parts2.Length then
      v2 := StrToInt(parts2[i]);

    if v1 <> v2 then
    begin
      if v1 > v2 then
        Result := 1
      else
        Result := -1;
      exit;
    end;
  end;

  Result := 0;
end;

function GCD(a, b: integer): integer;
begin
  while b <> 0 do
  begin
    var temp := b;
    b := a mod b;
    a := temp;
  end;
  Result := a;
end;

function FindLCM(num1, num2: integer): integer;
begin
  Result := (num1 div GCD(num1, num2)) * num2;
end;

function CountValidParenthesesStrings(n: integer): int64;
