function FindInCyclicSorted(arr: array of integer; target: integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := -1;
    exit;
  end;

  if arr.Length = 1 then
  begin
    if arr[0] = target then
      Result := 0
    else
      Result := -1;
    exit;
  end;

  // Find the index of the smallest element
  var start := 0;
  var &end := arr.Length - 1;

  while start < &end do
  begin
    var mid := (start + &end) div 2;
    if arr[mid] > arr[&end] then
      start := mid + 1
    else
      &end := mid;
  end;

  var pivot := start;
  start := 0;
  &end := arr.Length - 1;

  // Determine which half to search
  if (target >= arr[0]) and (target <= arr[pivot - 1]) then
  begin
    start := 0;
    &end := pivot - 1;
  end
  else
  begin
    start := pivot;
    &end := arr.Length - 1;
  end;

  // Binary search in the chosen half
  while start <= &end do
  begin
    var mid := (start + &end) div 2;
    if arr[mid] = target then
    begin
      Result := mid;
      exit;
    end
    else if arr[mid] < target then
      start := mid + 1
    else
      &end := mid - 1;
  end;

  Result := -1;
end;

