function LongestPalindromeSubseq(str: string): integer;
begin
  var n := str.Length;
  var dp := new integer[n, n];

  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 1;
    for var j := i + 1 to n - 1 do
    begin
      if str[i+1] = str[j+1] then
        dp[i, j] := 2 + dp[i+1, j-1]
      else
        dp[i, j] := Max(dp[i+1, j], dp[i, j-1]);
    end;
  end;

  if n = 0 then
    Result := 0
  else
    Result := dp[0, n-1];
end;

