function MinPathSumTriangle(triangle: array of array of integer): integer;
begin
  if triangle.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var dp := triangle.ToArray();
  for var i := 0 to triangle.Length - 1 do
  begin
    dp[i] := new integer[triangle[i].Length];
    for var j := 0 to triangle[i].Length - 1 do
      dp[i][j] := triangle[i][j];
  end;

  for var row := triangle.Length - 2 downto 0 do
    for var col := 0 to triangle[row].Length - 1 do
      dp[row][col] := dp[row][col] + Min(dp[row+1][col], dp[row+1][col+1]);

  Result := dp[0][0];
end;

