function MaxSwap(num: integer): integer;
begin
  var n := num.ToString;
  var digits := new List<integer>;

  for var i := 1 to n.Length do
    digits.Add(StrToInt(n[i].ToString));

  var maxCarry := new List<(integer, integer)>;
  maxCarry.Add((digits[digits.Count - 1], digits.Count - 1));

  for var i := digits.Count - 2 downto 0 do
  begin
    if digits[i] > maxCarry.Last.Item1 then
      maxCarry.Add((digits[i], i))
    else
      maxCarry.Add(maxCarry.Last);
  end;

  maxCarry.Reverse;

  for var i := 0 to digits.Count - 1 do
  begin
    if digits[i] < maxCarry[i].Item1 then
    begin
      var j := maxCarry[i].Item2;
      // Swap digits[i] and digits[j]
      var temp := digits[i];
      digits[i] := digits[j];
      digits[j] := temp;

      var swapped := 0;
      for var k := 0 to digits.Count - 1 do
        swapped := swapped * 10 + digits[k];

      Result := swapped;
      exit;
    end;
  end;

  Result := num;
end;

