type
  TreeNode = auto class
    val: integer;
    left: TreeNode;
    right: TreeNode;
  end;

var maxPathSumResult: integer;

function MaxPath(node: TreeNode): integer;
begin
  if node = nil then
  begin
    Result := 0;
    exit;
  end;

  var leftSum := Max(0, MaxPath(node.left));
  var rightSum := Max(0, MaxPath(node.right));

  if node.val + leftSum + rightSum > maxPathSumResult then
    maxPathSumResult := node.val + leftSum + rightSum;

  Result := node.val + Max(leftSum, rightSum);
end;

