    var subarr := new List<integer>;
    for var j := i to i + k - 1 do
      subarr.Add(arr[j]);

    var key := string.Join(',', subarr);

    if seen.Contains(key) then
    begin
      Result := True;
      exit;
    end;

    seen.Add(key);
  end;

  Result := False;
end;

function CalculateParkingFees(fees: array of integer; records: array of string): array of integer;
begin
  var answer := new List<integer>;
  var timeDict := new Dictionary<string, List<string>>;

  foreach var r in records do
  begin
    var parts := r.Split(' ');
    var time := parts[0];
    var carId := parts[1];

    if timeDict.ContainsKey(carId) then
      timeDict[carId].Add(time)
    else
      timeDict[carId] := new List<string>([time]);
  end;

  var sortedCars := timeDict.Keys.OrderBy(x -> x).ToList;

  foreach var carId in sortedCars do
  begin
    var times := timeDict[carId];

    if times.Count mod 2 <> 0 then
      times.Add('23:59');

    var total := 0;

    for var k := 0 to times.Count - 1 step 2 do
    begin
      var time1Parts := times[k].Split(':');
      var time2Parts := times[k+1].Split(':');
      var mins1 := StrToInt(time1Parts[0]) * 60 + StrToInt(time1Parts[1]);
      var mins2 := StrToInt(time2Parts[0]) * 60 + StrToInt(time2Parts[1]);
      total += mins2 - mins1;
    end;

    var diff := fees[0] - total;

    if diff > 0 then
      answer.Add(fees[1])
    else
      answer.Add(Ceil(Abs(diff) / fees[2]) * fees[3] + fees[1]);
  end;

  Result := answer.ToArray;
end;

