var sGlobalExtra: string;
var dictionarySet: HashSet<string>;
var memoExtra: Dictionary<integer, integer>;

function Dp(start: integer): integer;
begin
  if start = sGlobalExtra.Length then
  begin
    Result := 0;
    exit;
  end;

  if memoExtra.ContainsKey(start) then
  begin
    Result := memoExtra[start];
    exit;
  end;

  var ans := Dp(start + 1) + 1;

  for var &end := start to sGlobalExtra.Length - 1 do
  begin
    var curr := sGlobalExtra.Substring(start, &end - start + 1);
    if dictionarySet.Contains(curr) then
      ans := Min(ans, Dp(&end + 1));
  end;

  memoExtra[start] := ans;
  Result := ans;
end;

