function LargestNumber(numbers: array of integer): string;
begin
  var numStrs := numbers.Select(n -> n.ToString).ToList;

  numStrs.Sort((x, y) -> 
  begin
    var xy := x + y;
    var yx := y + x;
    Result := -xy.CompareTo(yx); // Negative for descending order
  end);

  var largest := string.Join('', numStrs);

  // Handle leading zeros
  if largest[1] = '0' then
    Result := '0'
  else
    Result := largest;
end;

function Merge(left, right: array of integer): array of integer;
begin
  var merged := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < left.Length) and (j < right.Length) do
  begin
    if left[i] < right[j] then
    begin
      merged.Add(left[i]);
      i += 1;
    end
    else
    begin
      merged.Add(right[j]);
      j += 1;
    end;
  end;

  while i < left.Length do
  begin
    merged.Add(left[i]);
    i += 1;
  end;

  while j < right.Length do
  begin
    merged.Add(right[j]);
    j += 1;
  end;

  Result := merged.ToArray;
end;

function MergeSort(list: array of integer): array of integer;
begin
  if list.Length < 2 then
  begin
    Result := list;
    exit;
  end;

  var middle := list.Length div 2;
  var left := MergeSort(list[:middle]);
  var right := MergeSort(list[middle:]);

  Result := Merge(left, right);
end;

function FindLHS(nums: array of integer): integer;
begin
  var count := new Dictionary<integer, integer>;

  foreach var num in nums do
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count[num] := 1;

  var maxLen := 0;

  foreach var kv in count do
  begin
    if count.ContainsKey(kv.Key + 1) then
    begin
      var sum := kv.Value + count[kv.Key + 1];
      if sum > maxLen then
        maxLen := sum;
    end;
  end;

  Result := maxLen;
end;

function MinDeletionsToPalindrome(s: string): integer;
begin
  var n := s.Length;
  var dp := new integer[n, n];

  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 0;
    for var j := i + 1 to n - 1 do
    begin
      if s[i+1] = s[j+1] then
        dp[i, j] := dp[i+1, j-1]
      else
        dp[i, j] := Min(dp[i+1, j], dp[i, j-1]) + 1;
    end;
  end;

  if n = 0 then
    Result := 0
  else
    Result := dp[0, n-1];
end;

function MatchRecursively(s, p: string): boolean;
begin
  if (s = '') and (p = '') then
  begin
    Result := True;
    exit;
  end;

  if p = '' then
  begin
    Result := False;
    exit;
  end;

  var firstMatch := (s <> '') and ((p[1] = '.') or (p[1] = s[1]));

  if (p.Length >= 2) and (p[2] = '*') then
  begin
    Result := (MatchRecursively(s, p.Substring(2))) or
              (firstMatch and MatchRecursively(s.Substring(1), p));
  end
  else
  begin
    Result := firstMatch and MatchRecursively(s.Substring(1), p.Substring(1));
  end;
end;

function DoesMatch(str, pattern: string): boolean;
begin
  Result := MatchRecursively(str, pattern);
end;

