function CountPairsForSum(arr: array of integer; target: integer): integer;
begin
  var count := 0;
  var freq := new Dictionary<integer, integer>;

  foreach var num in arr do
  begin
    var complement := target - num;

    if freq.ContainsKey(complement) then
      count += freq[complement];

    if freq.ContainsKey(num) then
      freq[num] += 1
    else
      freq[num] := 1;
  end;

  Result := count;
end;

function FindMaxSquare(matrix: array of array of integer): integer;
begin
  if matrix.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var rows := matrix.Length;
  var cols := matrix[0].Length;
  var maxSide := 0;

  var dp := new integer[rows, cols];

  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
    begin
      if matrix[i][j] = 1 then
      begin
        if (i = 0) or (j = 0) then
          dp[i, j] := 1
        else
          dp[i, j] := Min(Min(dp[i-1, j], dp[i, j-1]), dp[i-1, j-1]) + 1;

        if dp[i, j] > maxSide then
          maxSide := dp[i, j];
      end;
    end;

  Result := maxSide;
end;

function UniqueBST(n: integer): int64;
begin
  var dp := new int64[n + 1];
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
    for var j := 0 to i - 1 do
      dp[i] := dp[i] + dp[j] * dp[i - j - 1];

  Result := dp[n];
end;

function NearestPalindromic(n: string): string;
begin
  // Handle special cases
  if n.Length = 1 then
  begin
    Result := (StrToInt(n) - 1).ToString;
    exit;
  end;

  if (n = '10') or (n = '11') then
  begin
    Result := '9';
    exit;
  end;

  var mid := n.Length div 2;
  var part: string;

  if n.Length mod 2 = 0 then
    part := n.Substring(0, mid)
  else
    part := n.Substring(0, mid + 1);

  var candidates := new List<string>;

  // Try part-1, part, part+1
  for var i := -1 to 1 do
  begin
    var p := (StrToInt(part) + i).ToString;

    // Handle special case for 10x->9x
    if p = '0' then
      continue;

    var c := p.Substring(0, mid);
    c := p + c.Inverse;

    // Handle special case for 1000,100000,...
    if n.Length - c.Length > 1 then
      c := c + c[1];

    if c <> n then
      candidates.Add(c);
  end;

  // Select the best candidate
  var num := StrToInt64(n);
  var best := StrToInt64(candidates[0]);
  var bestGap := Abs(best - num);

  for var i := 1 to candidates.Count - 1 do
  begin
    var cand := StrToInt64(candidates[i]);
    var gap := Abs(cand - num);

    if (gap < bestGap) or ((gap = bestGap) and (cand < best)) then
    begin
      best := cand;
      bestGap := gap;
    end;
  end;

  Result := best.ToString;
end;

function PathCounter(grid: array of array of integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var dp := new integer[m, n];

  if grid[0][0] = 0 then
    dp[0, 0] := 1
  else
    dp[0, 0] := 0;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if grid[i][j] = 1 then
        dp[i, j] := 0
      else
      begin
        if i > 0 then
          dp[i, j] := dp[i, j] + dp[i-1, j];
        if j > 0 then
          dp[i, j] := dp[i, j] + dp[i, j-1];
      end;
    end;

  Result := dp[m-1, n-1];
end;

function MaxCandies(prices: array of integer; money: integer): integer;
