  foreach var price in sorted do
  begin
    if remainingMoney >= price then
    begin
      remainingMoney -= price;
      count += 1;
    end
    else
      break;
  end;

  Result := count;
end;

function Rob(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  if nums.Length = 1 then
  begin
    Result := nums[0];
    exit;
  end;

  var dp := new integer[nums.Length];
  dp[0] := nums[0];
  dp[1] := Max(nums[0], nums[1]);

  for var i := 2 to nums.Length - 1 do
    dp[i] := Max(dp[i-1], dp[i-2] + nums[i]);

  Result := dp[dp.Length - 1];
end;

type
  TreeNode = auto class
    val: integer;
    left: TreeNode;
    right: TreeNode;
  end;

function HelperBST(node: TreeNode; minVal, maxVal: int64): boolean;
begin
  if node = nil then
  begin
    Result := True;
    exit;
  end;

  if (node.val <= minVal) or (node.val >= maxVal) then
  begin
    Result := False;
    exit;
  end;

  Result := HelperBST(node.left, minVal, node.val) and
            HelperBST(node.right, node.val, maxVal);
end;

function IsValidBST(root: TreeNode): boolean;
begin
  Result := HelperBST(root, -1000000000000, 1000000000000);
end;

