function PrintCycle(matrix: array of array of integer; rows, columns, start: integer): List<integer>;
begin
  var cycle := new List<integer>;
  var endX := rows - 1 - start;
  var endY := columns - 1 - start;

  // Left to right
  for var i := start to endY do
    cycle.Add(matrix[start][i]);

  // Top to bottom (if at least two rows)
  if start < endX then
    for var i := start + 1 to endX do
      cycle.Add(matrix[i][endY]);

  // Right to left (if at least two rows and two columns)
  if (start < endX) and (start < endY) then
    for var i := endY - 1 downto start do
      cycle.Add(matrix[endX][i]);

  // Bottom to top (if at least three rows and two columns)
  if (start < endY) and (start < endX - 1) then
    for var i := endX - 1 downto start + 1 do
      cycle.Add(matrix[i][start]);

  Result := cycle;
end;

function PrintMatrix(matrix: array of array of integer): array of integer;
begin
  var rows := matrix.Length;
  var columns := matrix[0].Length;
  var start := 0;
  var spiral := new List<integer>;

  while (rows > 2 * start) and (columns > 2 * start) do
  begin
    spiral.AddRange(PrintCycle(matrix, rows, columns, start));
    start += 1;
  end;

  Result := spiral.ToArray;
end;

function FindKthMissing(arr: array of integer; k: integer): integer;
begin
  var missingCount := 0;
  var current := 1;
  var i := 0;

  while missingCount < k do
  begin
    if (i < arr.Length) and (arr[i] = current) then
    begin
      i += 1;
    end
    else
    begin
      missingCount += 1;
      if missingCount = k then
      begin
        Result := current;
        exit;
      end;
    end;
    current += 1;
  end;

  Result := current - 1;
end;

