function NumTilePossibilities(tiles: string): int64;
begin
  var counts := new List<integer>;
  var charCounts := new Dictionary<char, integer>;

  for var i := 1 to tiles.Length do
    if charCounts.ContainsKey(tiles[i]) then
      charCounts[tiles[i]] += 1
    else
      charCounts[tiles[i]] := 1;

  foreach var v in charCounts.Values do
    counts.Add(v);

  var dp := new int64[tiles.Length + 1];
  dp[0] := 1;
  var allLen := 0;

  foreach var v in counts do
  begin
    allLen += v;
    for var i := allLen downto 1 do
    begin
      for var j := 1 to Min(i, v) do
      begin
        // Combination C(i, j)
        var comb: int64 := 1;
        for var c := 1 to j do
          comb := comb * (i - j + c) div c;
        dp[i] := dp[i] + dp[i - j] * comb;
      end;
    end;
  end;

  Result := dp.Sum - 1;
end;

