    for var i := 1 to str.Length do
      if charCounts.ContainsKey(str[i]) then
        charCounts[str[i]] += 1
      else
        charCounts[str[i]] := 1;

    var key := new List<string>;
    foreach var kv in charCounts.OrderBy(kv -> kv.Key) do
      key.Add($'{kv.Key}:{kv.Value}');

    anagramCounts.Add(string.Join(',', key));
  end;

  Result := anagramCounts.Count;
end;

function FindLargestProduct(arr: array of integer): int64?;
