  var sorted := arr.ToArray;
  sorted.Sort;
  var n := sorted.Length;

  var product1 := int64(sorted[0]) * sorted[1] * sorted[n-1];
  var product2 := int64(sorted[n-1]) * sorted[n-2] * sorted[n-3];

  Result := Max(product1, product2);
end;

var matrixGlobal: array of array of integer;
var mGlobal: integer;
var nGlobal: integer;
var directionsIsland := |(0, 1), (0, -1), (1, 0), (-1, 0)|;

function Bfs(i, j: integer): integer;
begin
  var area := 1;
  var queue := new Queue<(integer, integer)>;
  queue.Enqueue((i, j));
  matrixGlobal[i][j] := 0;

  while queue.Count > 0 do
  begin
    var (x, y) := queue.Dequeue;

    foreach var (dx, dy) in directionsIsland do
    begin
      var nx := x + dx;
      var ny := y + dy;

      if (nx >= 0) and (nx < mGlobal) and (ny >= 0) and (ny < nGlobal) and (matrixGlobal[nx][ny] = 1) then
      begin
        matrixGlobal[nx][ny] := 0;
        area += 1;
        queue.Enqueue((nx, ny));
      end;
    end;
  end;

  Result := area;
end;

function MaxIslandArea(matrix: array of array of integer): integer;
begin
  if matrix.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  mGlobal := matrix.Length;
  nGlobal := matrix[0].Length;
  matrixGlobal := matrix;
  var maxArea := 0;

  for var i := 0 to mGlobal - 1 do
    for var j := 0 to nGlobal - 1 do
      if matrixGlobal[i][j] = 1 then
      begin
        var area := Bfs(i, j);
        if area > maxArea then
          maxArea := area;
      end;

  Result := maxArea;
end;

var numsGlobal: array of integer;
var visitedGlobal: array of boolean;
var targetSide: integer;

function DFS(pos: integer; fullEdge: integer; curLen: integer): boolean;
begin
  if fullEdge = 3 then
  begin
    Result := True;
    exit;
  end;

  if curLen > targetSide then
  begin
    Result := False;
    exit;
  end;

  if curLen = targetSide then
  begin
    Result := DFS(0, fullEdge + 1, 0);
    exit;
  end;

  for var i := pos to numsGlobal.Length - 1 do
  begin
    if visitedGlobal[i] then continue;

    visitedGlobal[i] := True;
    if DFS(i + 1, fullEdge, curLen + numsGlobal[i]) then
    begin
      Result := True;
      exit;
    end;
    visitedGlobal[i] := False;
  end;

  Result := False;
end;

function CanFormRectangle(nums: array of integer): boolean;
begin
  var perimeter := nums.Sum;
  var n := nums.Length;

  if (n < 4) or (perimeter mod 4 <> 0) then
  begin
    Result := False;
    exit;
  end;

  targetSide := perimeter div 4;
  numsGlobal := nums;
  visitedGlobal := new boolean[n];

  Result := DFS(0, 0, 0);
end;

