function FindLargestRectangle(matrix: array of array of integer): integer;
begin
  if matrix.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var m := matrix.Length;
  var n := matrix[0].Length;
  var height := new integer[n + 1];
  var maxArea := 0;

  for var i := 0 to m - 1 do
  begin
    for var j := 0 to n - 1 do
    begin
      if matrix[i][j] = 1 then
        height[j] := height[j] + 1
      else
        height[j] := 0;
    end;

    var stack := new Stack<integer>;
    stack.Push(-1);

    for var j := 0 to n do
    begin
      while (stack.Peek <> -1) and (height[j] < height[stack.Peek]) do
      begin
        var h := height[stack.Pop];
        var w := j - stack.Peek - 1;
        var area := h * w;
        if area > maxArea then
          maxArea := area;
      end;
      stack.Push(j);
    end;
  end;

  Result := maxArea;
end;

