function IsValidParenString(s: string): boolean;
begin
  var stack := new Stack<char>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];
    if ch = '(' then
      stack.Push(ch)
    else if ch = ')' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;

  Result := stack.Count = 0;
end;

var boardWordGlobal: array of array of char;
var rowsWord: integer;
var colsWord: integer;

function DfsWord(r, c, k: integer; word: string): boolean;
begin
  if (r < 0) or (r >= rowsWord) or (c < 0) or (c >= colsWord) or (boardWordGlobal[r][c] <> word[k+1]) then
  begin
    Result := False;
    exit;
  end;

  if k + 1 = word.Length then
  begin
    Result := True;
    exit;
  end;

  var temp := boardWordGlobal[r][c];
  boardWordGlobal[r][c] := #0;

  var found := DfsWord(r + 1, c, k + 1, word) or DfsWord(r - 1, c, k + 1, word) or 
                DfsWord(r, c + 1, k + 1, word) or DfsWord(r, c - 1, k + 1, word);

  boardWordGlobal[r][c] := temp;
  Result := found;
end;

function WordExist(board: array of array of char; word: string): boolean;
begin
  rowsWord := board.Length;
  colsWord := board[0].Length;
  boardWordGlobal := board;

  for var r := 0 to rowsWord - 1 do
    for var c := 0 to colsWord - 1 do
      if DfsWord(r, c, 0, word) then
      begin
        Result := True;
        exit;
      end;

  Result := False;
end;

function IsStrictlyMonotonic(lst: array of integer): boolean;
begin
  if lst.Length < 2 then
  begin
    Result := False;
    exit;
  end;

  var increasing := True;
  var decreasing := True;

  for var i := 0 to lst.Length - 2 do
  begin
    if lst[i] < lst[i + 1] then
      decreasing := False
    else if lst[i] > lst[i + 1] then
      increasing := False;
  end;

  Result := increasing or decreasing;
end;

