function LongestConsecutiveOnes(arr: array of integer): integer;
begin
  var maxCount := 0;
  var count := 0;

  foreach var i in arr do
  begin
    if i = 1 then
    begin
      count += 1;
      if count > maxCount then
        maxCount := count;
    end
    else
      count := 0;
  end;

  Result := maxCount;
end;

function MaxValueInSublists(sublists: array of array of integer): integer;
begin
  var maxValue := 0;

  foreach var sublist in sublists do
  begin
    if sublist.Length > 0 then
    begin
      var subMax := sublist.Max;
      if subMax > maxValue then
        maxValue := subMax;
    end;
