  Result := maxValue;
end;

function EraseOverlapIntervals(intervals: array of array of integer): integer;
begin
  var size := intervals.Length;

  if size <= 1 then
  begin
    Result := 0;
    exit;
  end;

  var sorted := intervals.OrderBy(x -> x[1]).ToArray;
  var firstEnd := sorted[0][1];
  var toRemove := 0;

  for var i := 1 to size - 1 do
  begin
    var start := sorted[i][0];
    var &end := sorted[i][1];

    if start >= firstEnd then
      firstEnd := &end
    else
      toRemove += 1;
  end;

  Result := toRemove;
end;

function LargestNumberFromDigits(n: int64): int64;
begin
  var digitList := new List<integer>;
  var num := n;

  while num > 0 do
  begin
    digitList.Add(num mod 10);
    num := num div 10;
  end;

  digitList.Sort;
  digitList.Reverse;

  var largest: int64 := 0;
  foreach var d in digitList do
    largest := largest * 10 + d;

  Result := largest;
end;

function MinOperationsToOne(n: integer): integer;
begin
  var operations := 0;
  var num := n;

  while num <> 1 do
  begin
    if num mod 2 = 0 then
      num := num div 2
    else
    begin
      if (num = 3) or ((num mod 4) = 1) then
        num -= 1
      else
        num += 1;
    end;
    operations += 1;
  end;

  Result := operations;
end;

function MaxIceCream(costs: array of integer; coins: integer): integer;
begin
  var sorted := costs.ToArray;
  sorted.Sort;
  var count := 0;
  var remainingCoins := coins;

  for var i := 0 to sorted.Length - 1 do
  begin
    if remainingCoins >= sorted[i] then
    begin
      count += 1;
      remainingCoins -= sorted[i];
    end
    else
      break;
  end;

  Result := count;
end;

function SortAndGroupByParity(nums: array of integer): array of integer;
