  var odd := nums.Where(num -> num mod 2 <> 0).OrderBy(x -> x).ToList;

  even.AddRange(odd);
  Result := even.ToArray;
end;

var numIslandGrid: array of array of char;
var numIslandRows: integer;
var numIslandCols: integer;

procedure DfsNumIsland(i, j: integer);
begin
  if (i < 0) or (j < 0) or (i >= numIslandRows) or (j >= numIslandCols) or (numIslandGrid[i][j] <> '1') then
    exit;

  numIslandGrid[i][j] := '#';
  DfsNumIsland(i + 1, j);
  DfsNumIsland(i - 1, j);
  DfsNumIsland(i, j + 1);
  DfsNumIsland(i, j - 1);
end;

function NumIslands(grid: array of array of char): integer;
begin
  if grid.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  numIslandRows := grid.Length;
  numIslandCols := grid[0].Length;
  numIslandGrid := grid;

  var count := 0;

  for var i := 0 to numIslandRows - 1 do
    for var j := 0 to numIslandCols - 1 do
      if grid[i][j] = '1' then
      begin
        DfsNumIsland(i, j);
        count += 1;
      end;

  Result := count;
end;

