function WordPatternCheck(pattern: string; str: string): boolean;
begin
  var words := str.Split;

  if pattern.Length <> words.Length then
  begin
    Result := False;
    exit;
  end;

  var charMap := new Dictionary<char, string>;
  var wordMap := new Dictionary<string, char>;

  for var i := 1 to pattern.Length do
  begin
    var c := pattern[i];
    var w := words[i-1];

    if not charMap.ContainsKey(c) then
    begin
      if wordMap.ContainsKey(w) then
      begin
        Result := False;
        exit;
      end;
      charMap[c] := w;
      wordMap[w] := c;
    end
    else
    begin
      if charMap[c] <> w then
      begin
        Result := False;
        exit;
      end;
    end;
  end;

  Result := True;
end;

function LargestInSubarrays(nums: array of integer; k: integer): array of integer;
begin
  var deque := new LinkedList<integer>;
  var n := nums.Length;
  var maxInEach := new List<integer>;

  for var i := 0 to n - 1 do
  begin
    // Remove elements out of current window
    while (deque.Count > 0) and (deque.First.Value <= i - k) do
      deque.RemoveFirst();

    // Remove smaller elements from the back
    while (deque.Count > 0) and (nums[i] > nums[deque.Last.Value]) do
      deque.RemoveLast();

    deque.AddLast(i);

    if i >= k - 1 then
      maxInEach.Add(nums[deque.First.Value]);
  end;

  Result := maxInEach.ToArray;
end;

function CheckValidIP(s: string): boolean;
begin
  var parts := s.Split('.');

  if parts.Length <> 4 then
  begin
    Result := False;
    exit;
  end;

  foreach var part in parts do
  begin
    // Check if all characters are digits
    for var i := 1 to part.Length do
      if not Char.IsDigit(part[i]) then
      begin
        Result := False;
        exit;
      end;

    var num := StrToInt(part);
    if (num < 0) or (num > 255) then
    begin
      Result := False;
      exit;
    end;

    // Check for leading zeros
    if (part[1] = '0') and (part.Length > 1) then
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;

