function NumTrees(n: integer): int64;
begin
  if n = 0 then
  begin
    Result := 1;
    exit;
  end;

  var dp := new int64[n + 1];
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
    for var j := 0 to i - 1 do
      dp[i] := dp[i] + dp[j] * dp[i - j - 1];

  Result := dp[n];
end;

