      if not visited[neighbor] then
        Dfs(graph, neighbor, visited);
end;

function CountConnectedComponents(edges: array of (integer, integer)): integer;
begin
  var graph := new Dictionary<integer, List<integer>>;

  foreach var (u, v) in edges do
  begin
    if not graph.ContainsKey(u) then
      graph[u] := new List<integer>;
    if not graph.ContainsKey(v) then
      graph[v] := new List<integer>;

    graph[u].Add(v);
    graph[v].Add(u);
  end;

  var visited := new Dictionary<integer, boolean>;
  foreach var node in graph.Keys do
    visited[node] := False;

  var count := 0;

  foreach var node in graph.Keys do
  begin
    if not visited[node] then
    begin
      Dfs(graph, node, visited);
      count += 1;
    end;
  end;

  Result := count;
end;

function RecurringCycleLength(n: integer): integer;
begin
  var num := n;

  // Remove factors of 2 and 5
  while num mod 2 = 0 do
    num := num div 2;
  while num mod 5 = 0 do
    num := num div 5;

  if num = 1 then
  begin
    Result := 0;
    exit;
  end;

  var remainder := 1;
  var cycleLength := 0;
  var remainders := new Dictionary<integer, integer>;

  while not remainders.ContainsKey(remainder) do
  begin
    remainders[remainder] := cycleLength;
    remainder := (remainder * 10) mod n;
    cycleLength += 1;
  end;

  Result := cycleLength - remainders[remainder];
end;

