function LongestDecreasingSubseq(nums: array of integer): integer;
begin
  var n := nums.Length;
  if n = 0 then
  begin
    Result := 0;
    exit;
  end;

  var dp := new integer[n];

  for var i := 0 to n - 1 do
  begin
    dp[i] := 1;
    for var j := 0 to i - 1 do
      if nums[i] < nums[j] then
        dp[i] := Max(dp[i], dp[j] + 1);
  end;

  Result := dp.Max;
end;

function FindLongestSubstring(s: string): integer;
begin
  var charMap := new Dictionary<char, integer>;
  var left := 0;
  var maxLength := 0;

  for var right := 0 to s.Length - 1 do
  begin
    var ch := s[right + 1];

    if charMap.ContainsKey(ch) then
      left := Max(left, charMap[ch] + 1);

    charMap[ch] := right;
    maxLength := Max(maxLength, right - left + 1);
  end;

  Result := maxLength;
end;

function CanThreePartsEqualSum(A: array of integer): boolean;
begin
  var total := A.Sum;

  if total mod 3 <> 0 then
  begin
    Result := False;
    exit;
  end;

  var count := 0;
  var cumSum := 0;
  var target := total div 3;

  foreach var num in A do
  begin
    cumSum += num;
    if cumSum = target then
    begin
      cumSum := 0;
      count += 1;
    end;
  end;

  Result := count >= 3;
end;

function DijkstraShortestPath(graph: Dictionary<string, Dictionary<string, integer>>; source: string): Dictionary<string, integer>;
begin
  var distances := new Dictionary<string, integer>;

  foreach var node in graph.Keys do
    distances[node] := MaxInt;

  distances[source] := 0;

  // Min-heap priority queue using List
  var queue := new List<(integer, string)>;
  queue.Add((0, source));

  while queue.Count > 0 do
  begin
    queue.Sort((x, y) -> x.Item1.CompareTo(y.Item1));
    var (currentDistance, currentNode) := queue[0];
    queue.RemoveAt(0);

    if currentDistance > distances[currentNode] then
      continue;

    if graph.ContainsKey(currentNode) then
    begin
      foreach var kv in graph[currentNode] do
      begin
        var neighbor := kv.Key;
        var weight := kv.Value;
        var distance := currentDistance + weight;

        if distance < distances[neighbor] then
        begin
          distances[neighbor] := distance;
          queue.Add((distance, neighbor));
        end;
      end;
    end;
  end;

  Result := distances;
end;

function RotatedDigitsCount(N: integer): integer;
begin
  var ans := 0;
  var d := new integer[N + 1];

  // Initialize for digits 0-9
  // 0: valid but unchanged, 1: valid and changes to another digit, -1: invalid
  d[0] := 0;
  d[1] := 0;
  d[2] := 1;
  d[3] := -1;
  d[4] := -1;
  d[5] := 1;
  d[6] := 1;
  d[7] := -1;
  d[8] := 0;
  d[9] := 1;

  for var i := 0 to N do
  begin
    if i >= 10 then
    begin
      if (d[i div 10] = -1) or (d[i mod 10] = -1) then
        d[i] := -1
      else
        d[i] := d[i div 10] or d[i mod 10];
    end;

    if d[i] = 1 then
      ans += 1;
  end;

  Result := ans;
end;

