function FindShortestSubArray(nums: array of integer): integer;
begin
  var numCounts := new Dictionary<integer, integer>;

  foreach var num in nums do
    if numCounts.ContainsKey(num) then
      numCounts[num] += 1
    else
      numCounts[num] := 1;

  var maxFreq := numCounts.Values.Max;

  var candidates := new List<integer>;

  foreach var kv in numCounts do
    if kv.Value = maxFreq then
      candidates.Add(kv.Key);

  var shortestSubarrayLength := nums.Length;

  foreach var candidate in candidates do
  begin
    var start := -1;
    var &end := -1;

    for var i := 0 to nums.Length - 1 do
    begin
      if nums[i] = candidate then
      begin
        if start = -1 then
          start := i;
        &end := i;
      end;
    end;

    var length := &end - start + 1;
    if length < shortestSubarrayLength then
      shortestSubarrayLength := length;
  end;

  Result := shortestSubarrayLength;
end;

function LongestCommonPrefix(strs: array of string): string;
begin
  if strs.Length = 0 then
  begin
    Result := '';
    exit;
  end;

  var shortestStr := strs.OrderBy(s -> s.Length).First;

  for var i := 1 to shortestStr.Length do
  begin
    var ch := shortestStr[i];

    for var j := 0 to strs.Length - 1 do
    begin
      if (i > strs[j].Length) or (strs[j][i] <> ch) then
      begin
        Result := shortestStr.Substring(0, i-1);
        exit;
      end;
    end;
  end;

  Result := shortestStr;
end;

function UncompressString(s: string): string;
begin
  var collapsed := new List<char>;

  for var i := 1 to s.Length do
  begin
    if (collapsed.Count = 0) or (collapsed.Last <> s[i]) then
      collapsed.Add(s[i]);
  end;

  Result := string.Join('', collapsed);
end;

function CountBinarySubstrings(s: string): integer;
begin
  var groups := new List<integer>;
  groups.Add(1);
  var total := 0;

  for var i := 2 to s.Length do
  begin
    if s[i] <> s[i-1] then
      groups.Add(1)
    else
      groups[groups.Count - 1] := groups.Last + 1;
  end;

  for var i := 1 to groups.Count - 1 do
    total := total + Min(groups[i-1], groups[i]);

  Result := total;
end;

