  foreach var item in lst do
    if counter.ContainsKey(item) then
      counter[item] += 1
    else
      counter[item] := 1;

  var frequencies := new List<(T, integer)>;

  foreach var kv in counter do
    frequencies.Add((kv.Key, kv.Value));

  Result := frequencies.ToArray;
end;

function FindLastOccurrence(A: array of integer; x: integer): integer;
begin
  var left := 0;
  var right := A.Length - 1;
  var idx := -1;

  while left <= right do
  begin
    var mid := (left + right) div 2;

    if x = A[mid] then
    begin
      idx := mid;
      left := mid + 1;
    end
    else if x < A[mid] then
      right := mid - 1
    else
      left := mid + 1;
  end;

  Result := idx;
end;

