function IsPermutation(A: array of integer): boolean;
begin
  var n := A.Length;
  var seen := new boolean[n];

  foreach var number in A do
  begin
    if (number < 1) or (number > n) then
    begin
      Result := False;
      exit;
    end;
    seen[number - 1] := True;
  end;

  for var i := 0 to seen.Length - 1 do
    if not seen[i] then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;

function MergeAlternating<T>(list1, list2: array of T): array of T;
begin
  var merged := new List<T>;
  var i := 0;
  var j := 0;

  while (i < list1.Length) or (j < list2.Length) do
  begin
    if i < list1.Length then
    begin
      merged.Add(list1[i]);
      i += 1;
    end;

    if j < list2.Length then
    begin
      merged.Add(list2[j]);
      j += 1;
    end;
  end;

  Result := merged.ToArray;
end;

