function MaxZeroSumSubarray(arr: array of integer): integer;
begin
  var maxLen := 0;
  var sumDict := new Dictionary<integer, integer>;
  sumDict[0] := -1;
  var currentSum := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    currentSum += arr[i];

    if not sumDict.ContainsKey(currentSum) then
      sumDict[currentSum] := i
    else
    begin
      var len := i - sumDict[currentSum];
      if len > maxLen then
        maxLen := len;
    end;
  end;

  Result := maxLen;
end;

function FindFirstOccurrence(nums: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := nums.Length - 1;
  var index := nums.Length;

  while left <= right do
  begin
    var mid := (left + right) div 2;

    if nums[mid] >= target then
    begin
      index := mid;
      right := mid - 1;
    end
    else
      left := mid + 1;
  end;

  Result := index;
end;

function AddWithoutPlus(a, b: integer): integer;
begin
  var x := a;
  var y := b;

  while y <> 0 do
  begin
    var carry := x and y;
    x := x xor y;
    y := carry shl 1;
  end;

  Result := x;
end;

function GetMirrorImage(a: string): string;
begin
  Result := a.Inverse;
end;

function FindLargestNonAdjacentSum(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var dp := new integer[arr.Length];
  dp[0] := arr[0];

  if arr.Length > 1 then
    dp[1] := Max(arr[0], arr[1]);

  for var i := 2 to arr.Length - 1 do
    dp[i] := Max(dp[i - 2] + arr[i], dp[i - 1]);

  Result := dp[dp.Length - 1];
end;

function FindUniqueCharacters(params args: array of string): string;
begin
  var bestString := '';
  var maxUniqueChars := 0;

  foreach var word in args do
  begin
    var charSet := new HashSet<char>(word.ToCharArray);
    var uniqueChars := charSet.Count;

    if uniqueChars > maxUniqueChars then
    begin
      maxUniqueChars := uniqueChars;
      bestString := word;
    end;
  end;

  Result := bestString;
end;

function IsValidShuffle(str1, str2, shuffledStr: string): boolean;
begin
  if str1.Length + str2.Length <> shuffledStr.Length then
  begin
    Result := False;
    exit;
  end;

  var dp := new boolean[str1.Length + 1, str2.Length + 1];
  dp[0, 0] := True;

  for var i := 1 to str1.Length do
    dp[i, 0] := dp[i - 1, 0] and (str1[i] = shuffledStr[i]);

  for var j := 1 to str2.Length do
    dp[0, j] := dp[0, j - 1] and (str2[j] = shuffledStr[j]);

  for var i := 1 to str1.Length do
    for var j := 1 to str2.Length do
      dp[i, j] := (dp[i - 1, j] and (str1[i] = shuffledStr[i + j])) or
                  (dp[i, j - 1] and (str2[j] = shuffledStr[i + j]));

  Result := dp[str1.Length, str2.Length];
end;

function NarcissisticNumber(n: integer): boolean;
begin
  var numStr := n.ToString;
  var numLen := numStr.Length;
  var sum := 0;

  for var i := 1 to numStr.Length do
  begin
    var digit := StrToInt(numStr[i].ToString);
    sum := sum + Round(Power(digit, numLen));
  end;

  Result := sum = n;
end;

function AverageOfCorrect(trainingData: array of (integer, integer)): real;
begin
  var correct := new List<integer>;

  foreach var (value, flag) in trainingData do
    if flag = 1 then
      correct.Add(value);

  if correct.Count = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sum := 0;
  foreach var val in correct do
    sum += val;

  Result := sum / correct.Count;
end;

function MinOperationsToAnagram(s, t: string): integer;
begin
  var sCount := new Dictionary<char, integer>;
  var tCount := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if sCount.ContainsKey(s[i]) then
      sCount[s[i]] += 1
    else
      sCount[s[i]] := 1;

  for var i := 1 to t.Length do
    if tCount.ContainsKey(t[i]) then
      tCount[t[i]] += 1
    else
      tCount[t[i]] := 1;

  var count := 0;

  foreach var kv in sCount do
    count += Max(0, kv.Value - tCount.Get(kv.Key, 0));

  foreach var kv in tCount do
    if not sCount.ContainsKey(kv.Key) then
      count += kv.Value;

  Result := count;
end;

function FindLargestSubarraySum(arr: array of integer): integer;
begin
  var maxSum := arr[0];
  var currentSum := arr[0];

  for var i := 1 to arr.Length - 1 do
  begin
    currentSum := Max(arr[i], currentSum + arr[i]);
    maxSum := Max(maxSum, currentSum);
  end;

  Result := maxSum;
end;

function LongPrefix(strs: array of string): string;
begin
  if strs.Length = 0 then
  begin
    Result := '';
    exit;
  end;

  var prefix := strs[0];

  for var i := 1 to strs.Length - 1 do
  begin
    while strs[i].IndexOf(prefix) <> 1 do
    begin
      prefix := prefix.Substring(0, prefix.Length - 1);
      if prefix.Length = 0 then
      begin
        Result := '';
        exit;
      end;
    end;
  end;

  Result := prefix;
end;

function LongestSubarrayWithKZeros(A: array of integer; K: integer): integer;
begin
  var left := 0;
  var right := 0;
  var zeroSize := 0;
  var ans := 0;

  while right < A.Length do
  begin
    if A[right] = 0 then
      zeroSize += 1;

    while (zeroSize > K) and (left <= right) do
    begin
      if A[left] = 0 then
        zeroSize -= 1;
      left += 1;
    end;

    var len := right - left + 1;
    if len > ans then
      ans := len;

    right += 1;
  end;

  Result := ans;
end;

function SimilarPairs(words: array of string): integer;
begin
  var hashes := new List<string>;

  foreach var word in words do
  begin
    var charSet := new HashSet<char>(word.ToCharArray);
    var chars := charSet.ToList;
    chars.Sort;
    hashes.Add(string.Join('', chars));
  end;

  var hashCount := new Dictionary<string, integer>;
  foreach var h in hashes do
    if hashCount.ContainsKey(h) then
      hashCount[h] += 1
    else
      hashCount[h] := 1;

  var pair := 0;
  foreach var cnt in hashCount.Values do
    pair := pair + (cnt * (cnt - 1)) div 2;

  Result := pair;
end;

function ConvertRomanToInt(roman: string): integer;
begin
  var romanDict := new Dictionary<char, integer>;
  romanDict.Add('I', 1);
  romanDict.Add('V', 5);
  romanDict.Add('X', 10);
  romanDict.Add('L', 50);
  romanDict.Add('C', 100);
  romanDict.Add('D', 500);
  romanDict.Add('M', 1000);

  var value := 0;

  for var i := 1 to roman.Length do
  begin
    if (i > 1) and (romanDict[roman[i]] > romanDict[roman[i-1]]) then
      value := value + romanDict[roman[i]] - 2 * romanDict[roman[i-1]]
    else
      value := value + romanDict[roman[i]];
  end;

  Result := value;
end;

function FindNoIncomingEdges(n: integer; edges: array of array of integer): array of integer;
begin
  var paths := new Dictionary<integer, HashSet<integer>>;
  var dest := new HashSet<integer>;
  var ans := new List<integer>;

  for var i := 0 to edges.Length - 1 do
  begin
    var u := edges[i][0];
    var v := edges[i][1];

    if not paths.ContainsKey(v) then
      paths[v] := new HashSet<integer>;

    paths[v].Add(u);
    dest.Add(v);
  end;

  for var i := 0 to n - 1 do
    if (not dest.Contains(i)) or (not paths.ContainsKey(i)) or (paths[i].Count = 0) then
      ans.Add(i);

  Result := ans.ToArray;
end;

function IsAnagramOfPermutation(s: string): boolean;
begin
  var charCount := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if charCount.ContainsKey(s[i]) then
      charCount[s[i]] += 1
    else
      charCount[s[i]] := 1;

  var oddCountChars := 0;

  foreach var cnt in charCount.Values do
    if cnt mod 2 <> 0 then
      oddCountChars += 1;

  Result := oddCountChars <= 1;
end;

