function LongestIncreasingSubsequence(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var dp := new integer[nums.Length];
  for var i := 0 to dp.Length - 1 do
    dp[i] := 1;

  for var i := 1 to nums.Length - 1 do
    for var j := 0 to i - 1 do
      if nums[j] < nums[i] then
        dp[i] := Max(dp[i], 1 + dp[j]);

  Result := dp.Max;
end;

