function MaxSubarray(arr: array of integer): integer;
begin
  var maxCurrent := arr[0];
  var maxGlobal := arr[0];

  for var i := 1 to arr.Length - 1 do
  begin
    maxCurrent := Max(arr[i], maxCurrent + arr[i]);
    if maxCurrent > maxGlobal then
      maxGlobal := maxCurrent;
  end;

  Result := maxGlobal;
end;

function RemoveTarget(nums: array of integer; val: integer): integer;
begin
  var i := 0;
  var N := nums.Length;

  while i < N do
  begin
    if nums[i] = val then
    begin
      nums[i] := nums[N-1];
      N -= 1;
    end
    else
      i += 1;
  end;

  Result := N;
end;

function Find2DPeak(matrix: array of array of integer): integer?;
begin
  if matrix.Length = 0 then
  begin
    Result := nil;
    exit;
  end;

  var m := matrix.Length;
  var n := matrix[0].Length;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      var isPeak := True;

      if (i > 0) and (matrix[i][j] <= matrix[i-1][j]) then
        isPeak := False;
      if (i < m-1) and (matrix[i][j] <= matrix[i+1][j]) then
        isPeak := False;
      if (j > 0) and (matrix[i][j] <= matrix[i][j-1]) then
        isPeak := False;
      if (j < n-1) and (matrix[i][j] <= matrix[i][j+1]) then
        isPeak := False;

      if isPeak then
      begin
        Result := matrix[i][j];
        exit;
      end;
    end;

  Result := nil;
end;

