function JumpClouds(clouds: array of integer): integer;
begin
  if clouds.Length <= 2 then
  begin
    Result := clouds.Length - 1;
    exit;
  end;

  var jumps := 0;
  var position := 0;

  while position < clouds.Length - 1 do
  begin
    if (position + 2 < clouds.Length) and (clouds[position + 2] = 0) then
      position += 2
    else
      position += 1;

    jumps += 1;
  end;

  Result := jumps;
end;

