function TwoSumLessThanK(A: array of integer; K: integer): integer;
begin
  var sorted := A.ToArray;
  sorted.Sort;
  var n := sorted.Length;
  var res := -1;

  for var i := 0 to n - 1 do
  begin
    var j := n - 1;
    while (j > i) and (sorted[i] + sorted[j] >= K) do
      j -= 1;

    if i >= j then
      break;

    var sum := sorted[i] + sorted[j];
    if sum > res then
      res := sum;
  end;

  Result := res;
end;

