function CalculateHCF(x, y: integer): integer;
begin
  var a := x;
  var b := y;

  while b <> 0 do
  begin
    var temp := b;
    b := a mod b;
    a := temp;
  end;

  Result := a;
end;

function FindSmallestWindow(str1, str2: string): string;
begin
  if (str1.Length = 0) or (str2.Length = 0) then
  begin
    Result := '';
    exit;
  end;

  var str2Dict := new Dictionary<char, integer>;
  for var i := 1 to str2.Length do
    if str2Dict.ContainsKey(str2[i]) then
      str2Dict[str2[i]] += 1
    else
      str2Dict[str2[i]] := 1;

  var required := str2Dict.Count;
  var formed := 0;
  var windowCounts := new Dictionary<char, integer>;

  var left := 1;
  var right := 1;
  var minLength := MaxInt;
  var minWindow := '';

  while right <= str1.Length do
  begin
    var character := str1[right];

    if windowCounts.ContainsKey(character) then
      windowCounts[character] += 1
    else
      windowCounts[character] := 1;

    if str2Dict.ContainsKey(character) and (windowCounts[character] = str2Dict[character]) then
      formed += 1;

    while (left <= right) and (formed = required) do
    begin
      var ch := str1[left];

      if right - left + 1 < minLength then
      begin
        minLength := right - left + 1;
        minWindow := str1.Substring(left - 1, minLength);
      end;

      windowCounts[ch] -= 1;
      if str2Dict.ContainsKey(ch) and (windowCounts[ch] < str2Dict[ch]) then
        formed -= 1;

      left += 1;
    end;

    right += 1;
  end;

  Result := minWindow;
end;

function FindMaxDifference(arr: array of integer): integer;
begin
  var maxDiff := 0;
  var minElement := arr[0];

  for var i := 1 to arr.Length - 1 do
  begin
    if arr[i] - minElement > maxDiff then
      maxDiff := arr[i] - minElement;

    if arr[i] < minElement then
      minElement := arr[i];
  end;

  Result := maxDiff;
end;

var partitionsResult: List<array of string>;

function IsPalindrome(subS: string): boolean;
begin
  Result := subS = subS.Inverse;
end;

procedure GeneratePartitions(remaining: string; path: List<string>);
begin
  if remaining.Length = 0 then
  begin
    partitionsResult.Add(path.ToArray);
    exit;
  end;

  for var i := 1 to remaining.Length do
  begin
    var prefix := remaining.Substring(0, i);
    if IsPalindrome(prefix) then
    begin
      path.Add(prefix);
      GeneratePartitions(remaining.Substring(i), path);
      path.RemoveAt(path.Count - 1);
    end;
  end;
end;

function PalindromicPartitions(s: string): array of array of string;
begin
  partitionsResult := new List<array of string>;

  GeneratePartitions(s, new List<string>);
  Result := partitionsResult.ToArray;
end;

type
  ListNode = auto class
    val: integer;
    next: ListNode;
  end;

function CreateLinkedList(elements: array of integer): ListNode;
begin
  var dummy := new ListNode(0, nil);
  var current := dummy;

  foreach var element in elements do
  begin
    current.next := new ListNode(element, nil);
    current := current.next;
  end;

  Result := dummy.next;
end;

function MiddleNode(head: ListNode): integer;
begin
  var slow := head;
  var fast := head;

  while (fast <> nil) and (fast.next <> nil) do
  begin
    slow := slow.next;
    fast := fast.next.next;
  end;

  Result := slow.val;
end;

