function JosephusProblem(n, k: integer): array of integer;
begin
  var circle := new List<integer>;
  for var i := 1 to n do
    circle.Add(i);

  var executionOrder := new List<integer>;
  var index := 0;

  while circle.Count > 0 do
  begin
    index := (index + k - 1) mod circle.Count;
    executionOrder.Add(circle[index]);
    circle.RemoveAt(index);
  end;

  Result := executionOrder.ToArray;
end;

function TrapWater(elevations: array of integer): integer;
begin
  if elevations.Length < 3 then
  begin
    Result := 0;
    exit;
  end;

  var left := 0;
  var right := elevations.Length - 1;
  var leftMax := elevations[left];
  var rightMax := elevations[right];
  var trappedWater := 0;

  while left < right do
  begin
    if leftMax < rightMax then
    begin
      left += 1;
      leftMax := Max(leftMax, elevations[left]);
      trappedWater += Max(0, leftMax - elevations[left]);
    end
    else
    begin
      right -= 1;
      rightMax := Max(rightMax, elevations[right]);
      trappedWater += Max(0, rightMax - elevations[right]);
    end;
  end;

  Result := trappedWater;
end;

function LuckyNumber(k: integer): string;
begin
  var digits := new List<char>;
  var pos := k + 1;

  while pos <> 1 do
  begin
    if (pos and 1) = 0 then
      digits.Add('4')
    else
      digits.Add('7');
    pos := pos shr 1;
  end;

  digits.Reverse;
  Result := string.Join('', digits);
end;

function SmallestSubWithSum(arr: array of integer; x: integer): integer;
begin
  var n := arr.Length;
  var minLen := n + 1;
  var currSum := 0;
  var start := 0;

  for var &end := 0 to n - 1 do
  begin
    currSum += arr[&end];

    while currSum >= x do
    begin
      var len := &end - start + 1;
      if len < minLen then
        minLen := len;

      currSum -= arr[start];
      start += 1;
    end;
  end;

  if minLen <= n then
    Result := minLen
  else
    Result := 0;
end;

