function GrayCodeSequence(n: integer): array of integer;
begin
  if n = 0 then
    Result := |0|
  else if n = 1 then
    Result := |0, 1|
  else
  begin
    var arr := GrayCodeSequence(n - 1);
    var baseVal := 1 shl (n - 1);
    var resultList := new List<integer>;

    resultList.AddRange(arr);

    for var i := arr.Length - 1 downto 0 do
      resultList.Add(baseVal + arr[i]);

    Result := resultList.ToArray;
  end;
end;

