function CheckReverseSort(arr: array of integer): boolean;
begin
  if arr.OrderBy(x -> x).SequenceEqual(arr) then
  begin
    Result := True;
    exit;
  end;

  for var i := 0 to arr.Length - 1 do
    for var j := i + 1 to arr.Length - 1 do
    begin
      var temp := new List<integer>;
      for var k := j downto i do
        temp.Add(arr[k]);

      var newArr := new List<integer>;
      for var k := 0 to i - 1 do
        newArr.Add(arr[k]);
      newArr.AddRange(temp);
      for var k := j + 1 to arr.Length - 1 do
        newArr.Add(arr[k]);

      if newArr.OrderBy(x -> x).SequenceEqual(newArr) then
      begin
        Result := True;
        exit;
      end;
    end;

  Result := False;
end;

function FlipCase(s: string): string;
begin
  var sb := new StringBuilder;

  for var i := 1 to s.Length do
  begin
    if Char.IsLower(s[i]) then
      sb.Append(Char.ToUpper(s[i]))
    else if Char.IsUpper(s[i]) then
      sb.Append(Char.ToLower(s[i]))
    else
      sb.Append(s[i]);
  end;

  Result := sb.ToString;
end;

function IsPossible(nums: array of integer): boolean;
begin
  var count := new Dictionary<integer, integer>;
  var &end := new Dictionary<integer, integer>;

  foreach var n in nums do
    if count.ContainsKey(n) then
      count[n] += 1
    else
      count[n] := 1;

  foreach var n in nums do
  begin
    if count[n] = 0 then
      continue;

    count[n] -= 1;

    if (&end.ContainsKey(n-1)) and (&end[n-1] > 0) then
    begin
      &end[n-1] -= 1;
      if &end.ContainsKey(n) then
        &end[n] += 1
      else
        &end[n] := 1;
    end
    else if (count.ContainsKey(n+1)) and (count[n+1] > 0) and 
            (count.ContainsKey(n+2)) and (count[n+2] > 0) then
    begin
      count[n+1] -= 1;
      count[n+2] -= 1;
      if &end.ContainsKey(n+2) then
        &end[n+2] += 1
      else
        &end[n+2] := 1;
    end
    else
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;

function FindLength(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var dp := new integer[arr.Length];
  for var i := 0 to dp.Length - 1 do
    dp[i] := 1;

  for var i := 0 to arr.Length - 1 do
    for var j := 0 to i - 1 do
      if arr[i] > arr[j] then
        dp[i] := Max(dp[i], dp[j] + 1);

  Result := dp.Max;
end;

function MaxContinuousSum(arr: array of integer): integer;
begin
  var currentSum := arr[0];
  var maxSum := arr[0];

  for var i := 1 to arr.Length - 1 do
  begin
    currentSum := Max(currentSum + arr[i], arr[i]);
    maxSum := Max(maxSum, currentSum);
  end;

  Result := maxSum;
end;

