function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
  begin
    Result := False;
    exit;
  end;

  if n <= 3 then
  begin
    Result := True;
    exit;
  end;

  if (n mod 2 = 0) or (n mod 3 = 0) then
  begin
    Result := False;
    exit;
  end;

  var i := 5;
  while i * i <= n do
  begin
    if (n mod i = 0) or (n mod (i + 2) = 0) then
    begin
      Result := False;
      exit;
    end;
    i += 6;
  end;

  Result := True;
end;

function CountPrimesBetween(start, &end: integer): integer;
begin
  var count := 0;

  for var num := start to &end do
    if IsPrime(num) then
      count += 1;

  Result := count;
end;

function ListToCommaSeparatedString(numbers: array of integer): string;
begin
  var strings := numbers.Select(n -> n.ToString).ToArray;
  Result := string.Join(',', strings);
end;

function MinOps(word1, word2: string): integer;
begin
  var dp := new integer[word2.Length + 1, word1.Length + 1];

  for var j := 0 to word1.Length do
    dp[0, j] := j;

  for var i := 0 to word2.Length do
    dp[i, 0] := i;

  for var i := 1 to word2.Length do
    for var j := 1 to word1.Length do
      if word1[j] = word2[i] then
        dp[i, j] := dp[i-1, j-1]
      else
        dp[i, j] := Min(Min(dp[i-1, j], dp[i-1, j-1]), dp[i, j-1]) + 1;

  Result := dp[word2.Length, word1.Length];
end;

function MostFrequentChar(s: string): char;
begin
  var charFrequency := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if charFrequency.ContainsKey(s[i]) then
      charFrequency[s[i]] += 1
    else
      charFrequency[s[i]] := 1;

  var maxFreq := 0;
  var mostFrequentChar := s[1];

  for var i := 1 to s.Length do
  begin
    var freq := charFrequency[s[i]];
    if freq > maxFreq then
    begin
      maxFreq := freq;
      mostFrequentChar := s[i];
    end;
  end;

  Result := mostFrequentChar;
end;

function UniqueOccurrences(arr: array of integer): boolean;
begin
  var counter := new Dictionary<integer, integer>;

  foreach var num in arr do
    if counter.ContainsKey(num) then
      counter[num] += 1
    else
      counter[num] := 1;

  var visited := new HashSet<integer>;

  foreach var val in counter.Values do
    if visited.Contains(val) then
    begin
      Result := False;
      exit;
    end
    else
      visited.Add(val);

  Result := True;
end;

function ExtractPalindromes(words: array of string): array of string;
begin
  var palindromes := new List<string>;

  foreach var word in words do
    if word = word.Inverse then
      palindromes.Add(word);

  Result := palindromes.ToArray;
end;

function NumOfWays(grid: array of array of integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var dp := new integer[m, n];

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if grid[i][j] = 1 then
        dp[i, j] := 0
      else if (i = 0) and (j = 0) then
        dp[i, j] := 1
      else if i = 0 then
        dp[i, j] := dp[i, j-1]
      else if j = 0 then
        dp[i, j] := dp[i-1, j]
      else
        dp[i, j] := dp[i-1, j] + dp[i, j-1];
    end;

  Result := dp[m-1, n-1];
end;

function DivisibleBy3(numbers: array of integer): array of integer;
begin
  var divisible := new List<integer>;

  foreach var num in numbers do
    if num mod 3 = 0 then
      divisible.Add(num);

  Result := divisible.ToArray;
end;

function ConcatArrays<T>(list1, list2: array of T): array of T;
begin
  var concatenated := new List<T>;
  concatenated.AddRange(list1);
  concatenated.AddRange(list2);
  Result := concatenated.ToArray;
end;

function IsSpecialEquivalent(A, B: string): boolean;
begin
  if A.Length <> B.Length then
  begin
    Result := False;
    exit;
  end;

  var evenA := new StringBuilder;
  var oddA := new StringBuilder;
  var evenB := new StringBuilder;
  var oddB := new StringBuilder;

  for var i := 1 to A.Length do
  begin
    if i mod 2 = 1 then
    begin
      evenA.Append(A[i]);
      evenB.Append(B[i]);
    end
    else
    begin
      oddA.Append(A[i]);
      oddB.Append(B[i]);
    end;
  end;

  var charsEvenA := evenA.ToString.ToCharArray;
  var charsOddA := oddA.ToString.ToCharArray;
  var charsEvenB := evenB.ToString.ToCharArray;
  var charsOddB := oddB.ToString.ToCharArray;

  &Array.Sort(charsEvenA);
  &Array.Sort(charsOddA);
  &Array.Sort(charsEvenB);
  &Array.Sort(charsOddB);

  Result := (new string(charsEvenA) = new string(charsEvenB)) and 
            (new string(charsOddA) = new string(charsOddB));
end;

function Magnitude(x, y: real): real;
begin
  Result := Sqrt(x*x + y*y);
end;

function MaxArithmeticSubarrays(nums: array of integer): integer;
begin
  var diffs := new Dictionary<integer, integer>[nums.Length];
  for var i := 0 to nums.Length - 1 do
    diffs[i] := new Dictionary<integer, integer>;

  var total := 0;

  for var i := 0 to nums.Length - 1 do
    for var j := 0 to i - 1 do
    begin
      var diff := nums[i] - nums[j];

      if diffs[j].ContainsKey(diff) then
        diffs[i][diff] := diffs[i].Get(diff, 0) + diffs[j][diff] + 1
      else
        diffs[i][diff] := diffs[i].Get(diff, 0) + 1;

      total += diffs[j].Get(diff, 0);
    end;

  Result := total;
end;

function MaxWorkshops(workshops: array of (integer, integer)): integer;
begin
  var sorted := workshops.OrderBy(x -> x.Item2).ToArray;
  var selected := new List<(integer, integer)>;
  selected.Add(sorted[0]);

  for var i := 1 to sorted.Length - 1 do
    if sorted[i].Item1 >= selected.Last.Item2 then
      selected.Add(sorted[i]);

  Result := selected.Count;
end;

function CountQuadruplets(nums: array of integer): integer;
begin
  var ans := 0;

  for var i := 0 to nums.Length - 4 do
    for var j := i + 1 to nums.Length - 3 do
      for var k := j + 1 to nums.Length - 2 do
        for var l := k + 1 to nums.Length - 1 do
          if nums[i] + nums[j] + nums[k] = nums[l] then
            ans += 1;

  Result := ans;
end;

function Product3(nums: array of integer): int64;
begin
  var sorted := nums.ToArray;
  sorted.Sort;
  var n := sorted.Length;

  var prod1 := int64(sorted[0]) * sorted[1] * sorted[n-1];
  var prod2 := int64(sorted[n-1]) * sorted[n-2] * sorted[n-3];

  Result := Max(prod1, prod2);
end;

function FirstRepeatingChar(s: string): char?;
begin
  var charSet := new HashSet<char>;

  for var i := 1 to s.Length do
  begin
    if charSet.Contains(s[i]) then
    begin
      Result := s[i];
      exit;
    end;
    charSet.Add(s[i]);
  end;

  Result := nil;
end;

function LargestProductSubarray(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var maxProd := nums[0];
  var minProd := nums[0];
  var overallMax := nums[0];

  for var i := 1 to nums.Length - 1 do
  begin
    var choices := |nums[i], nums[i] * maxProd, nums[i] * minProd|;
    var newMaxProd := Max(Max(choices[0], choices[1]), choices[2]);
    var newMinProd := Min(Min(choices[0], choices[1]), choices[2]);

    maxProd := newMaxProd;
    minProd := newMinProd;

    overallMax := Max(overallMax, maxProd);
  end;

  Result := overallMax;
end;

function Heptagonal(n: integer): integer;
begin
  Result := n * (5 * n - 3) div 2;
end;

function FreqWords(wordList: array of string): array of (string, integer);
begin
  var wordCount := new Dictionary<string, integer>;

  foreach var word in wordList do
    if wordCount.ContainsKey(word) then
      wordCount[word] += 1
    else
      wordCount[word] := 1;

  var frequencies := new List<(string, integer)>;
  foreach var kv in wordCount do
    frequencies.Add((kv.Key, kv.Value));

  frequencies.Sort((x, y) -> y.Item2.CompareTo(x.Item2));

  Result := frequencies.ToArray;
end;

function OctalToDecimal(octal: string): integer;
begin
  var decimalNum := 0;
  var index := 0;
  var s := octal;

  while s.Length > 0 do
  begin
    var digit := StrToInt(s.Substring(s.Length - 1));
    decimalNum := decimalNum + digit * Round(Power(8, index));
    index += 1;
    s := s.Substring(0, s.Length - 1);
  end;

  Result := decimalNum;
end;

function CalculateMaxProfit(prices: array of integer): integer;
begin
  var profit := 0;

  for var i := 1 to prices.Length - 1 do
    if prices[i] > prices[i-1] then
      profit += prices[i] - prices[i-1];

  Result := profit;
end;

function BiggestNumber(number: int64): int64;
begin
  var numStr := number.ToString;
  var digits := numStr.ToCharArray;
  &Array.Sort(digits);
  &Array.Reverse(digits);
  var resultStr := new string(digits);
  Result := StrToInt64(resultStr);
end;

function AddMatrices(m1, m2: array[,] of integer): array[,] of integer;
begin
  var rows := m1.GetLength(0);
  var cols := m1.GetLength(1);
  var sum := new integer[rows, cols];

  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
      sum[i, j] := m1[i, j] + m2[i, j];

  Result := sum;
end;

function FindRightIntervals(intervals: array of array of integer): array of integer;
begin
  var starts := new List<(integer, integer)>;

  for var i := 0 to intervals.Length - 1 do
    starts.Add((intervals[i][0], i));

  starts.Sort((x, y) -> x.Item1.CompareTo(y.Item1));

  var ans := new List<integer>;

  foreach var interval in intervals do
  begin
    var &end := interval[1];
    var idx := -1;

    for var j := 0 to starts.Count - 1 do
      if starts[j].Item1 >= &end then
      begin
        idx := starts[j].Item2;
        break;
      end;

    ans.Add(idx);
  end;

  Result := ans.ToArray;
end;

function ReverseParentheses(s: string): string;
begin
  var stack := new Stack<char>;

  for var i := 1 to s.Length do
  begin
    var ch := s[i];

    if ch <> ')' then
      stack.Push(ch)
    else
    begin
      var temp := new StringBuilder;

      while (stack.Count > 0) and (stack.Peek <> '(') do
        temp.Append(stack.Pop);

      if stack.Count > 0 then
        stack.Pop; // Remove '('

      for var j := 1 to temp.Length do
        stack.Push(temp[j]);
    end;
  end;

  var sb := new StringBuilder;
  var reversedStack := stack.Reverse.ToArray;

  foreach var ch in reversedStack do
    sb.Append(ch);

  Result := sb.ToString;
end;

function ReverseComplement(dna: string): string;
begin
  var complement := new Dictionary<char, char>;
  complement.Add('A', 'T');
  complement.Add('T', 'A');
  complement.Add('C', 'G');
  complement.Add('G', 'C');

  var sb := new StringBuilder;

  for var i := dna.Length downto 1 do
    sb.Append(complement[dna[i]]);

  Result := sb.ToString;
end;

function SumOfDigitsRaisedToPower(num: integer; pow: integer): int64;
begin
  var numStr := num.ToString;
  var sum: int64 := 0;

  for var i := 1 to numStr.Length do
  begin
    var digit := StrToInt(numStr[i].ToString);
    sum := sum + Round(Power(digit, pow));
  end;

  Result := sum;
end;

function CountCats(text: string): integer;
begin
  var lowerText := text.ToLower;
  var count := 0;
  var i := 1;

  while i <= lowerText.Length - 2 do
  begin
    if (lowerText[i] = 'c') and (lowerText[i+1] = 'a') and (lowerText[i+2] = 't') then
    begin
      // Check if it's a whole word
      var isWordStart := (i = 1) or not Char.IsLetter(lowerText[i-1]);
      var isWordEnd := (i + 2 = lowerText.Length) or not Char.IsLetter(lowerText[i+3]);

      if isWordStart and isWordEnd then
        count += 1;

      i += 3;
    end
    else
      i += 1;
  end;

  Result := count;
end;

function MaxProductNonConsecutive(nums: array of integer): int64;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  if nums.Length = 1 then
  begin
    Result := nums[0];
    exit;
  end;

  var incl := int64(nums[0]);
  var excl: int64 := 1;
  var newExcl: int64;

  for var i := 1 to nums.Length - 1 do
  begin
    newExcl := Max(excl, incl);
    incl := excl * nums[i];
    excl := newExcl;
  end;

  Result := Max(incl, excl);
end;

function BinRepresentation(decimalNum: integer): string;
begin
  if decimalNum = 0 then
  begin
    Result := '0';
    exit;
  end;

  var binary := '';
  var n := decimalNum;

  while n > 0 do
  begin
    binary := (n mod 2).ToString + binary;
    n := n div 2;
  end;

  Result := binary;
end;

var visitedGraph: HashSet<integer>;
var recStack: HashSet<integer>;
var graphGlobal: Dictionary<integer, List<integer>>;

function DfsGraph(node: integer): boolean;
begin
  if recStack.Contains(node) then
  begin
    Result := True;
    exit;
  end;

  if visitedGraph.Contains(node) then
  begin
    Result := False;
    exit;
  end;

  visitedGraph.Add(node);
  recStack.Add(node);

  if graphGlobal.ContainsKey(node) then
  begin
    foreach var neighbor in graphGlobal[node] do
      if DfsGraph(neighbor) then
      begin
        Result := True;
        exit;
      end;
  end;

  recStack.Remove(node);
  Result := False;
end;

function IsCycle(graph: Dictionary<integer, List<integer>>): boolean;
begin
  visitedGraph := new HashSet<integer>;
  recStack := new HashSet<integer>;
  graphGlobal := graph;

  foreach var node in graph.Keys do
    if DfsGraph(node) then
    begin
      Result := True;
      exit;
    end;

  Result := False;
end;

function FindMissingRepeating(arr: array of integer): array of integer;
begin
  var n := arr.Length;
  var xorAll := 0;

  for var i := 1 to n do
    xorAll := xorAll xor i;

  foreach var num in arr do
    xorAll := xorAll xor num;

  var lowbit := xorAll and -xorAll;
  var a := 0;
  var b := 0;

  foreach var num in arr do
  begin
    if (num and lowbit) <> 0 then
      a := a xor num
    else
      b := b xor num;
  end;

  for var i := 1 to n do
  begin
    if (i and lowbit) <> 0 then
      a := a xor i
    else
      b := b xor i;
  end;

  // Check which one is repeating and which is missing
  foreach var num in arr do
    if num = a then
    begin
      Result := |a, b|;
      exit;
    end;

  Result := |b, a|;
end;

function DoubleEvenIndex(lst: array of integer): array of integer;
begin
  var doubled := new integer[lst.Length];

  for var i := 0 to lst.Length - 1 do
    if i mod 2 = 0 then
      doubled[i] := lst[i] * 2
    else
      doubled[i] := lst[i];

  Result := doubled;
end;

function EvenOddReorder(arr: array of integer): array of integer;
begin
  var evenList := new List<integer>;
  var oddList := new List<integer>;

  foreach var num in arr do
    if num mod 2 = 0 then
      evenList.Add(num)
    else
      oddList.Add(num);

  evenList.AddRange(oddList);
  Result := evenList.ToArray;
end;

function CountPath(m, n: integer): integer;
begin
  if (m = 1) or (n = 1) then
    Result := 1
  else
    Result := CountPath(m-1, n) + CountPath(m, n-1);
end;

function SecondHighest(lst: array of integer): integer?;
begin
  var uniqueLst := lst.Distinct.ToList;
  uniqueLst.Sort;

  if uniqueLst.Count >= 2 then
    Result := uniqueLst[uniqueLst.Count - 2]
  else
    Result := nil;
end;

function CanIWinNimGame(n: integer): boolean;
begin
  Result := n mod 4 <> 0;
end;

function NumIdenticalPairs(nums: array of integer): integer;
begin
  var count := 0;
  var dict := new Dictionary<integer, integer>;

  foreach var num in nums do
  begin
    if dict.ContainsKey(num) then
    begin
      count += dict[num];
      dict[num] += 1;
    end
    else
      dict[num] := 1;
  end;

  Result := count;
end;

function ChangeWays(coins: array of integer; amount: integer): int64;
begin
  var dp := new int64[amount + 1];
  dp[0] := 1;

  foreach var coin in coins do
    for var x := coin to amount do
      dp[x] := dp[x] + dp[x - coin];

  Result := dp[amount];
end;

function ReplaceLongestString(strings: array of string): array of string;
begin
  var maxLen := strings.Select(s -> s.Length).Max;
  var replaced := new List<string>;

  foreach var s in strings do
    if s.Length = maxLen then
      replaced.Add('***')
    else
      replaced.Add(s);

  Result := replaced.ToArray;
end;

function SmallestDivisorThreshold(n, threshold: integer): integer;
begin
  for var i := threshold + 1 to n do
    if n mod i = 0 then
    begin
      Result := i;
      exit;
    end;

  Result := n;
end;

var parentDict: Dictionary<string, string>;

function Find(w: string): string;
begin
  var current := w;
  while parentDict[current] <> current do
    current := parentDict[current];
  Result := current;
end;

function AreSentencesSimilarTwo(words1, words2: array of string; pairs: array of array of string): boolean;
begin
  if words1.Length <> words2.Length then
  begin
    Result := False;
    exit;
  end;

  parentDict := new Dictionary<string, string>;

  foreach var p in pairs do
  begin
    foreach var w in p do
      if not parentDict.ContainsKey(w) then
        parentDict[w] := w;
  end;

  foreach var p in pairs do
  begin
    var root1 := Find(p[0]);
    var root2 := Find(p[1]);
    if root1 <> root2 then
      parentDict[root1] := root2;
  end;

  for var i := 0 to words1.Length - 1 do
  begin
    if words1[i] = words2[i] then
      continue;

    if (not parentDict.ContainsKey(words1[i])) or (not parentDict.ContainsKey(words2[i])) or 
       (Find(words1[i]) <> Find(words2[i])) then
    begin
      Result := False;
      exit;
    end;
  end;

  Result := True;
end;

function CheckRepeatedSubstring(s, t: string): boolean;
begin
  if (s.Length mod t.Length = 0) or (t.Length mod s.Length = 0) then
  begin
    if s.Length >= t.Length then
    begin
      var rep := s.Length div t.Length;
      for var i := 0 to rep - 1 do
        if s.Substring(i * t.Length, t.Length) <> t then
        begin
          Result := False;
          exit;
        end;
      Result := True;
    end
    else
    begin
      var rep := t.Length div s.Length;
      for var i := 0 to rep - 1 do
        if t.Substring(i * s.Length, s.Length) <> s then
        begin
          Result := False;
          exit;
        end;
      Result := True;
    end;
  end
  else
    Result := False;
end;

function IsPalindromePermutation(s: string): boolean;
begin
  var cleaned := s.Replace(' ', '').ToLower;
  var charCount := new Dictionary<char, integer>;

  for var i := 1 to cleaned.Length do
    if charCount.ContainsKey(cleaned[i]) then
      charCount[cleaned[i]] += 1
    else
      charCount[cleaned[i]] := 1;

  var oddCount := 0;

  foreach var cnt in charCount.Values do
    if cnt mod 2 <> 0 then
    begin
      oddCount += 1;
      if oddCount > 1 then
      begin
        Result := False;
        exit;
      end;
    end;

  Result := True;
end;

function GraphToAdjacencyMatrix(edges: array of array of integer): array[,] of integer;
begin
  // find the maximum vertex in the graph
  var maxVertex := 0;
  foreach var edge in edges do
  begin
    maxVertex := Max(maxVertex, edge[0]);
    maxVertex := Max(maxVertex, edge[1]);
  end;

  // initialize the adjacency matrix
  var adjacencyMatrix := new integer[maxVertex + 1, maxVertex + 1];

  // populate the adjacency matrix
  foreach var edge in edges do
  begin
    adjacencyMatrix[edge[0], edge[1]] := 1;
    adjacencyMatrix[edge[1], edge[0]] := 1;
  end;

  Result := adjacencyMatrix;
end;

function ReverseStringsAndList(strList: array of string): array of string;
begin
  var reversedList := new List<string>;

  for var i := strList.Length - 1 downto 0 do
  begin
    var reversed := '';
    for var j := strList[i].Length downto 1 do
      reversed += strList[i][j];
    reversedList.Add(reversed);
  end;

  Result := reversedList.ToArray;
end;

function MatchList(list1, list2: array of integer): boolean;
begin
  if (list1.Length = 0) or (list2.Length = 0) then
  begin
    Result := False;
    exit;
  end;

  if (list1[0] = list2[0]) and (list1[list1.Length - 1] = list2[list2.Length - 1]) then
    Result := True
  else
    Result := False;
end;

function CustomUppercase(s: string): string;
begin
  var sb := new StringBuilder;

  for var i := 1 to s.Length do
  begin
    var asciiVal := Ord(s[i]);
    if (asciiVal >= 97) and (asciiVal <= 122) then // ASCII values for 'a' to 'z'
      sb.Append(Chr(asciiVal - 32)) // Convert lowercase to uppercase
    else
      sb.Append(s[i]);
  end;

  Result := sb.ToString;
end;

function FirstRepeating(arr: array of integer): integer?;
begin
  var seen := new HashSet<integer>;
  var repeats := new HashSet<integer>;

  foreach var n in arr do
  begin
    if seen.Contains(n) then
      repeats.Add(n)
    else
      seen.Add(n);
  end;

  foreach var n in arr do
    if repeats.Contains(n) then
    begin
      Result := n;
      exit;
    end;

  Result := nil;
end;

function DifferenceLists<T>(list1, list2: array of T): array of T;
begin
  var set2 := new HashSet<T>(list2);
  var difference := new List<T>;

  foreach var item in list1 do
    if not set2.Contains(item) then
      difference.Add(item);

  Result := difference.ToArray;
end;

function RemoveAnagrams(words: array of string): array of string;
begin
  var answerList := new List<string>;

  for var idx := 0 to words.Length - 1 do
  begin
    if idx = 0 then
    begin
      answerList.Add(words[idx]);
      continue;
    end;

    var tempDict := new Dictionary<char, integer>;
    for var i := 1 to words[idx].Length do
    begin
      var c := words[idx][i];
      if tempDict.ContainsKey(c) then
        tempDict[c] += 1
      else
        tempDict[c] := 1;
    end;

    var tempDict1 := new Dictionary<char, integer>;
    for var i := 1 to words[idx - 1].Length do
    begin
      var c := words[idx - 1][i];
      if tempDict1.ContainsKey(c) then
        tempDict1[c] += 1
      else
        tempDict1[c] := 1;
    end;

    var areEqual := True;
    if tempDict.Count = tempDict1.Count then
    begin
      foreach var kv in tempDict do
      begin
        if not tempDict1.ContainsKey(kv.Key) or (tempDict1[kv.Key] <> kv.Value) then
        begin
          areEqual := False;
          break;
        end;
      end;
    end
    else
      areEqual := False;

    if areEqual then
      continue
    else
      answerList.Add(words[idx]);
  end;

  Result := answerList.ToArray;
end;

procedure Heapify(var nums: array of integer; heapSize, rootIndex: integer);
begin
  var largest := rootIndex;
  var leftChild := 2 * rootIndex + 1;
  var rightChild := 2 * rootIndex + 2;

  if (leftChild < heapSize) and (nums[leftChild] > nums[largest]) then
    largest := leftChild;

  if (rightChild < heapSize) and (nums[rightChild] > nums[largest]) then
    largest := rightChild;

  if largest <> rootIndex then
  begin
    Swap(nums[rootIndex], nums[largest]);
    Heapify(nums, heapSize, largest);
  end;
end;

function HeapSort(nums: array of integer): array of integer;
begin
  var arr := nums.ToArray;
  var n := arr.Length;

  for var i := n div 2 - 1 downto 0 do
    Heapify(arr, n, i);

  for var i := n - 1 downto 1 do
  begin
    Swap(arr[i], arr[0]);
    Heapify(arr, i, 0);
  end;

  Result := arr;
end;

