function Dfs(graph: Dictionary<integer, List<integer>>; v: integer; visited: HashSet<integer>; destination: integer): boolean;
begin
  visited.Add(v);

  if v = destination then
  begin
    Result := True;
    exit;
  end;

  if graph.ContainsKey(v) then
  begin
    foreach var neighbor in graph[v] do
    begin
      if not visited.Contains(neighbor) then
      begin
        if Dfs(graph, neighbor, visited, destination) then
        begin
          Result := True;
          exit;
        end;
      end;
    end;
  end;

  Result := False;
end;

function HasPath(n: integer; edges: array of array of integer; source, destination: integer): boolean;
begin
  var graph := new Dictionary<integer, List<integer>>;

  foreach var edge in edges do
  begin
    var u := edge[0];
    var v := edge[1];

    if not graph.ContainsKey(u) then
      graph[u] := new List<integer>;
    if not graph.ContainsKey(v) then
      graph[v] := new List<integer>;

    graph[u].Add(v);
    graph[v].Add(u);
  end;

  var visited := new HashSet<integer>;
  Result := Dfs(graph, source, visited, destination);
end;

