  var b1 := StrToInt(bParts[0]);
  var b2 := StrToInt(bParts[1].Substring(0, bParts[1].Length - 1));

  var realPart := a1 + b1;
  var imaginaryPart := a2 + b2;

  Result := realPart.ToString + '+' + imaginaryPart.ToString + 'i';
end;

function UniqueWays(n: integer): int64;
begin
  if n < 0 then
  begin
    Result := 0;
    exit;
  end;

  var dp := new int64[n + 1];
  dp[0] := 1;

  for var i := 1 to n do
  begin
    if i >= 1 then dp[i] += dp[i - 1];
    if i >= 3 then dp[i] += dp[i - 3];
    if i >= 4 then dp[i] += dp[i - 4];
  end;

  Result := dp[n];
end;

