function MaxPick(weights: array of integer; limit: integer): integer;
begin
  var n := weights.Length;
  var dp := new integer[limit + 1];

  for var i := 0 to n - 1 do
    for var j := limit downto weights[i] do
      dp[j] := Max(dp[j], dp[j - weights[i]] + weights[i]);

  Result := dp[limit];
end;

