function MaxProduct(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var prevMax := nums[0];
  var prevMin := nums[0];
  var maxProduct := nums[0];

  for var i := 1 to nums.Length - 1 do
  begin
    var curMax := Max(Max(prevMax * nums[i], prevMin * nums[i]), nums[i]);
    var curMin := Min(Min(prevMax * nums[i], prevMin * nums[i]), nums[i]);

    maxProduct := Max(maxProduct, curMax);

    prevMax := curMax;
    prevMin := curMin;
  end;

  Result := maxProduct;
end;

