function NumDistinctSubseq(s: string): int64;
begin
  var modVal := Round(Power(10, 9) + 7);
  var dp := new int64[s.Length + 1];
  dp[0] := 1; // empty string has one subsequence, which is itself
  var lastOccurrence := new integer[26];

  for var i := 0 to 25 do
    lastOccurrence[i] := -1;

  for var i := 1 to s.Length do
  begin
    dp[i] := (2 * dp[i-1]) mod modVal;
    var idx := Ord(s[i]) - Ord('a');

    if lastOccurrence[idx] <> -1 then
      dp[i] := (dp[i] - dp[lastOccurrence[idx]] + modVal) mod modVal;

    lastOccurrence[idx] := i - 1;
  end;

  Result := (dp[s.Length] - 1) mod modVal;
end;

function ShortestPathLength(n: integer; edges: array of array of integer; start: integer): array of integer;
begin
  var graph := new List<integer>[n+1];
  for var i := 0 to n do
    graph[i] := new List<integer>;

  foreach var edge in edges do
  begin
    graph[edge[0]].Add(edge[1]);
    graph[edge[1]].Add(edge[0]);
  end;

  var visited := new boolean[n+1];
  var distance := new integer[n+1];

  for var i := 0 to n do
    distance[i] := -1;

  distance[start] := 0;

  var queue := new Queue<integer>;
  queue.Enqueue(start);
  visited[start] := True;

  while queue.Count > 0 do
  begin
    var current := queue.Dequeue;

    foreach var neighbor in graph[current] do
    begin
      if not visited[neighbor] then
      begin
        visited[neighbor] := True;
        distance[neighbor] := distance[current] + 1;
        queue.Enqueue(neighbor);
      end;
    end;
  end;

  var paths := new integer[n];
  for var i := 0 to n-1 do
    paths[i] := distance[i+1];

  Result := paths;
end;

function Check(dist: array of integer; speed: integer; hour: real): boolean;
begin
  var cost := 0.0;

  for var i := 0 to dist.Length - 2 do
  begin
    var temp := dist[i] / speed;
    cost += Ceil(temp);
  end;

  cost := cost + dist[dist.Length-1] / speed;
  Result := cost <= hour;
end;

function MinSpeedOnTime(dist: array of integer; hour: real): integer;
begin
  var m := dist.Length;

  if m > Ceil(hour) then
  begin
    Result := -1;
    exit;
  end;

  var left := 1;
  var right := Max(dist.Max, 10000000);

  while left < right do
  begin
    var mid := (left + right) div 2;

    if Check(dist, mid, hour) then
      right := mid
    else
      left := mid + 1;
  end;

  Result := left;
end;

function NumWaysTraverseGrid(m, n: integer): int64;
begin
  if (m = 1) or (n = 1) then
  begin
    Result := 1;
    exit;
  end;

  var dp := new int64[m, n];

  for var i := 0 to m - 1 do
    dp[i, 0] := 1;

  for var j := 0 to n - 1 do
    dp[0, j] := 1;

  for var i := 1 to m - 1 do
    for var j := 1 to n - 1 do
      dp[i, j] := dp[i-1, j] + dp[i, j-1];

  Result := dp[m-1, n-1];
end;

function CalculateAverageScores(scoresList: array of (string, array of integer)): Dictionary<string, real>;
