function FindMinDiffSubarray(nums: array of integer): integer;
begin
  var freq := new Dictionary<integer, integer>;
  var span := new Dictionary<integer, (integer, integer)>;
  var maxElements := new List<integer>;
  var maxFreq := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    var n := nums[i];

    if freq.ContainsKey(n) then
      freq[n] += 1
    else
      freq[n] := 1;

    if span.ContainsKey(n) then
      span[n] := (span[n].Item1, i)
    else
      span[n] := (i, i);

    var nextMaxFreq := Max(maxFreq, freq[n]);

    if nextMaxFreq <> maxFreq then
    begin
      maxElements.Clear;
      maxElements.Add(n);
    end
    else if nextMaxFreq = freq[n] then
      maxElements.Add(n);

    maxFreq := nextMaxFreq;
  end;

  var minLength := MaxInt;

  foreach var n in maxElements do
  begin
    var (start, &end) := span[n];
    var len := &end - start + 1;
    if len < minLength then
      minLength := len;
  end;

  Result := minLength;
end;

