  var maxProduct: int64 := 0;

  for var i := 0 to numStr.Length - k do
  begin
    var product: int64 := 1;
    for var j := 0 to k - 1 do
    begin
      var digit := StrToInt(numStr[i + j + 1].ToString);
      product := product * digit;
    end;
    if product > maxProduct then
      maxProduct := product;
  end;

  Result := maxProduct;
end;

