function SimpleCalculator(expression: string): real;
begin
  var parts := expression.Split;
  var num1 := StrToFloat(parts[0]);
  var num2 := StrToFloat(parts[2]);
  var operation := parts[1];

  case operation of
    '+': Result := num1 + num2;
    '-': Result := num1 - num2;
    '*': Result := num1 * num2;
    '/': 
      begin
        if num2 <> 0 then
          Result := num1 / num2
        else
          raise new System.DivideByZeroException('Error: Division by zero');
      end;
    else
      raise new System.ArgumentException('Error: Invalid operation');
  end;
end;

