function DistributeMoney(money, children: integer): integer;
begin
  if money < children then
  begin
    Result := -1;
    exit;
  end;

  var remaining := money - children; // now everybody has 1$
  var good := remaining div 7;
  var rest := remaining mod 7;

  if good > children then
    Result := children - 1
  else if good = children then
  begin
    if rest = 0 then
      Result := children
    else
      Result := children - 1;
  end
  else // good < children
  begin
    if (good = children - 1) and (rest = 3) then
      Result := children - 2
    else
      Result := good;
  end;
end;

function NoAdjacentMaxSum(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  if arr.Length = 1 then
  begin
    Result := arr[0];
    exit;
  end;

  if arr.Length = 2 then
  begin
    Result := Max(arr[0], arr[1]);
    exit;
  end;

  var dp := new integer[arr.Length];
  dp[0] := arr[0];
  dp[1] := Max(arr[0], arr[1]);

  for var i := 2 to arr.Length - 1 do
    dp[i] := Max(dp[i-1], dp[i-2] + arr[i]);

  Result := dp[arr.Length - 1];
end;

function MaxPositiveSubarraySum(arr: array of integer): integer;
begin
  var maxSum := -MaxInt;
  var currentSum := -MaxInt;
  var maxEnd := 0;
  var currentEnd := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    currentSum := currentSum + arr[i];
    if currentSum > maxSum then
    begin
      maxSum := currentSum;
      maxEnd := i;
    end;

    if currentSum < 0 then
    begin
      currentSum := 0;
      currentEnd := i + 1;
    end;
  end;

  if maxSum <= 0 then
    maxSum := arr.Max;

  Result := maxSum;
end;

