function NextLargerWithSameBits(n: integer): integer;
begin
  var c := n;
  var c0 := 0;
  var c1 := 0;

  while ((c and 1) = 0) and (c <> 0) do
  begin
    c0 += 1;
    c := c shr 1;
  end;

  while (c and 1) = 1 do
  begin
    c1 += 1;
    c := c shr 1;
  end;

  if (c0 + c1 = 31) or (c0 + c1 = 0) then
  begin
    Result := -1;
    exit;
  end;

  var p := c0 + c1;
  var nextNum := n;

  nextNum := nextNum or (1 shl p);
  nextNum := nextNum and not ((1 shl p) - 1);
  nextNum := nextNum or ((1 shl (c1 - 1)) - 1);

  Result := nextNum;
end;

function CountAnagramSubstrings(s1, s2: string): integer;
begin
  if s1.Length > s2.Length then
  begin
    Result := 0;
    exit;
  end;

  var s1Count := new Dictionary<char, integer>;
  for var i := 1 to s1.Length do
    if s1Count.ContainsKey(s1[i]) then
      s1Count[s1[i]] += 1
    else
      s1Count[s1[i]] := 1;

  var localCount := new Dictionary<char, integer>;
  var start := 1;
  var count := 0;

  for var &end := 1 to s2.Length do
  begin
    var endChar := s2[&end];

    if localCount.ContainsKey(endChar) then
      localCount[endChar] += 1
    else
      localCount[endChar] := 1;

    if &end - start + 1 = s1.Length then
    begin
      var equal := True;

      if localCount.Count = s1Count.Count then
      begin
        foreach var kv in s1Count do
        begin
          if not localCount.ContainsKey(kv.Key) or (localCount[kv.Key] <> kv.Value) then
          begin
            equal := False;
            break;
          end;
        end;
      end
      else
        equal := False;

      if equal then
        count += 1;

      localCount[s2[start]] -= 1;
      if localCount[s2[start]] = 0 then
        localCount.Remove(s2[start]);

      start += 1;
    end;
  end;

  Result := count;
end;

