function LargestRectangleArea(heights: array of integer): integer;
begin
  var stack := new Stack<integer>;
  stack.Push(-1);
  var maxArea := 0;

  for var i := 0 to heights.Length - 1 do
  begin
    var h := heights[i];
    while (stack.Peek <> -1) and (h < heights[stack.Peek]) do
    begin
      var prevIdx := stack.Pop;
      var prevH := heights[prevIdx];
      var width := i - 1 - stack.Peek;
      var area := width * prevH;
      if area > maxArea then
        maxArea := area;
    end;
    stack.Push(i);
  end;

  while stack.Peek <> -1 do
  begin
    var prevIdx := stack.Pop;
    var prevH := heights[prevIdx];
    var width := heights.Length - stack.Peek - 1;
    var area := width * prevH;
    if area > maxArea then
      maxArea := area;
  end;

  Result := maxArea;
end;

function PrimeNumbersBelow(n: integer): array of integer;
begin
  if n <= 2 then
  begin
    Result := new integer[0];
    exit;
  end;

  var primes := new List<integer>;
  primes.Add(2);

  for var i := 3 to n - 1 step 2 do
  begin
    var isPrime := True;
    foreach var p in primes do
    begin
      if p * p > i then
        break;
      if i mod p = 0 then
      begin
        isPrime := False;
        break;
      end;
    end;
    if isPrime then
      primes.Add(i);
  end;

  Result := primes.ToArray;
end;

function MinParentheses(parentheses: string): integer;
