  var needToInsert := 0;

  for var i := 1 to parentheses.Length do
  begin
    if parentheses[i] = '(' then
      openParentheses += 1
    else if parentheses[i] = ')' then
    begin
      if openParentheses > 0 then
        openParentheses -= 1
      else
        needToInsert += 1;
    end;
  end;

  needToInsert += openParentheses;
  Result := needToInsert;
end;

function IsCyclicGraph(numCourses: integer; prerequisites: array of array of integer): boolean;
begin
  if prerequisites.Length = 0 then
  begin
    Result := False;
    exit;
  end;

  var nextCourse := new Dictionary<integer, List<integer>>;
  for var i := 0 to numCourses - 1 do
    nextCourse[i] := new List<integer>;

  var degree := new integer[numCourses];

  foreach var pre in prerequisites do
  begin
    degree[pre[0]] += 1;
    nextCourse[pre[1]].Add(pre[0]);
  end;

  var queue := new Queue<integer>;
  var processed := new List<integer>;

  for var i := 0 to degree.Length - 1 do
    if degree[i] = 0 then
      queue.Enqueue(i);

  while queue.Count > 0 do
  begin
    var course := queue.Dequeue;
    processed.Add(course);

    foreach var next in nextCourse[course] do
    begin
      degree[next] -= 1;
      if degree[next] = 0 then
        queue.Enqueue(next);
    end;
  end;

  Result := processed.Count <> numCourses;
end;

function BitConverter(A, B: integer): integer;
begin
  var xorResult := A xor B;
  var count := 0;

  while xorResult <> 0 do
  begin
    count += 1;
    xorResult := xorResult and (xorResult - 1);
  end;

  Result := count;
end;

function FindLowerBound(arr: array of integer; x: integer): integer;
begin
  var lo := 0;
  var hi := arr.Length - 1;

  while lo <= hi do
  begin
    var mid := lo + (hi - lo) div 2;
    if arr[mid] < x then
      lo := mid + 1
    else
      hi := mid - 1;
  end;

  if lo < arr.Length then
    Result := lo
  else
    Result := -1;
end;

function CanDivideInSubsequences(nums: array of integer; k: integer): boolean;
begin
  if nums.Length mod k <> 0 then
  begin
    Result := False;
    exit;
  end;

  var numCounts := new Dictionary<integer, integer>;

  foreach var num in nums do
    if numCounts.ContainsKey(num) then
      numCounts[num] += 1
    else
      numCounts[num] := 1;

  var sorted := numCounts.Keys.ToList;
  sorted.Sort;

  foreach var num in sorted do
  begin
    var needed := numCounts[num];
    if needed > 0 then
    begin
      for var i := num to num + k - 1 do
      begin
        if (not numCounts.ContainsKey(i)) or (numCounts[i] < needed) then
        begin
          Result := False;
          exit;
        end;
        numCounts[i] := numCounts[i] - needed;
      end;
    end;
  end;

  Result := True;
end;

