function LongestIncSubseq(nums: array of integer): integer;
begin
  var sz := nums.Length;
  var dp := new integer[sz];

  for var i := 0 to sz - 1 do
  begin
    dp[i] := 1;
    for var j := 0 to i - 1 do
      if nums[j] < nums[i] then
        dp[i] := Max(dp[i], dp[j] + 1);
  end;

  if sz = 0 then
    Result := 0
  else
    Result := dp.Max;
end;

function MaxAverageSubarray(nums: array of integer; k: integer): real;
begin
  if (nums.Length = 0) or (k <= 0) or (k > nums.Length) then
  begin
    Result := 0;
    exit;
  end;

  var maxSum := -MaxInt;
  var windowSum := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    windowSum += nums[i];

    if i >= k - 1 then
    begin
      if windowSum > maxSum then
        maxSum := windowSum;

      windowSum -= nums[i - k + 1];
    end;
  end;

  Result := maxSum / k;
end;

