function CheckSubarraySum(nums: array of integer; k: integer): boolean;
begin
  var remInd := new Dictionary<integer, integer>;
  remInd[0] := -1;
  var curSum := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    curSum += nums[i];
    var remainder := curSum mod k;

    if not remInd.ContainsKey(remainder) then
      remInd[remainder] := i
    else if i - remInd[remainder] > 1 then
    begin
      Result := True;
      exit;
    end;
  end;

