var partitionResult: List<array of string>;
    partitionString: string;
    partitionDp: array[,] of boolean;
    partitionN: integer;

procedure DfsPartition(start: integer; path: List<string>);
begin
  if start = partitionN then
  begin
    partitionResult.Add(path.ToArray);
    exit;
  end;

  for var i := start to partitionN - 1 do
    if partitionDp[start, i] then
    begin
      path.Add(partitionString.Substring(start, i - start + 1));
      DfsPartition(i + 1, path);
      path.RemoveAt(path.Count - 1);
    end;
end;

function PartitionPalindrome(s: string): array of array of string;
begin
  partitionResult := new List<array of string>;
  partitionString := s;
  partitionN := s.Length;

  var dp := new boolean[partitionN, partitionN];

  // Initialize DP for single characters
  for var i := 0 to partitionN - 1 do
    dp[i, i] := True;

  // Fill DP for longer substrings
  for var len := 2 to partitionN do
    for var i := 0 to partitionN - len do
    begin
      var j := i + len - 1;
      if s[i+1] = s[j+1] then
      begin
        if len = 2 then
          dp[i, j] := True
        else
          dp[i, j] := dp[i+1, j-1];
      end;
    end;

  partitionDp := dp;

  DfsPartition(0, new List<string>);
  Result := partitionResult.ToArray;
end;

function ShiftingLetters(s: string; shifts: array of array of integer): string;
begin
  var diff := new integer[s.Length + 1];

  foreach var shift in shifts do
  begin
    var start := shift[0];
    var &end := shift[1];
    var direction := shift[2];

    var delta := 1;
    if direction = 1 then
      delta := 1
    else
      delta := -1;

    diff[start] := diff[start] + delta;
    diff[&end + 1] := diff[&end + 1] - delta;
  end;

  var sb := new StringBuilder;
  var prefix := 0;

  for var i := 0 to s.Length - 1 do
  begin
    prefix := (prefix + diff[i]) mod 26;
    if prefix < 0 then
      prefix := prefix + 26;

    var newCharCode := ((Ord(s[i+1]) - Ord('a') + prefix) mod 26) + Ord('a');
    sb.Append(Chr(newCharCode));
  end;

  Result := sb.ToString;
end;

