function WordBreak(s: string; wordDict: array of string): boolean;
begin
  var n := s.Length;
  var dp := new boolean[n];

  for var i := 0 to n - 1 do
  begin
    foreach var w in wordDict do
    begin
      var startIdx := i - w.Length + 1;
      if (startIdx >= 0) and (s.Substring(startIdx, w.Length) = w) then
      begin
        if (startIdx = 0) or dp[startIdx - 1] then
        begin
          dp[i] := True;
          break;
        end;
      end;
    end;
  end;

  if n > 0 then
    Result := dp[n-1]
  else
    Result := False;
end;

