function ClosestToZero(li: array of integer): integer;
begin
  var maxDist := 100000;
  var closest := 100000;

  foreach var i in li do
  begin
    var currDist := Abs(i);

    if currDist <= maxDist then
    begin
      if currDist = Abs(closest) then
        closest := Max(i, closest)
      else if currDist < Abs(closest) then
        closest := i;

      maxDist := currDist;
    end;
  end;

  Result := closest;
end;

