  var mid := length div 2;
  var totalCost := 0;

  var sorted := costs.ToArray;
  sorted.Sort((x, y) -> (x.Item1 - x.Item2).CompareTo(y.Item1 - y.Item2));

  for var i := 0 to mid - 1 do
    totalCost := totalCost + sorted[i].Item1 + sorted[i + mid].Item2;

  Result := totalCost;
end;

