function ComputeLevenshteinDistance(str1, str2: string): integer;
begin
  var n1 := str1.Length;
  var n2 := str2.Length;
  var dp := new integer[n1 + 1, n2 + 1];

  for var j := 1 to n2 do
    dp[0, j] := dp[0, j-1] + 1;

  for var i := 1 to n1 do
    dp[i, 0] := dp[i-1, 0] + 1;

  for var i := 1 to n1 do
    for var j := 1 to n2 do
      if str1[i] = str2[j] then
        dp[i, j] := dp[i-1, j-1]
      else
        dp[i, j] := Min(Min(dp[i, j-1], dp[i-1, j]), dp[i-1, j-1]) + 1;

  Result := dp[n1, n2];
end;

var matrixWordGlobal: array of array of char;
var rowsWordGlobal: integer;
var colsWordGlobal: integer;
var visitedWord: array[,] of boolean;

function Helper(r, c, wordIndex: integer; word: string): boolean;
begin
  if wordIndex = word.Length then
  begin
    Result := True;
    exit;
  end;

  if (r < 0) or (c < 0) or (r >= rowsWordGlobal) or (c >= colsWordGlobal) or 
     visitedWord[r, c] or (matrixWordGlobal[r][c] <> word[wordIndex+1]) then
  begin
    Result := False;
    exit;
  end;

  visitedWord[r, c] := True;
  var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;

  foreach var (dr, dc) in directions do
  begin
    var nr := r + dr;
    var nc := c + dc;
    if Helper(nr, nc, wordIndex + 1, word) then
    begin
      Result := True;
      exit;
    end;
  end;

  visitedWord[r, c] := False;
  Result := False;
end;

function HasMatrixWordPath(matrix: array of array of char; word: string): boolean;
begin
  rowsWordGlobal := matrix.Length;
  colsWordGlobal := matrix[0].Length;
  matrixWordGlobal := matrix;
  visitedWord := new boolean[rowsWordGlobal, colsWordGlobal];

  for var r := 0 to rowsWordGlobal - 1 do
    for var c := 0 to colsWordGlobal - 1 do
      if matrix[r][c] = word[1] then
        if Helper(r, c, 0, word) then
        begin
          Result := True;
          exit;
        end;

  Result := False;
end;

