  if word1.Length > word2.Length then
    for var i := minLen + 1 to word1.Length do
      merged.Add(word1[i])
  else if word2.Length > word1.Length then
    for var i := minLen + 1 to word2.Length do
      merged.Add(word2[i]);

  Result := string.Join('', merged);
end;

function ConvertDecimalToBinary(decimalNumber: integer): string;
begin
  if decimalNumber = 0 then
  begin
    Result := '0';
    exit;
  end;

  var binaryDigits := new List<integer>;
  var n := decimalNumber;

  while n > 0 do
  begin
    binaryDigits.Add(n mod 2);
    n := n div 2;
  end;

  binaryDigits.Reverse;
  var sb := new StringBuilder;

  foreach var digit in binaryDigits do
    sb.Append(digit.ToString);

  Result := sb.ToString;
end;

