function CanTopologicallySort(numVertices: integer; edges: array of array of integer): boolean;
begin
  var indegrees := new integer[numVertices];
  var adjacency := new Dictionary<integer, List<integer>>;

  for var i := 0 to numVertices - 1 do
    adjacency[i] := new List<integer>;

  foreach var edge in edges do
  begin
    var cur := edge[0];
    var pre := edge[1];
    indegrees[cur] += 1;
    adjacency[pre].Add(cur);
  end;

  var queue := new Queue<integer>;

  for var i := 0 to indegrees.Length - 1 do
    if indegrees[i] = 0 then
      queue.Enqueue(i);

  var remaining := numVertices;

  while queue.Count > 0 do
  begin
    var pre := queue.Dequeue;
    remaining -= 1;

    foreach var cur in adjacency[pre] do
    begin
      indegrees[cur] -= 1;
      if indegrees[cur] = 0 then
        queue.Enqueue(cur);
    end;
  end;

  Result := remaining = 0;
end;

function ValidParenthesesCombinations(n: integer): int64;
begin
  if n = 0 then
  begin
    Result := 1;
    exit;
  end;

  if n = 1 then
  begin
    Result := 1;
    exit;
  end;

  var dp := new int64[n + 1];
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
    for var j := 0 to i - 1 do
      dp[i] := dp[i] + dp[j] * dp[i - j - 1];

  Result := dp[n];
end;

function GetPascalRow(row: integer): array of integer;
begin
  var current := new List<integer>;
  current.Add(1);

  for var i := 1 to row do
  begin
    var prev := 1;
    for var j := 1 to i - 1 do
    begin
      var temp := current[j];
      current[j] := current[j] + prev;
      prev := temp;
    end;
    current.Add(1);
  end;

  Result := current.ToArray;
end;

