function CountNonOverlappingIntervals(intervals: array of array of integer): integer;
begin
  var sorted := intervals.OrderBy(x -> x[1]).ToArray;
  var count := 1;
  var &end := sorted[0][1];

  for var i := 1 to sorted.Length - 1 do
  begin
    if sorted[i][0] > &end then
    begin
      count += 1;
      &end := sorted[i][1];
    end;
  end;

  Result := count;
end;

function SubstringFrequency(str, substr: string): integer;
begin
  var freq := 0;
  var len := substr.Length;

  // Forward search
  for var i := 1 to str.Length - len + 1 do
    if str.Substring(i-1, len) = substr then
      freq += 1;

  // Reverse search
  for var i := 1 to str.Length - len + 1 do
  begin
    var segment := str.Substring(i-1, len);
    var reversed := '';
    for var j := segment.Length downto 1 do
      reversed += segment[j];

    if reversed = substr then
      freq += 1;
  end;

  Result := freq;
end;

function CountSubarraysWithSumDivisibleByK(arr: array of integer; k: integer): integer;
begin
  var count := 0;
  var prefixSum := 0;
  var prefixSumCount := new Dictionary<integer, integer>;
  prefixSumCount[0] := 1;

  foreach var num in arr do
  begin
    prefixSum := (prefixSum + num) mod k;

    if prefixSumCount.ContainsKey(prefixSum) then
    begin
      count += prefixSumCount[prefixSum];
      prefixSumCount[prefixSum] += 1;
    end
    else
      prefixSumCount[prefixSum] := 1;
  end;

  Result := count;
end;

function Maximum(a, b, c: integer): integer;
begin
  var maxVal := a;
  if b > maxVal then
    maxVal := b;
  if c > maxVal then
    maxVal := c;
  Result := maxVal;
end;

function FindSmallestPowerOf2(n: integer): integer;
begin
  var power := 1;
  while power < n do
    power := power * 2;
  Result := power;
end;

function CountSubarrays(nums: array of integer; target: integer): integer;
begin
  var count := 0;
  var n := nums.Length;

  for var i := 0 to n - 1 do
  begin
    var currSum := nums[i];
    if currSum = target then
      count += 1;

    for var j := i + 1 to n - 1 do
    begin
      currSum += nums[j];
      if currSum = target then
        count += 1;
    end;
  end;

  Result := count;
end;

function MaxProductThreeNums(lst: array of integer): int64;
begin
  var sorted := lst.ToArray;
  sorted.Sort;
  var n := sorted.Length;

  var prod1 := int64(sorted[0]) * sorted[1] * sorted[n-1];
  var prod2 := int64(sorted[n-1]) * sorted[n-2] * sorted[n-3];

  Result := Max(prod1, prod2);
end;

function IsSubstringTwice(sub, main: string): boolean;
begin
  var lowerSub := sub.ToLower;
  var lowerMain := main.ToLower;
  var count := 0;
  var start := 1;

  while start <= lowerMain.Length do
  begin
    var index := lowerMain.IndexOf(lowerSub, start);
    if index = -1 then
      break;

    count += 1;
    start := index + 1;
  end;

  Result := count >= 2;
end;

function CollatzConjecture(num: integer): integer;
begin
  var steps := 0;
  var n := num;

  while n > 1 do
  begin
    if n mod 2 = 0 then
      n := n div 2
    else
      n := 3 * n + 1;

    steps += 1;
  end;

  Result := steps;
end;

function CanJump(nums: array of integer): boolean;
begin
  var n := nums.Length;
  var rightmost := 0;

  for var i := 0 to n - 1 do
  begin
    if i <= rightmost then
    begin
      rightmost := Max(rightmost, i + nums[i]);
      if rightmost >= n - 1 then
      begin
        Result := True;
        exit;
      end;
    end;
  end;

  Result := False;
end;

