function CountBST(n: integer): int64;
begin
  if n <= 1 then
  begin
    Result := 1;
    exit;
  end;

  var total: int64 := 0;

  for var i := 0 to n - 1 do
  begin
    var l := CountBST(i);
    var r := CountBST(n - 1 - i);
    total := total + l * r;
  end;

  Result := total;
end;

function OddPowerSum(n: integer): int64;
begin
  var sum: int64 := 0;

  for var i := 1 to n do
  begin
    var j := 2 * i - 1;
    sum := sum + j * j;
  end;

  Result := sum;
end;

function MinSwap(arr: array of integer): integer;
begin
  var n := arr.Length;
  var ans := 0;
  var temp := arr.ToArray;
  temp.Sort;
  var visited := new boolean[n];

  for var i := 0 to n - 1 do
  begin
    if visited[i] or (temp[i] = arr[i]) then
      continue;

    var cycleSize := 0;
    var j := i;

    while not visited[j] do
    begin
      visited[j] := True;

      // Find index of arr[j] in temp
      var idx := 0;
      while (idx < n) and (temp[idx] <> arr[j]) do
        idx += 1;
      j := idx;

      cycleSize += 1;
    end;

    if cycleSize > 0 then
      ans += cycleSize - 1;
  end;

  Result := ans;
end;

function MinMovesToPower(n: integer; baseNum: integer): integer;
begin
  var moves := 0;
  var num := n;

  while num <> 1 do
  begin
    if num mod baseNum = 0 then
      num := num div baseNum
    else
    begin
      if num < baseNum then
        num := num + 1
      else
        num := num - 1;
    end;

    moves += 1;
  end;

  Result := moves;
end;

function LongestOddSubarray(arr: array of integer): integer;
