  foreach var num in arr do
  begin
    if num mod 2 <> 0 then
    begin
      currentLength += 1;
      if currentLength > maxLength then
        maxLength := currentLength;
    end
    else
      currentLength := 0;
  end;

  Result := maxLength;
end;

type
  TreeNode = auto class
    val: integer;
    left: TreeNode;
    right: TreeNode;
  end;

function CheckBST(node: TreeNode; minVal, maxVal: int64): boolean;
begin
  if node = nil then
  begin
    Result := True;
    exit;
  end;

  if (node.val <= minVal) or (node.val >= maxVal) then
  begin
    Result := False;
    exit;
  end;

  Result := CheckBST(node.left, minVal, node.val) and 
            CheckBST(node.right, node.val, maxVal);
end;

function IsBST(root: TreeNode): boolean;
begin
  Result := CheckBST(root, -1000000000000, 1000000000000);
end;

function RecursionFactorial(n: integer): int64;
begin
  if n = 1 then
    Result := 1
  else
    Result := n * RecursionFactorial(n - 1);
end;

function FindNumberOfLIS(nums: array of integer): integer;
begin
  var n := nums.Length;
  var dp := ArrFill(n, (1, 1));

  var ans := 1;
  var lis := 1;

  for var i := n - 2 downto 0 do
  begin
    for var j := i + 1 to n - 1 do
    begin
      if nums[j] > nums[i] then
      begin
        var (len, cnt) := dp[j];

        if len + 1 > dp[i].Item1 then
          dp[i] := (len + 1, cnt)
        else if len + 1 = dp[i].Item1 then
          dp[i] := (dp[i].Item1, dp[i].Item2 + cnt);
      end;
    end;

    if dp[i].Item1 > lis then
    begin
      lis := dp[i].Item1;
      ans := dp[i].Item2;
    end
    else if dp[i].Item1 = lis then
      ans := ans + dp[i].Item2;
  end;

  Result := ans;
end;

function IsPrime(num: integer): boolean;
begin
  if num < 2 then
  begin
    Result := False;
    exit;
  end;

  for var i := 2 to Trunc(Sqrt(num)) do
    if num mod i = 0 then
    begin
      Result := False;
      exit;
    end;

  Result := True;
end;

