function SmallestMissing(nums: array of integer): integer;
begin
  var n := nums.Length;
  var arr := nums.ToArray;

  for var i := 0 to n - 1 do
    while (arr[i] >= 1) and (arr[i] <= n) and (arr[arr[i] - 1] <> arr[i]) do
    begin
      var temp := arr[arr[i] - 1];
      arr[arr[i] - 1] := arr[i];
      arr[i] := temp;
    end;

  for var i := 0 to n - 1 do
    if arr[i] <> i + 1 then
    begin
      Result := i + 1;
      exit;
    end;

  Result := n + 1;
end;

function MaxFreqElement(arr: array of integer): integer;
