      freq[i] += 1
    else
      freq[i] := 1;

  var maxFreq := freq.Values.Max;
  var maxFreqElements := new List<integer>;

  foreach var kv in freq do
    if kv.Value = maxFreq then
      maxFreqElements.Add(kv.Key);

  maxFreqElements.Sort;
  Result := maxFreqElements[0];
end;

