function NumUniqueBSTs(n: integer): int64;
begin
  if n <= 1 then
  begin
    Result := 1;
    exit;
  end;

  var G := new int64[n + 1];
  G[0] := 1;
  G[1] := 1;
  G[2] := 2;

  for var i := 3 to n do
  begin
    G[i] := 0;
    for var k := 0 to i - 1 do
      G[i] := G[i] + G[k] * G[i - k - 1];
  end;

  Result := G[n];
end;

function Sum67(nums: array of integer): integer;
begin
  var total := 0;
  var add := True;

  foreach var num in nums do
  begin
    if num = 6 then
      add := False;

    if add then
      total += num;

    if (num = 7) and not add then
      add := True;
  end;

  Result := total;
end;

function BisectionMethod(f: real -> real; a, b, tol: real): real;
begin
  if f(a) * f(b) >= 0 then
    raise new System.ArgumentException('The function values at the endpoints must have opposite signs.');

  var left := a;
  var right := b;

  while (right - left) / 2 > tol do
  begin
    var midpoint := (left + right) / 2;
    var fmid := f(midpoint);

    if fmid = 0 then
    begin
      Result := midpoint;
      exit;
    end
    else if f(left) * fmid < 0 then
      right := midpoint
    else
      left := midpoint;
  end;

  Result := (left + right) / 2;
end;

function FlowerBloom(flowers: array of (integer, integer); visits: array of integer): array of integer;
begin
  var startTimes := new List<integer>;
  var endTimes := new List<integer>;

  foreach var (start, &end) in flowers do
  begin
    startTimes.Add(start);
    endTimes.Add(&end);
  end;

  startTimes.Sort;
  endTimes.Sort;

  var bloomCounts := new List<integer>;

  foreach var visit in visits do
  begin
    var started := 0;
    for var i := 0 to startTimes.Count - 1 do
      if startTimes[i] <= visit then
        started += 1
      else
        break;

    var ended := 0;
    for var i := 0 to endTimes.Count - 1 do
      if endTimes[i] < visit then
        ended += 1
      else
        break;

    bloomCounts.Add(started - ended);
  end;

  Result := bloomCounts.ToArray;
end;

function IsSegmentable(s: string; wordDict: array of string): boolean;
begin
  var wordSet := new HashSet<string>(wordDict);
  var dp := new boolean[s.Length + 1];
  dp[0] := True;

  for var i := 1 to s.Length do
  begin
    for var j := 0 to i - 1 do
    begin
      if dp[j] and wordSet.Contains(s.Substring(j, i - j)) then
      begin
        dp[i] := True;
        break;
      end;
    end;
  end;

  Result := dp[s.Length];
end;

function ExtendedGCD(a, b: integer): (integer, integer, integer);
begin
  if a = 0 then
  begin
    Result := (b, 0, 1);
    exit;
  end;

  var (gcdVal, x1, y1) := ExtendedGCD(b mod a, a);
  var x := y1 - (b div a) * x1;
  var y := x1;

  Result := (gcdVal, x, y);
end;

function MaxAbsSubarray(nums: array of integer): integer;
begin
  var maxSum := nums[0];
  var currentMax := nums[0];
  var currentMin := nums[0];

  for var i := 1 to nums.Length - 1 do
  begin
    currentMax := Max(nums[i], currentMax + nums[i]);
    currentMin := Min(nums[i], currentMin + nums[i]);
    maxSum := Max(Max(maxSum, currentMax), Abs(currentMin));
  end;

  Result := maxSum;
end;

function ReverseBits(n: integer): integer;
begin
  var ans := 0;
  for var i := 0 to 31 do
  begin
    var digit := (n shr i) and 1;
    ans := ans shl 1;
    ans := ans or digit;
  end;
  Result := ans;
end;

