function UniquePathsWithObstacles(obstacleGrid: array of array of integer): integer;
begin
  var m := obstacleGrid.Length;
  var n := obstacleGrid[0].Length;

  if obstacleGrid[0][0] = 1 then
  begin
    Result := 0;
    exit;
  end;

  var dp := new integer[m, n];
  dp[0, 0] := 1;

  for var i := 1 to m - 1 do
    if (obstacleGrid[i][0] = 0) and (dp[i-1, 0] = 1) then
      dp[i, 0] := 1
    else
      dp[i, 0] := 0;

  for var j := 1 to n - 1 do
    if (obstacleGrid[0][j] = 0) and (dp[0, j-1] = 1) then
      dp[0, j] := 1
    else
      dp[0, j] := 0;

  for var i := 1 to m - 1 do
    for var j := 1 to n - 1 do
      if obstacleGrid[i][j] = 0 then
        dp[i, j] := dp[i-1, j] + dp[i, j-1]
      else
        dp[i, j] := 0;

  Result := dp[m-1, n-1];
end;

function MaxSubstringsWithoutRepeating(s: string): array of string;
begin
  var intervals := new Dictionary<char, List<integer>>;

  for var i := 1 to s.Length do
  begin
    var c := s[i];
    if not intervals.ContainsKey(c) then
      intervals[c] := new List<integer>;
    intervals[c].Add(i);
  end;

  foreach var c in intervals.Keys.ToList do
  begin
    var positions := intervals[c];
    var left := positions[0];
    var right := positions[positions.Count - 1] + 1;
    var tl := left;
    var tr := right;

    while (tl <> left) or (tr <> right) do
    begin
      left := tl;
      right := tr;

      for var i := left to right - 1 do
      begin
        var ch := s[i];
        tl := Min(tl, intervals[ch][0]);
        tr := Max(tr, intervals[ch][intervals[ch].Count - 1] + 1);
      end;

      if (tl = left) and (tr = right) then
        break;
    end;

    intervals[c] := new List<integer>([left, right]);
  end;

  var sortedIntervals := intervals.Values.ToList;
  sortedIntervals.Sort((x, y) -> x[1].CompareTo(y[1]));

  var prev := 0;
  var output := new List<string>;

  foreach var interval in sortedIntervals do
  begin
    var start := interval[0];
    var &end := interval[1];
    if start >= prev then
    begin
      output.Add(s.Substring(start-1, &end - start));
      prev := &end;
    end;
  end;

  Result := output.ToArray;
end;

