function SubstringSearch(haystack, needle: string): integer;
begin
  if needle.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  for var i := 1 to haystack.Length - needle.Length + 1 do
    if haystack.Substring(i-1, needle.Length) = needle then
    begin
      Result := i - 1;
      exit;
    end;

  Result := -1;
end;

function MaxSumNonAdjacent(arr: array of integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  if arr.Length <= 2 then
  begin
    Result := arr.Max;
    exit;
  end;

  var dp := new integer[arr.Length];
  dp[0] := arr[0];
  dp[1] := Max(arr[0], arr[1]);

  for var i := 2 to arr.Length - 1 do
    dp[i] := Max(dp[i-1], dp[i-2] + arr[i]);

  Result := dp[arr.Length - 1];
end;

function FindErrorNums(nums: array of integer): array of integer;
begin
  var n := nums.Length;
  var fullSet := new HashSet<integer>;
  for var i := 1 to n do
    fullSet.Add(i);

  var numSet := new HashSet<integer>;
  var duplicate := 0;

  foreach var num in nums do
  begin
    if numSet.Contains(num) then
      duplicate := num;
    numSet.Add(num);
  end;

  var missing := 0;
  foreach var num in fullSet do
    if not numSet.Contains(num) then
    begin
      missing := num;
      break;
    end;

  Result := |duplicate, missing|;
end;

function FindMaxPairChain(pairs: array of (integer, integer)): integer;
begin
  if pairs.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sorted := pairs.OrderBy(x -> x.Item2).ToArray;
  var currentEnd := sorted[0].Item2;
  var chainLength := 1;

  for var i := 1 to sorted.Length - 1 do
    if sorted[i].Item1 > currentEnd then
    begin
      chainLength += 1;
      currentEnd := sorted[i].Item2;
    end;

  Result := chainLength;
end;

