  end;

  Result := dict;
end;

var palStart: integer;
    palMaxLen: integer;
    palString: string;

procedure ExpandAroundCenter(left, right: integer);
begin
  var l := left;
  var r := right;

  while (l >= 1) and (r <= palString.Length) and (palString[l] = palString[r]) do
  begin
    l := l - 1;
    r := r + 1;
  end;

  var len := r - l - 1;
  if len > palMaxLen then
  begin
    palStart := l + 1;
    palMaxLen := len;
  end;
end;

function LongestPalindrome(s: string): string;
begin
  if (s.Length < 2) or (s = s.Inverse) then
  begin
    Result := s;
    exit;
  end;

  palStart := 0;
  palMaxLen := 1;
  palString := s;

  for var i := 1 to s.Length - 1 do
  begin
    ExpandAroundCenter(i, i);
    ExpandAroundCenter(i, i + 1);
  end;

  Result := s.Substring(palStart - 1, palMaxLen);
end;

function LargestConcatNumber(nums: array of integer): string;
begin
  var numStrs := nums.Select(x -> x.ToString).ToList;

  numStrs.Sort((a, b) -> 
    (b + a).CompareTo(a + b)
  );

  var largest := string.Join('', numStrs);

  // Remove leading zeros
  var i := 1;
  while (i <= largest.Length) and (largest[i] = '0') do
    i += 1;

  if i > largest.Length then
    Result := '0'
  else
    Result := largest.Substring(i-1);
end;

