type
  WordDictionary = class
  private
    lookup: Dictionary<char, object>;

    function SearchHelper(w: string; tree: Dictionary<char, object>): boolean;
    begin
      if w.Length = 0 then
      begin
        Result := tree.ContainsKey('#');
        exit;
      end;

      if w[1] = '.' then
      begin
        foreach var t in tree.Keys do
        begin
          if (t <> '#') and SearchHelper(w.Substring(1), tree[t] as Dictionary<char, object>) then
          begin
            Result := True;
            exit;
          end;
        end;
        Result := False;
      end
      else if tree.ContainsKey(w[1]) then
      begin
        Result := SearchHelper(w.Substring(1), tree[w[1]] as Dictionary<char, object>);
      end
      else
        Result := False;
    end;

  public
    constructor Create;
    begin
      lookup := new Dictionary<char, object>;
    end;

    procedure AddWord(word: string);
    begin
      var tree := lookup;
      for var i := 1 to word.Length do
      begin
        var ch := word[i];
        if not tree.ContainsKey(ch) then
          tree[ch] := new Dictionary<char, object>;
        tree := tree[ch] as Dictionary<char, object>;
      end;
      tree['#'] := new Dictionary<char, object>;
    end;

    function Search(word: string): boolean;
    begin
      Result := SearchHelper(word, lookup);
    end;
  end;

function FindWord(word: string; dictionary: array of string): boolean;
begin
  var wd := new WordDictionary;
  foreach var w in dictionary do
    wd.AddWord(w);
  Result := wd.Search(word);
end;

