function NearestSmallerElements(arr: array of integer): array of integer;
begin
  var stack := new Stack<(integer, integer)>;
  var smaller := new integer[arr.Length];

  for var i := 0 to arr.Length - 1 do
  begin
    while (stack.Count > 0) and (stack.Peek.Item1 >= arr[i]) do
      stack.Pop;

    if stack.Count = 0 then
      smaller[i] := -1
    else
      smaller[i] := stack.Peek.Item1;

    stack.Push((arr[i], i));
  end;

  Result := smaller;
end;

function RobLinear(arr: array of integer): integer;
begin
  var rob1 := 0;
  var rob2 := 0;

  foreach var n in arr do
  begin
    var newRob := Max(rob1 + n, rob2);
    rob1 := rob2;
    rob2 := newRob;
  end;

  Result := rob2;
end;

function CircularHouseRobber(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  if nums.Length = 1 then
  begin
    Result := nums[0];
    exit;
  end;

  // Choose to rob the first house or not
  var robFirst := RobLinear(nums[:nums.Length-1]);
  var robLast := RobLinear(nums[1:]);

  Result := Max(robFirst, robLast);
end;

