function MinCutsForPalindromePartition(s: string): integer;
begin
  if s.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var n := s.Length;
  var palindrome := new boolean[n, n];

  // All single characters are palindromes
  for var i := 0 to n - 1 do
    palindrome[i, i] := True;

  // Build palindrome table
  for var len := 2 to n do
    for var i := 0 to n - len do
    begin
      var j := i + len - 1;
      if s[i+1] = s[j+1] then
      begin
        if len = 2 then
          palindrome[i, j] := True
        else
          palindrome[i, j] := palindrome[i+1, j-1];
      end;
    end;

  var dp := new integer[n + 1];
  for var i := 0 to n do
    dp[i] := i - 1;

  for var left := 0 to n - 1 do
    for var right := left to n - 1 do
      if palindrome[left, right] then
        dp[right + 1] := Min(dp[right + 1], dp[left] + 1);

  Result := dp[n];
end;

