function FindPalindromicSubstrings(s: string): integer;
begin
  var palSet := new HashSet<string>;

  for var i := 1 to s.Length do
  begin
    // Odd length palindromes
    var left := i;
    var right := i;
    while (left >= 1) and (right <= s.Length) and (s[left] = s[right]) do
    begin
      palSet.Add(s.Substring(left-1, right - left + 1));
      left := left - 1;
      right := right + 1;
    end;

    // Even length palindromes
    left := i;
    right := i + 1;
    while (left >= 1) and (right <= s.Length) and (s[left] = s[right]) do
    begin
      palSet.Add(s.Substring(left-1, right - left + 1));
      left := left - 1;
      right := right + 1;
    end;
  end;

  Result := palSet.Count;
end;

function MinimumMovesToOne(n: integer): integer;
begin
