function NextGreaterElements(nums: array of integer): array of integer;
begin
  var output := new integer[nums.Length];
  for var i := 0 to output.Length - 1 do
    output[i] := -1;

  var stack := new Stack<integer>;

  for var currIdx := 0 to nums.Length - 1 do
  begin
    while (stack.Count > 0) and (nums[currIdx] > nums[stack.Peek]) do
    begin
      var idx := stack.Pop;
      output[idx] := nums[currIdx];
    end;
    stack.Push(currIdx);
  end;

  Result := output;
end;

function SortString(s: string): string;
begin
  var charCount := new Dictionary<char, integer>;

  for var i := 1 to s.Length do
    if charCount.ContainsKey(s[i]) then
      charCount[s[i]] += 1
    else
      charCount[s[i]] := 1;

  var sortedChars := charCount.Keys.ToList;
  sortedChars.Sort;

  var revSortedChars := sortedChars.ToList;
  revSortedChars.Reverse;

  var rearranged := '';

  while rearranged.Length < s.Length do
  begin
    foreach var ch in sortedChars do
    begin
      if charCount[ch] > 0 then
      begin
        rearranged := rearranged + ch;
        charCount[ch] := charCount[ch] - 1;
      end;
    end;

    foreach var ch in revSortedChars do
    begin
      if charCount[ch] > 0 then
      begin
        rearranged := rearranged + ch;
        charCount[ch] := charCount[ch] - 1;
      end;
    end;
  end;

  Result := rearranged;
end;

