function MissingInt(arr: array of integer): integer;
begin
  var positiveArr := arr.Where(x -> x > 0).ToList;
  positiveArr.Add(0);
  var n := positiveArr.Count;
  var tempArr := positiveArr.ToArray;

  for var i := 0 to n - 1 do
  begin
    while (tempArr[i] >= 0) and (tempArr[i] < n) and (tempArr[tempArr[i]] <> tempArr[i]) do
    begin
      var temp := tempArr[tempArr[i]];
      tempArr[tempArr[i]] := tempArr[i];
      tempArr[i] := temp;
    end;
  end;

  for var i := 0 to n - 1 do
    if tempArr[i] <> i then
    begin
      Result := i;
      exit;
    end;

  Result := n;
end;

