var adjListGlobal: Dictionary<integer, List<integer>>;

function DfsTree(source: integer; parent: integer; visitedSet: HashSet<integer>): boolean;
begin
  foreach var vertex in adjListGlobal[source] do
  begin
    if not visitedSet.Contains(vertex) then
    begin
      visitedSet.Add(vertex);
      if DfsTree(vertex, source, visitedSet) then
      begin
        Result := True;
        exit;
      end;
    end
    else if vertex <> parent then
    begin
      Result := True;
      exit;
    end;
  end;
  Result := False;
end;

function ValidTree(n: integer; edges: array of array of integer): boolean;
begin
  // Construct the adjacency list
  adjListGlobal := new Dictionary<integer, List<integer>>;
  for var i := 0 to n - 1 do
    adjListGlobal[i] := new List<integer>;

  for var i := 0 to edges.Length - 1 do
  begin
    var u := edges[i][0];
    var v := edges[i][1];
    adjListGlobal[u].Add(v);
    adjListGlobal[v].Add(u);
  end;

  var visitedSet := new HashSet<integer>;
  var connected := 0;

  for var node := 0 to n - 1 do
  begin
    if not visitedSet.Contains(node) then
    begin
      visitedSet.Add(node);

      if DfsTree(node, -1, visitedSet) then
      begin
        Result := False;
        exit;
      end;

      connected := connected + 1;
      if connected > 1 then
      begin
        Result := False;
        exit;
      end;
    end;
  end;

  Result := True;
end;

function SortZeroOneTwo(arr: array of integer): array of integer;
begin
  var sorted := arr.ToArray;
  var low := 0;
  var mid := 0;
  var high := sorted.Length - 1;

  while mid <= high do
  begin
    if sorted[mid] = 0 then
    begin
      Swap(sorted[low], sorted[mid]);
      low := low + 1;
      mid := mid + 1;
    end
    else if sorted[mid] = 1 then
      mid := mid + 1
    else
    begin
      Swap(sorted[mid], sorted[high]);
      high := high - 1;
    end;
  end;

  Result := sorted;
end;

function Turn(digit: char): (string, string);
begin
  var d := StrToInt(digit.ToString);
  var up := ((d + 1) mod 10).ToString;
  var down := ((d - 1 + 10) mod 10).ToString;
  Result := (up, down);
end;

function Neighbors(state: string): IEnumerable<string>;
begin
  var neighborList := new List<string>;
  for var i := 1 to 4 do
  begin
    var digit := state[i];
    var (up, down) := Turn(digit);
    neighborList.Add(state.Substring(0, i-1) + up + state.Substring(i));
    neighborList.Add(state.Substring(0, i-1) + down + state.Substring(i));
  end;
  Result := neighborList;
end;

function FindMinimumMoves(deadends: array of string; target: string): integer;
begin
  var dead := new HashSet<string>(deadends);
  var queue := new Queue<(string, integer)>;
  queue.Enqueue(('0000', 0));
  var visited := new HashSet<string>;
  visited.Add('0000');

  while queue.Count > 0 do
  begin
    var (state, steps) := queue.Dequeue;

    if dead.Contains(state) then
      continue;

    if state = target then
    begin
      Result := steps;
      exit;
    end;

    foreach var nextState in Neighbors(state) do
    begin
      if not visited.Contains(nextState) then
      begin
        visited.Add(nextState);
        queue.Enqueue((nextState, steps + 1));
      end;
    end;
  end;

  Result := -1;
end;

