function ReverseDict(d: Dictionary<integer, integer>): Dictionary<integer, object>;
begin
  var reverse := new Dictionary<integer, List<integer>>;

  foreach var kv in d do
  begin
    if not reverse.ContainsKey(kv.Value) then
      reverse[kv.Value] := new List<integer>;

    reverse[kv.Value].Add(kv.Key);
  end;

  var reversedDict := new Dictionary<integer, object>;

  foreach var kv in reverse do
  begin
    if kv.Value.Count = 1 then
      reversedDict[kv.Key] := kv.Value[0]
    else
      reversedDict[kv.Key] := kv.Value.ToArray;
  end;

  Result := reversedDict;
end;

