function PrimeFactorization(n: integer): array of integer;
begin
  var i := 2;
  var num := n;
  var factors := new List<integer>;

  while i * i <= num do
  begin
    if num mod i = 0 then
    begin
      num := num div i;
      factors.Add(i);
    end
    else
      i := i + 1;
  end;

  if num > 1 then
    factors.Add(num);

  Result := factors.ToArray;
end;

function NumOfDivisors(n: integer): integer;
begin
  var factors := PrimeFactorization(n);
  var factorCounts := new Dictionary<integer, integer>;

  foreach var f in factors do
    if factorCounts.ContainsKey(f) then
      factorCounts[f] := factorCounts[f] + 1
    else
      factorCounts[f] := 1;

  var totalDivisors := 1;

  foreach var count in factorCounts.Values do
    totalDivisors := totalDivisors * (count + 1);

  Result := totalDivisors;
end;

