function GrayCode(n: integer): array of integer;
begin
  if n = 0 then
    Result := |0|
  else
  begin
    var prevGray := GrayCode(n - 1);
    var graySeq := new List<integer>;
    graySeq.AddRange(prevGray);

    for var i := prevGray.Length - 1 downto 0 do
      graySeq.Add(prevGray[i] + (1 shl (n - 1)));

    Result := graySeq.ToArray;
  end;
end;

function SquareExceptMax(nums: array of integer): array of int64;
begin
  var maxVal := nums.Max;
  var transformed := new List<int64>;

  foreach var num in nums do
    if num = maxVal then
      transformed.Add(int64(num) * num * num)
    else
      transformed.Add(int64(num) * num);

  Result := transformed.ToArray;
end;

function CyclicRotation<T>(aList: array of T; rotations: integer): array of T;
begin
  var length := aList.Length;
  var rot := rotations mod length;

  var rotated := new List<T>;

  for var i := length - rot to length - 1 do
    rotated.Add(aList[i]);

  for var i := 0 to length - rot - 1 do
    rotated.Add(aList[i]);

  Result := rotated.ToArray;
end;

function BuildGraph(targetGrid: array of array of integer; colors: HashSet<integer>): (Dictionary<integer, HashSet<integer>>, Dictionary<integer, integer>);
begin
  var m := targetGrid.Length;
  var n := targetGrid[0].Length;
  var graph := new Dictionary<integer, HashSet<integer>>;
  var indegree := new Dictionary<integer, integer>;

  foreach var color in colors do
  begin
    var x1 := m;
    var y1 := n;
    var x2 := -1;
    var y2 := -1;

    for var i := 0 to m - 1 do
      for var j := 0 to n - 1 do
        if targetGrid[i][j] = color then
        begin
          if i < x1 then x1 := i;
          if j < y1 then y1 := j;
          if i > x2 then x2 := i;
          if j > y2 then y2 := j;
        end;

    if x2 = -1 then
      continue;

    for var i := x1 to x2 do
      for var j := y1 to y2 do
        if targetGrid[i][j] <> color then
        begin
          if not indegree.ContainsKey(targetGrid[i][j]) then
            indegree[targetGrid[i][j]] := 0;
          indegree[targetGrid[i][j]] := indegree[targetGrid[i][j]] + 1;

          if not graph.ContainsKey(color) then
            graph[color] := new HashSet<integer>;

          graph[color].Add(targetGrid[i][j]);
        end;
  end;

  Result := (graph, indegree);
end;

function TopologicalSort(graph: Dictionary<integer, HashSet<integer>>; indegree: Dictionary<integer, integer>): boolean;
begin
  var queue := new Queue<integer>;

  foreach var color in graph.Keys do
    if not indegree.ContainsKey(color) then
      queue.Enqueue(color);

  var visited := new HashSet<integer>;

  while queue.Count > 0 do
  begin
    var color := queue.Dequeue;
    visited.Add(color);

    if graph.ContainsKey(color) then
    begin
      foreach var neighbor in graph[color] do
      begin
        indegree[neighbor] := indegree[neighbor] - 1;
        if indegree[neighbor] = 0 then
          queue.Enqueue(neighbor);
      end;
    end;
  end;

  Result := visited.Count = graph.Count;
end;

function CanPrintMatrix(targetGrid: array of array of integer): boolean;
begin
  var colors := new HashSet<integer>;

  for var i := 0 to targetGrid.Length - 1 do
    for var j := 0 to targetGrid[0].Length - 1 do
      colors.Add(targetGrid[i][j]);

  var (graph, indegree) := BuildGraph(targetGrid, colors);
  Result := TopologicalSort(graph, indegree);
end;

