function CheckIfExist(arr: array of integer): boolean;
begin
  var counter := new Dictionary<integer, integer>;

  foreach var num in arr do
    if counter.ContainsKey(num) then
      counter[num] := counter[num] + 1
    else
      counter[num] := 1;

  foreach var num in arr do
  begin
    if (num <> 0) and counter.ContainsKey(num * 2) and (counter[num * 2] >= 1) then
    begin
      Result := True;
      exit;
    end;

    // Special handling for zero
    if (num = 0) and counter.ContainsKey(0) and (counter[0] >= 2) then
    begin
      Result := True;
      exit;
    end;
  end;

  Result := False;
end;

function LongestSubsequence(arr: array of integer; k: integer): integer;
begin
  var dp := new Dictionary<integer, integer>;
  var maxLen := 0;
  foreach var num in arr do
  begin
    var current := 0;
    if dp.ContainsKey(num + k) then
      current := max(current, dp[num + k] + 1);
    if dp.ContainsKey(num - k) then
      current := max(current, dp[num - k] + 1);
    current := max(current, 1);

    if dp.ContainsKey(num) then
      dp[num] := max(dp[num], current)
    else
      dp[num] := current;

    maxLen := max(maxLen, dp[num]);
  end;
  Result := maxLen;
end;

function HistogramArea(heights: array of integer): integer;
begin
  var stack := new Stack<integer>;
  var maxArea := 0;
  var index := 0;

  while index < heights.Length do
  begin
    if (stack.Count = 0) or (heights[stack.Peek] <= heights[index]) then
    begin
      stack.Push(index);
      index += 1;
    end
    else
    begin
      var top := stack.Pop;
      var area := heights[top] * (if stack.Count > 0 then index - stack.Peek - 1 else index);
      if area > maxArea then
        maxArea := area;
    end;
  end;

  while stack.Count > 0 do
  begin
    var top := stack.Pop;
    var area := heights[top] * (if stack.Count > 0 then index - stack.Peek - 1 else index);
    if area > maxArea then
      maxArea := area;
  end;

  Result := maxArea;
end;

function LongestSubarrayProduct(nums: array of integer; threshold: integer): integer;
begin
  var left := 0;
  var maxLen := 0;
  var prod := 1;

  for var right := 0 to nums.Length - 1 do
  begin
    prod *= nums[right];
    while (prod >= threshold) and (left <= right) do
    begin
      prod := prod div nums[left];
      left += 1;
    end;
    var currentLen := right - left + 1;
    if currentLen > maxLen then
      maxLen := currentLen;
  end;

  Result := maxLen;
end;

