function MinimumDeviation(nums: array of integer): integer;
begin
  var queue := new List<integer>;
  var maxVal := -MaxInt;

  foreach var num in nums do
  begin
    var val := num;
    if val mod 2 = 1 then
      val := val * 2;
    queue.Add(-val); // negative for max-heap simulation
    if val > maxVal then
      maxVal := val;
  end;

  queue.Sort;
  var res := MaxInt;

  while True do
  begin
    var current := -queue[0];
    res := min(res, maxVal - current);
    if current mod 2 = 1 then
      break;
    current := current div 2;
    queue.RemoveAt(0);
    queue.Add(-current);
    queue.Sort;
    if current > maxVal then
      maxVal := current;
  end;

  Result := res;
end;

