function ReverseInteger(x: integer): integer;
begin
  var reversed: int64 := 0;
  var sign := sign(x);
  var val := abs(x);

  while val > 0 do
  begin
    reversed := reversed * 10 + (val mod 10);
    val := val div 10;
  end;

  reversed := reversed * sign;

  if (reversed < -MaxInt - 1) or (reversed > MaxInt) then
    Result := 0
  else
    Result := integer(reversed);
end;

