function FindLongestSubstringWithoutRepeatingCharacters(s: string): string;
begin
  if (s = nil) or (s.Length <= 1) then
  begin
    Result := s;
    exit;
  end;

  var start := 0;
  var maxLen := 0;
  var maxSubstring := '';
  var charMap := new Dictionary<char, integer>;

  for var &end := 0 to s.Length - 1 do
  begin
    if charMap.ContainsKey(s[&end]) then
      start := max(start, charMap[s[&end]] + 1);
    charMap[s[&end]] := &end;

    var currentLen := &end - start + 1;
    if currentLen > maxLen then
    begin
      maxLen := currentLen;
      maxSubstring := s.Substring(start, currentLen);
    end;
  end;

  Result := maxSubstring;
end;

