    exit;
  end;

  var temp := list1 + list1;

  for var i := 0 to list1.Length - 1 do
  begin
    var &match := true;
    for var j := 0 to list2.Length - 1 do
      if temp[i + j] <> list2[j] then
      begin
        &match := false;
        break;
      end;
    if &match then
    begin
      Result := true;
      exit;
    end;
  end;

  Result := false;
end;

procedure Heapify(var arr: array of integer; n, i: integer; isMaxHeap: boolean);
begin
  if isMaxHeap then
  begin
    var largest := i;
    var l := 2 * i + 1;
    var r := 2 * i + 2;

    if (l < n) and (arr[l] > arr[largest]) then
      largest := l;
    if (r < n) and (arr[r] > arr[largest]) then
      largest := r;

    if largest <> i then
    begin
      Swap(arr[i], arr[largest]);
      Heapify(arr, n, largest, isMaxHeap);
    end;
  end
  else
  begin
    var smallest := i;
    var l := 2 * i + 1;
    var r := 2 * i + 2;

    if (l < n) and (arr[l] < arr[smallest]) then
      smallest := l;
    if (r < n) and (arr[r] < arr[smallest]) then
      smallest := r;

    if smallest <> i then
    begin
      Swap(arr[i], arr[smallest]);
      Heapify(arr, n, smallest, isMaxHeap);
    end;
  end;
end;

procedure BuildHeap(var arr: array of integer; isMaxHeap: boolean);
begin
  var n := arr.Length;
  for var i := (n - 1) div 2 downto 0 do
    Heapify(arr, n, i, isMaxHeap);
end;

function FindMaxMinHeap(arr: array of integer): (integer, integer);
