  BuildHeap(maxHeap, true);
  BuildHeap(minHeap, false);

  Result := (maxHeap[0], minHeap[0]);
end;

function ConvertTernary(number: string; toTernary: boolean): string;
begin
  if toTernary then
  begin
    var num := integer.Parse(number);
    if num = 0 then
    begin
      Result := '0';
      exit;
    end;
    var digits := new List<string>;
    while num > 0 do
    begin
      digits.Add((num mod 3).ToString);
      num := num div 3;
    end;
    digits.Reverse;
    Result := string.Join('', digits);
  end
  else
  begin
    var answer := 0;
    var numStr := number;
    for var i := 0 to numStr.Length - 1 do
    begin
      var digit := integer.Parse(numStr[numStr.Length - 1 - i].ToString);
      answer := answer + digit * Round(Power(3, i));
    end;
    Result := answer.ToString;
  end;
end;

function PolygonArea(vertices: array of (real, real)): real;
begin
  var area := 0.0;
  var n := vertices.Length;

  for var i := 0 to n - 1 do
  begin
    var j := (i + 1) mod n;
    area := area + vertices[i].Item1 * vertices[j].Item2;
    area := area - vertices[j].Item1 * vertices[i].Item2;
  end;

  Result := Abs(area) / 2;
end;

