function ShortestSubarraySort(arr: array of integer): integer;
begin
  var n := arr.Length;
  var start := -1;
  var &end := -1;
  var maxSoFar := -MaxInt;
  var minSoFar := MaxInt;

  for var i := 0 to n - 1 do
  begin
    if arr[i] < maxSoFar then
      &end := i
    else
      maxSoFar := arr[i];

    if arr[n - 1 - i] > minSoFar then
      start := n - 1 - i
    else
      minSoFar := arr[n - 1 - i];
  end;

  if start = -1 then
    Result := 0
  else
    Result := &end - start + 1;
end;

function FindUniquePairs(arr: array of integer; k: integer): integer;
