    if elements.ContainsKey(num + k) then
      count := count + elements[num + k];
    if elements.ContainsKey(num - k) then
      count := count + elements[num - k];

    if elements.ContainsKey(num) then
      elements[num] := elements[num] + 1
    else
      elements[num] := 1;
  end;

  Result := count;
end;

