function OrangesRotting(grid: array[,] of integer): integer;
begin
  var queue := new Queue<(integer, integer)>;
  var rows := grid.GetLength(0);
  var cols := grid.GetLength(1);
  var fresh := 0;

  for var row := 0 to rows - 1 do
    for var col := 0 to cols - 1 do
      if grid[row, col] = 2 then
        queue.Enqueue((row, col))
      else if grid[row, col] = 1 then
        fresh += 1;

  if fresh = 0 then
  begin
    Result := 0;
    exit;
  end;

  var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;
  var days := 0;

  while queue.Count > 0 do
  begin
    for var i := 0 to queue.Count - 1 do
    begin
      var (row, col) := queue.Dequeue;
      foreach var d in directions do
      begin
        var newRow := row + d.Item1;
        var newCol := col + d.Item2;
        if (newRow >= 0) and (newRow < rows) and (newCol >= 0) and (newCol < cols) and (grid[newRow, newCol] = 1) then
        begin
          grid[newRow, newCol] := 2;
          fresh -= 1;
          queue.Enqueue((newRow, newCol));
        end;
      end;
    end;
    days += 1;
  end;

  if fresh > 0 then
    Result := -1
  else
    Result := days - 1;
end;

