function NumValidParentheses(n: integer): integer;
begin
  if (n = 0) or (n = 1) then
  begin
    Result := 1;
    exit;
  end;

  var a := new integer[n + 1];
  a[0] := 1;
  a[1] := 1;

  for var i := 2 to n do
  begin
    a[i] := 0;
    for var j := 0 to i - 1 do
      a[i] := a[i] + a[j] * a[i - j - 1];
  end;

  Result := a[n];
end;

type UnionFind = class
  private
    parent: array of integer;
    rank: array of integer;
    minEdge: array of integer;
  public
    constructor Create(n: integer);
    begin
      parent := ArrGen(n, i -> i);
      rank := new integer[n];
      minEdge := ArrGen(n, i -> MaxInt);
    end;

    function Find(node: integer): integer;
    begin
      if parent[node] <> node then
        parent[node] := Find(parent[node]);
      Result := parent[node];
    end;

    procedure Union(node1, node2, distance: integer);
    begin
      var rep1 := Find(node1);
      var rep2 := Find(node2);

      if rep1 = rep2 then
      begin
        minEdge[rep1] := Min(Min(minEdge[rep1], minEdge[rep2]), distance);
        exit;
      end;

      if rank[rep1] > rank[rep2] then
      begin
        parent[rep2] := rep1;
        minEdge[rep1] := Min(Min(minEdge[rep1], minEdge[rep2]), distance);
      end
      else if rank[rep2] > rank[rep1] then
      begin
        parent[rep1] := rep2;
        minEdge[rep2] := Min(Min(minEdge[rep1], minEdge[rep2]), distance);
      end
      else
      begin
        parent[rep2] := rep1;
        rank[rep1] += 1;
        minEdge[rep1] := Min(Min(minEdge[rep1], minEdge[rep2]), distance);
      end;
    end;

    function GetMinEdge: integer;
    begin
      Result := minEdge[Find(0)];
    end;
end;

function MinRoadDistance(roads: array of (integer, integer, integer)): integer;
begin
  var maxCity := 0;
  foreach var road in roads do
  begin
    maxCity := Max(maxCity, road.Item1);
    maxCity := Max(maxCity, road.Item2);
  end;

  var uf := new UnionFind(maxCity);

  foreach var road in roads do
    uf.Union(road.Item1 - 1, road.Item2 - 1, road.Item3);

  Result := uf.GetMinEdge;
end;

