function NextPermutation(nums: array of integer): array of integer;
begin
  var n := nums.Length;
  var i := n - 2;

  while (i >= 0) and (nums[i] >= nums[i + 1]) do
    i -= 1;

  if i >= 0 then
  begin
    var j := n - 1;
    while (j >= 0) and (nums[i] >= nums[j]) do
      j -= 1;
    Swap(nums[i], nums[j]);
  end;

  var left := i + 1;
  var right := n - 1;
  while left < right do
  begin
    Swap(nums[left], nums[right]);
    left += 1;
    right -= 1;
  end;

  Result := nums;
end;

function IsSortedLexicographically(words: array of string; order: string): boolean;
begin
  var orderIndex := new Dictionary<char, integer>;
  for var i := 0 to order.Length - 1 do
    orderIndex[order[i]] := i;

  for var i := 0 to words.Length - 2 do
  begin
    var word1 := words[i];
    var word2 := words[i + 1];
    var minLen := Min(word1.Length, word2.Length);
    var found := false;

    for var j := 0 to minLen - 1 do
    begin
      if word1[j] <> word2[j] then
      begin
        if orderIndex[word1[j]] > orderIndex[word2[j]] then
        begin
          Result := false;
          exit;
        end;
        found := true;
        break;
      end;
    end;

    if not found and (word1.Length > word2.Length) then
    begin
      Result := false;
      exit;
    end;
  end;

  Result := true;
end;

function ShortestSubarray(nums: array of integer): integer;
begin
  var sortedNums := nums.OrderBy(x -> x).ToArray;
  var start := -1;
  var &end := -1;

  for var i := 0 to nums.Length - 1 do
    if nums[i] <> sortedNums[i] then
    begin
      if start = -1 then
        start := i;
      &end := i;
    end;

  if start = -1 then
    Result := 0
  else
    Result := &end - start + 1;
end;

function MinJump(arr: array of integer): integer;
begin
  var n := arr.Length;
  if (n = 0) or (arr[0] = 0) then
  begin
    Result := MaxInt;
    exit;
  end;

  var jumps := new integer[n];
  jumps[0] := 0;

  for var i := 1 to n - 1 do
  begin
    jumps[i] := MaxInt;
    for var j := 0 to i - 1 do
    begin
      if (i <= j + arr[j]) and (jumps[j] <> MaxInt) then
      begin
        jumps[i] := Min(jumps[i], jumps[j] + 1);
        break;
      end;
    end;
  end;

  Result := jumps[n - 1];
end;

