function DistinctAfterOperations(nums: array of integer; k: integer): integer;
begin
  var current := nums.ToList;

  for var op := 1 to k do
  begin
    var counter := new HashSet<integer>(current);
    if counter.Count = 1 then
    begin
      Result := 1;
      exit;
    end;

    var temp := new List<integer>;
    for var i := 1 to current.Count - 1 do
      temp.Add(current[i - 1] + current[i]);

    current := temp;
    if current.Count <= 1 then
      break;
  end;

  Result := (new HashSet<integer>(current)).Count;
end;

function CheckPreorder(preOrder: array of integer): boolean;
begin
  var stack := new Stack<integer>;
  var lower := -MaxInt;

  foreach var node in preOrder do
  begin
    if node < lower then
    begin
      Result := false;
      exit;
    end;

    while (stack.Count > 0) and (node > stack.Peek) do
      lower := stack.Pop;

    stack.Push(node);
  end;

  Result := true;
end;

