function MazeTraverse(n, m: integer): integer;
begin
  if (n = 1) or (m = 1) then
  begin
    Result := 1;
    exit;
  end;

  var dp := new integer[n, m];

  for var i := 0 to n - 1 do
    dp[i, 0] := 1;
  for var j := 0 to m - 1 do
    dp[0, j] := 1;

  for var i := 1 to n - 1 do
    for var j := 1 to m - 1 do
      dp[i, j] := dp[i - 1, j] + dp[i, j - 1];

  Result := dp[n - 1, m - 1];
end;

function LargestRectangleHistogram(histogram: array of integer): integer;
begin
  var stack := new Stack<integer>;
  var index := 0;
  var maxArea := 0;

  while index < histogram.Length do
  begin
    if (stack.Count = 0) or (histogram[stack.Peek] <= histogram[index]) then
    begin
      stack.Push(index);
      index += 1;
    end
    else
    begin
      var topOfStack := stack.Pop;
      var area := histogram[topOfStack] * 
                 (if stack.Count > 0 then index - stack.Peek - 1 else index);
      if area > maxArea then
        maxArea := area;
    end;
  end;

  while stack.Count > 0 do
  begin
    var topOfStack := stack.Pop;
    var area := histogram[topOfStack] * 
               (if stack.Count > 0 then index - stack.Peek - 1 else index);
    if area > maxArea then
      maxArea := area;
  end;

  Result := maxArea;
end;

