function ProductPalindrome(n: integer): integer;
begin
  var maxNum := int64(Power(10, n) - 1);
  var minNum := int64(Power(10, n - 1));
  var maxPalindrome := 0;

  for var i := maxNum downto minNum do
  begin
    for var j := i downto minNum do
    begin
      var product := i * j;
      if product <= maxPalindrome then
        break;
      var productStr := product.ToString;
      var isPalindrome := true;
      for var k := 1 to productStr.Length div 2 do
        if productStr[k] <> productStr[productStr.Length - k + 1] then
        begin
          isPalindrome := false;
          break;
        end;
      if isPalindrome then
        maxPalindrome := product;
    end;
  end;

  Result := maxPalindrome;
end;

