function MaxProfitTwoTransactions(prices: array of integer): integer;
begin
  if prices.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var firstBuy := MaxInt;
  var firstSell := 0;
  var secondBuy := MaxInt;
  var secondSell := 0;

  foreach var price in prices do
  begin
    if price < firstBuy then
      firstBuy := price;
    if price - firstBuy > firstSell then
      firstSell := price - firstBuy;
    if price - firstSell < secondBuy then
      secondBuy := price - firstSell;
    if price - secondBuy > secondSell then
      secondSell := price - secondBuy;
  end;

  Result := secondSell;
end;

function StairsWays(n: integer): integer;
