function LongestPalindromeDP(s: string): string;
begin
  if string.IsNullOrEmpty(s) then
  begin
    Result := '';
    exit;
  end;

  var n := s.Length;
  var table := new boolean[n, n];
  var maxLength := 1;
  var start := 0;

  for var i := 0 to n - 1 do
    table[i, i] := true;

  for var i := 0 to n - 2 do
    if s[i] = s[i + 1] then
    begin
      table[i, i + 1] := true;
      start := i;
      maxLength := 2;
    end;

  for var length := 3 to n do
    for var i := 0 to n - length do
    begin
      var j := i + length - 1;
      if (s[i] = s[j]) and table[i + 1, j - 1] then
      begin
        table[i, j] := true;
        start := i;
        maxLength := length;
      end;
    end;

  Result := s.Substring(start, maxLength);
end;

function MergeAlternately(word1, word2: string): string;
begin
  var len1 := word1.Length;
  var len2 := word2.Length;
  var shorter := '';
  var extra := '';

  if len1 < len2 then
  begin
    shorter := word1;
    extra := word2.Substring(len1);
  end
  else if len2 < len1 then
  begin
    shorter := word2;
    extra := word1.Substring(len2);
  end
  else
    shorter := word1;

  var sb := new StringBuilder;
  for var i := 0 to shorter.Length - 1 do
    sb.Append(word1[i]).Append(word2[i]);
  sb.Append(extra);

  Result := sb.ToString;
end;

