function DetectPalindrome(S: string): boolean;
begin
  var left := 0;
  var right := S.Length - 1;

  while left < right do
  begin
    while (left < right) and not char.IsLetterOrDigit(S[left]) do
      left += 1;
    while (left < right) and not char.IsLetterOrDigit(S[right]) do
      right -= 1;

    if char.ToLower(S[left]) <> char.ToLower(S[right]) then
    begin
      Result := false;
      exit;
    end;

    left += 1;
    right -= 1;
  end;

  Result := true;
end;

