function MaxDepthTree(tree: array of integer): integer;
begin
  if tree.Length = 0 then
  begin
    Result := 1;
    exit;
  end;

  var depth := 1;
  var i := 0;

  while i < tree.Length do
  begin
    if (2 * i + 1 < tree.Length) and (tree[2 * i + 1] <> 0) then
    begin
      var leftTree := new List<integer>;
      for var j := 2 * i + 1 to tree.Length - 1 do
        leftTree.Add(tree[j]);
      depth := Max(depth, MaxDepthTree(leftTree.ToArray) + 1);
    end;

    if (2 * i + 2 < tree.Length) and (tree[2 * i + 2] <> 0) then
    begin
      var rightTree := new List<integer>;
      for var j := 2 * i + 2 to tree.Length - 1 do
        rightTree.Add(tree[j]);
      depth := Max(depth, MaxDepthTree(rightTree.ToArray) + 1);
    end;

    i += 1;
  end;

  Result := depth;
end;

function CountBitStrings(n: integer): integer;
