  var a := new integer[n + 1];
  var b := new integer[n + 1];
  a[0] := 1;
  b[0] := 0;

  for var i := 1 to n do
  begin
    a[i] := a[i - 1] + b[i - 1];
    b[i] := a[i - 1];
  end;

  Result := a[n] + b[n];
end;

