function MinStepsPalindrome(s: string): integer;
  function LPS(s: string; i, j: integer): integer;
  begin
    if i > j then
      Result := 0
    else if i = j then
      Result := 1
    else if (s[i] = s[j]) and (i + 1 = j) then
      Result := 2
    else if s[i] = s[j] then
      Result := LPS(s, i + 1, j - 1) + 2
    else
      Result := Max(LPS(s, i, j - 1), LPS(s, i + 1, j));
  end;
begin
  Result := s.Length - LPS(s, 0, s.Length - 1);
end;

