procedure DFSComp(node: integer);
begin
  compVisited[node] := true;
  for var neighbor := 0 to compN - 1 do
    if (compMatrix[node, neighbor] = 1) and not compVisited[neighbor] then
      DFSComp(neighbor);
end;

