function ZigzagLevelOrder(root: TreeNode): array of array of integer;
begin
  var levelLists := new List<List<integer>>;

  if root = nil then
  begin
    Result := levelLists.Select(x -> x.ToArray).ToArray;
    exit;
  end;

  var queue := new Queue<TreeNode>;
  queue.Enqueue(root);
  var leftToRight := true;

  while queue.Count > 0 do
  begin
    var levelSize := queue.Count;
    var currentLevel := new List<integer>;

    for var i := 0 to levelSize - 1 do
    begin
      var node := queue.Dequeue;
      if leftToRight then
        currentLevel.Add(node.val)
      else
        currentLevel.Insert(0, node.val);

      if node.left <> nil then
        queue.Enqueue(node.left);
      if node.right <> nil then
        queue.Enqueue(node.right);
    end;

    levelLists.Add(currentLevel);
    leftToRight := not leftToRight;
  end;

  Result := levelLists.Select(x -> x.ToArray).ToArray;
end;

