function CheckTicTacToe(board: array of string): boolean;
begin
  var tictactoe := string.Join('', board);
  var x := 0;
  var o := 0;

  foreach var ch in tictactoe do
    if ch = 'X' then
      x += 1
    else if ch = 'O' then
      o += 1;

  var xWins := false;
  var oWins := false;

  // Check diagonals
  if (board[0][1] = 'X') and (board[1][1] = 'X') and (board[2][2] = 'X') then xWins := true;
  if (board[0][2] = 'X') and (board[1][1] = 'X') and (board[2][0] = 'X') then xWins := true;
  if (board[0][1] = 'O') and (board[1][1] = 'O') and (board[2][2] = 'O') then oWins := true;
  if (board[0][2] = 'O') and (board[1][1] = 'O') and (board[2][0] = 'O') then oWins := true;

  // Check rows and columns
  for var i := 0 to 2 do
  begin
    if (board[i][1] = 'X') and (board[i][2] = 'X') and (board[i][3] = 'X') then xWins := true;
    if (board[1][i] = 'X') and (board[2][i] = 'X') and (board[3][i] = 'X') then xWins := true;
    if (board[i][1] = 'O') and (board[i][2] = 'O') and (board[i][3] = 'O') then oWins := true;
    if (board[1][i] = 'O') and (board[2][i] = 'O') and (board[3][i] = 'O') then oWins := true;
  end;

  if xWins and oWins then
  begin
    Result := false;
    exit;
  end;

  if xWins then
  begin
    Result := x = o + 1;
    exit;
  end;

  if oWins then
  begin
    Result := x = o;
    exit;
  end;

  if o > x then
  begin
    Result := false;
    exit;
  end;

  Result := (x = o) or (x = o + 1);
end;

