function FindFirstLastPosition(nums: array of integer; target: integer): array of integer;
  function FindFirst: integer;
  begin
    var left := 0;
    var right := nums.Length - 1;
    while left <= right do
    begin
      var mid := (left + right) div 2;
      if nums[mid] < target then
        left := mid + 1
      else
        right := mid - 1;
    end;
    if (left < nums.Length) and (nums[left] = target) then
      Result := left
    else
      Result := -1;
  end;

  function FindLast: integer;
  begin
    var left := 0;
    var right := nums.Length - 1;
    while left <= right do
    begin
      var mid := (left + right) div 2;
      if nums[mid] <= target then
        left := mid + 1
      else
        right := mid - 1;
    end;
    if (right >= 0) and (nums[right] = target) then
      Result := right
    else
      Result := -1;
  end;
begin
  Result := |FindFirst, FindLast|;
end;

type TreeNode = class
  val: integer;
  left: TreeNode;
  right: TreeNode;
  constructor Create(v: integer);
  begin
    val := v;
    left := nil;
    right := nil;
  end;
end;

function BuildCompleteBinaryTree(values: array of integer): TreeNode;
begin
  if values.Length = 0 then
  begin
    Result := nil;
    exit;
  end;

  var root := new TreeNode(values[0]);
  var nodeQueue := new List<TreeNode>;
  nodeQueue.Add(root);
  var idx := 1;

  while idx < values.Length do
  begin
    var node := nodeQueue[0];
    nodeQueue.RemoveAt(0);

    if idx < values.Length then
    begin
      node.left := new TreeNode(values[idx]);
      nodeQueue.Add(node.left);
      idx += 1;
    end;

    if idx < values.Length then
    begin
      node.right := new TreeNode(values[idx]);
      nodeQueue.Add(node.right);
      idx += 1;
    end;
  end;

  Result := root;
end;

function LevelOrderTraversal(root: TreeNode): array of integer;
begin
  if root = nil then
  begin
    Result := new integer[0];
    exit;
  end;

  var traversal := new List<integer>;
  var queue := new Queue<TreeNode>;
  queue.Enqueue(root);

  while queue.Count > 0 do
  begin
    var current := queue.Dequeue;
    traversal.Add(current.val);

    if current.left <> nil then
      queue.Enqueue(current.left);
    if current.right <> nil then
      queue.Enqueue(current.right);
  end;

  Result := traversal.ToArray;
end;

function LevelOrderCompleteBinaryTree(values: array of integer): array of integer;
begin
  var root := BuildCompleteBinaryTree(values);
  Result := LevelOrderTraversal(root);
end;

function KaprekarsConstant(num: integer): integer;
begin
  if num = 6174 then
  begin
    Result := 6174;
    exit;
  end;

  if num = 4444 then
  begin
    Result := 0;
    exit;
  end;

  var numList := num.ToString.ToCharArray.Select(ch -> integer.Parse(ch.ToString)).ToList;
  while numList.Count < 4 do
    numList.Add(0);

  numList.Sort;
  var smallest := integer.Parse(string.Join('', numList.Select(x -> x.ToString)));

  numList.Sort((x, y) -> y.CompareTo(x));
  var largest := integer.Parse(string.Join('', numList.Select(x -> x.ToString)));

  Result := KaprekarsConstant(largest - smallest);
end;

function JumpGame(arr: array of integer): integer;
begin
  if arr.Length <= 1 then
  begin
    Result := 0;
    exit;
  end;

  var jumps := 0;
  var current := 0;
  var farthest := 0;

  for var i := 0 to arr.Length - 2 do
  begin
    farthest := Max(farthest, i + arr[i]);

    if i = current then
    begin
      jumps += 1;
      current := farthest;
      if current >= arr.Length - 1 then
        break;
    end;
  end;

  Result := jumps;
end;

