function FindZeroSumSubarrays(nums: array of integer): integer;
begin
  var n := nums.Length;
  var maxSubarrays := 0;
  var prefixSum := new integer[n + 1];

  for var i := 1 to n do
    prefixSum[i] := prefixSum[i - 1] + nums[i - 1];

  var count := new Dictionary<integer, integer>;
  for var i := 0 to n do
  begin
    if count.ContainsKey(prefixSum[i]) then
    begin
      maxSubarrays += count[prefixSum[i]];
      count[prefixSum[i]] += 1;
    end
    else
      count[prefixSum[i]] := 1;
  end;

  Result := maxSubarrays;
end;

function MaxSubarraySumWithTarget(arr: array of integer; target: integer): integer;
begin
  var maxLen := 0;
  var currSum := 0;
  var sumDict := new Dictionary<integer, integer>;
  sumDict[0] := -1;

  for var i := 0 to arr.Length - 1 do
  begin
    currSum += arr[i];
    if not sumDict.ContainsKey(currSum) then
      sumDict[currSum] := i;
    if sumDict.ContainsKey(currSum - target) then
      maxLen := max(maxLen, i - sumDict[currSum - target]);
  end;

  if maxLen > 0 then
    Result := target
  else
    Result := 0;
end;

