function FindLeastUnique(arr: array of integer; k: integer): integer;
begin
  var count := new Dictionary<integer, integer>;
  foreach var num in arr do
    if count.ContainsKey(num) then
      count[num] += 1
    else
      count[num] := 1;

  var freqList := count.Values.OrderBy(x -> x).ToList;
  var removed := 0;
  var idx := 0;

  while (k > 0) and (idx < freqList.Count) do
  begin
    if freqList[idx] <= k then
    begin
      k -= freqList[idx];
      removed += 1;
    end
    else
      break;
    idx += 1;
  end;

  Result := freqList.Count - removed;
end;

