function MaxInSubarrays(arr: array of integer; k: integer): array of integer;
begin
  if (arr.Length = 0) or (k <= 0) then
  begin
    Result := new integer[0];
    exit;
  end;

  var maxElements := new List<integer>;
  var window := new Queue<integer>;

  for var i := 0 to arr.Length - 1 do
  begin
    while (window.Count > 0) and (arr[window.Last] <= arr[i]) do
      window.Dequeue;
    window.Enqueue(i);

    if window.First <= i - k then
      window.Dequeue;

    if i + 1 >= k then
      maxElements.Add(arr[window.First]);
  end;

  Result := maxElements.ToArray;
end;

