function BinaryAddition(a, b: string): string;
begin
  var sum := '';
  var carry := 0;
  var i := a.Length;
  var j := b.Length;

  while (i > 0) or (j > 0) do
  begin
    var total := carry;
    if i > 0 then
    begin
      total += integer.Parse(a[i].ToString);
      i -= 1;
    end;
    if j > 0 then
    begin
      total += integer.Parse(b[j].ToString);
      j -= 1;
    end;

    if total = 0 then
    begin
      sum := '0' + sum;
      carry := 0;
    end
    else if total = 1 then
    begin
      sum := '1' + sum;
      carry := 0;
    end
    else if total = 2 then
    begin
      sum := '0' + sum;
      carry := 1;
    end
    else if total = 3 then
    begin
      sum := '1' + sum;
      carry := 1;
    end;
  end;

  if carry <> 0 then
    sum := '1' + sum;

  Result := sum;
end;

function BridgeCrossing(bridgeLength, weight: integer; truckWeights: array of integer): integer;
begin
  var time := 0;
  var bridge := new Queue<integer>;
  for var i := 1 to bridgeLength do
    bridge.Enqueue(0);

  var trucks := new Queue<integer>(truckWeights);
  var currentWeight := 0;

  while trucks.Count > 0 do
  begin
    currentWeight -= bridge.Dequeue;

    if currentWeight + trucks.Peek <= weight then
    begin
      var truck := trucks.Dequeue;
      bridge.Enqueue(truck);
      currentWeight += truck;
    end
    else
      bridge.Enqueue(0);

    time += 1;
  end;

  while bridge.Count > 0 do
  begin
    bridge.Dequeue;
    time += 1;
  end;

  Result := time;
end;

function BinarySearch(nums: array of integer; target: integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := -1;
    exit;
  end;

  var left := 0;
  var right := nums.Length - 1;

  while left <= right do
  begin
    var mid := (left + right) div 2;
    if nums[mid] = target then
    begin
      Result := mid;
      exit;
    end
    else if nums[mid] < target then
      left := mid + 1
    else
      right := mid - 1;
  end;

  Result := -1;
end;

function CountOccurrence(nums: array of integer; target: integer): integer;
begin
  var firstIndex := BinarySearch(nums, target);
  if firstIndex = -1 then
  begin
    Result := 0;
    exit;
  end;

  var count := 1;
  var left := firstIndex - 1;
  while (left >= 0) and (nums[left] = target) do
  begin
    count += 1;
    left -= 1;
  end;

  var right := firstIndex + 1;
  while (right < nums.Length) and (nums[right] = target) do
  begin
    count += 1;
    right += 1;
  end;

  Result := count;
end;

