function MaxNumDeletingKDigits(num: string; k: integer): string;
begin
  var stack := new Stack<char>;
  var toDelete := k;

  foreach var digit in num do
  begin
    while (toDelete > 0) and (stack.Count > 0) and (stack.Peek < digit) do
    begin
      stack.Pop;
      toDelete -= 1;
    end;
    stack.Push(digit);
  end;

  while toDelete > 0 do
  begin
    stack.Pop;
    toDelete -= 1;
  end;

  var chars := stack.ToArray;
  System.Array.Reverse(chars);
  Result := new string(chars);
end;

