function IsGroupable(hand: array of integer; groupSize: integer): boolean;
begin
  if hand.Length mod groupSize <> 0 then
  begin
    Result := false;
    exit;
  end;

  var count := new Dictionary<integer, integer>;
  foreach var card in hand do
    if count.ContainsKey(card) then
      count[card] += 1
    else
      count[card] := 1;

  var minHeap := new List<integer>;
  foreach var key in count.Keys do
    minHeap.Add(key);
  minHeap.Sort;

  while minHeap.Count > 0 do
  begin
    var first := minHeap[0];

    for var card := first to first + groupSize - 1 do
    begin
      if not minHeap.Contains(card) then
      begin
        Result := false;
        exit;
      end;

      count[card] -= 1;

      if count[card] = 0 then
      begin
        if card <> minHeap[0] then
        begin
          Result := false;
          exit;
        end;
        minHeap.RemoveAt(0);
      end;
    end;
  end;

  Result := true;
end;

function MinConferenceRooms(meetings: array of (integer, integer)): integer;
begin
  if meetings.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var sorted := meetings.OrderBy(m -> m.Item1).ToArray;
  var minHeap := new List<integer>;
  minHeap.Add(sorted[0].Item2);

  for var i := 1 to sorted.Length - 1 do
  begin
    minHeap.Sort;
    if sorted[i].Item1 >= minHeap[0] then
    begin
      minHeap.RemoveAt(0);
      minHeap.Add(sorted[i].Item2);
    end
    else
      minHeap.Add(sorted[i].Item2);
  end;

  Result := minHeap.Count;
end;

function MaxNonoverlappingIntervals(intervals: array of (integer, integer)): integer;
begin
  var sorted := intervals.OrderBy(x -> x.Item2).ToArray;
  var count := 1;
  var &end := sorted[0].Item2;

  for var i := 1 to sorted.Length - 1 do
    if sorted[i].Item1 >= &end then
    begin
      count += 1;
      &end := sorted[i].Item2;
    end;

  Result := count;
end;

function CountStrictlyIncreasing(lst: array of integer): integer;
