  var uniqueLst := new List<integer>;
  var prev := -MaxInt;

  foreach var num in lst do
    if num > prev then
    begin
      uniqueLst.Add(num);
      prev := num;
    end;

  Result := uniqueLst.Count;
end;

type IntTuple = (integer, integer);

function KSmallestPairs(nums1, nums2: array of integer; k: integer): array of (integer, integer);
begin
  if (nums1.Length = 0) or (nums2.Length = 0) then
  begin
    Result := new IntTuple[0];
    exit;
  end;

  var res := new List<(integer, integer)>;
  var heap := new List<(integer, integer, integer)>;
  heap.Add((nums1[0] + nums2[0], 0, 0));

  var visited := new HashSet<(integer, integer)>;
  visited.Add((0, 0));

  while (heap.Count > 0) and (res.Count < k) do
  begin
    heap.Sort((x, y) -> x.Item1.CompareTo(y.Item1));
    var (t, i, j) := heap[0];
    heap.RemoveAt(0);

    res.Add((nums1[i], nums2[j]));

    if (j + 1 < nums2.Length) and not visited.Contains((i, j + 1)) then
    begin
      heap.Add((nums1[i] + nums2[j + 1], i, j + 1));
      visited.Add((i, j + 1));
    end;

    if (j = 0) and (i + 1 < nums1.Length) and not visited.Contains((i + 1, j)) then
    begin
      heap.Add((nums1[i + 1] + nums2[j], i + 1, j));
      visited.Add((i + 1, j));
    end;
  end;

  Result := res.ToArray;
end;

function Levenshtein(s1, s2: string): integer;
begin
  if s1.Length < s2.Length then
    Result := Levenshtein(s2, s1)
  else if s2.Length = 0 then
    Result := s1.Length
  else
  begin
    var previousRow := ArrGen(s2.Length + 1, i -> i);

    for var i := 0 to s1.Length - 1 do
    begin
      var currentRow := new List<integer>;
      currentRow.Add(i + 1);

      for var j := 0 to s2.Length - 1 do
      begin
        var insertions := previousRow[j + 1] + 1;
        var deletions := currentRow[j] + 1;
        var substitutions := previousRow[j] + (if s1[i + 1] <> s2[j + 1] then 1 else 0);
        currentRow.Add(min(min(insertions, deletions), substitutions));
      end;

      previousRow := currentRow.ToArray;
    end;

    Result := previousRow[previousRow.Length - 1];
  end;
end;

function LongestSubarrayEqualZerosOnes(arr: array of integer): integer;
begin
  var maxLength := 0;
  var count := 0;
  var sumDict := new Dictionary<integer, integer>;
  sumDict[0] := -1;
  var maxSum := 0;

  for var i := 0 to arr.Length - 1 do
  begin
    if arr[i] = 0 then
      count -= 1
    else
      count += 1;

    if sumDict.ContainsKey(count) then
      maxLength := max(maxLength, i - sumDict[count])
    else
      sumDict[count] := i;

    if count = 0 then
      maxSum := max(maxSum, i + 1);
  end;

  Result := max(maxLength, maxSum);
end;

function BinarySearchFirst(arr: array of integer; target: integer): integer;
begin
  var left := 0;
  var right := arr.Length - 1;
  var idx := -1;

  while left <= right do
  begin
    var mid := left + (right - left) div 2;
    if arr[mid] = target then
    begin
      idx := mid;
      right := mid - 1;
    end
    else if arr[mid] < target then
      left := mid + 1
    else
      right := mid - 1;
  end;

  Result := idx;
end;

function SmallestInRotated(nums: array of integer): integer;
begin
  var n := nums.Length;
  var low := 0;
  var high := n - 1;

  while low < high do
  begin
    var mid := low + (high - low) div 2;
    if nums[mid] > nums[high] then
      low := mid + 1
    else
      high := mid;
  end;

  Result := low;
end;

procedure Dfs(grid: array[,] of integer; i, j: integer; direction: string; var shape: List<string>);
begin
  if (i < 0) or (i >= grid.GetLength(0)) or (j < 0) or (j >= grid.GetLength(1)) or (grid[i, j] = 0) then
    exit;

  grid[i, j] := 0;
  shape.Add(direction);

  Dfs(grid, i + 1, j, 'D', shape);
  Dfs(grid, i - 1, j, 'U', shape);
  Dfs(grid, i, j + 1, 'R', shape);
  Dfs(grid, i, j - 1, 'L', shape);
  shape.Add('B'); // Backtrack marker
end;

function CountDistinctIslands(grid: array[,] of integer): integer;
begin
  var shapes := new HashSet<string>;
  var rows := grid.GetLength(0);
  var cols := grid.GetLength(1);

  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
      if grid[i, j] = 1 then
      begin
        var shape := new List<string>;
        Dfs(grid, i, j, 'S', shape); // 'S' for start
        shapes.Add(string.Join('', shape));
      end;

  Result := shapes.Count;
end;

