function UniquePath(grid: array[,] of integer): integer;
begin
  if grid[0, 0] = 1 then
  begin
    Result := 0;
    exit;
  end;

  var m := grid.GetLength(0);
  var n := grid.GetLength(1);
  var dp := new integer[m, n];
  dp[0, 0] := 1;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
    begin
      if (grid[i, j] = 1) or ((i = 0) and (j = 0)) then
        continue;

      var fromUp := if i > 0 then dp[i - 1, j] else 0;
      var fromLeft := if j > 0 then dp[i, j - 1] else 0;
      dp[i, j] := fromUp + fromLeft;
    end;

  Result := dp[m - 1, n - 1];
end;

