function FindConsecutiveSums(target: integer): array of array of integer;
begin
  var sequences := new List<array of integer>;

  for var i := 1 to target - 1 do
  begin
    var sum := 0;
    for var j := i to target - 1 do
    begin
      sum += j;
      if sum = target then
      begin
        var seq := new List<integer>;
        for var k := i to j do
          seq.Add(k);
        sequences.Add(seq.ToArray);
        break;
      end
      else if sum > target then
        break;
    end;
  end;

  Result := sequences.ToArray;
end;

function ShortestSubarrayToSort(nums: array of integer): integer;
begin
  var n := nums.Length;
  if n <= 1 then
  begin
    Result := 0;
    exit;
  end;

  var first := nums[0];
  var last := nums[n - 1];
  var start := 0;
  var &end := 0;

  for var i := 1 to n - 1 do
  begin
    if nums[i] < first then
      &end := i
    else
      first := nums[i];

    if last < nums[n - 1 - i] then
      start := n - 1 - i
    else
      last := nums[n - 1 - i];
  end;

  if &end <> 0 then
    Result := &end - (n + start) + 1
  else
    Result := 0;
end;

function UniqueElement(nums: array of integer): integer;
begin
  var lo := 0;
  var hi := nums.Length - 1;

  while lo < hi do
  begin
    var mid := lo + (hi - lo) div 2;
    var halvesAreEven := (hi - mid) mod 2 = 0;

    if (mid + 1 <= hi) and (nums[mid + 1] = nums[mid]) then
    begin
      if halvesAreEven then
        lo := mid + 2
      else
        hi := mid - 1;
    end
    else if (mid - 1 >= lo) and (nums[mid - 1] = nums[mid]) then
    begin
      if halvesAreEven then
        hi := mid - 2
      else
        lo := mid + 1;
    end
    else
    begin
      Result := nums[mid];
      exit;
    end;
  end;

  Result := nums[lo];
end;

function MinPathTriangle(triangle: array of array of integer): integer;
begin
  var tri := triangle.Select(row -> row.ToList).ToList;

  for var row := tri.Count - 2 downto 0 do
    for var col := 0 to tri[row].Count - 1 do
      tri[row][col] := tri[row][col] + min(tri[row + 1][col], tri[row + 1][col + 1]);

  Result := tri[0][0];
end;

function EventualSafeStates(graph: array of array of integer): array of integer;
begin
  var n := graph.Length;
  var safe := new boolean[n];
  var graphSet := graph.Select(lst -> lst.ToHashSet).ToArray;
  var reverseGraph := ArrGen(n, i -> new HashSet<integer>);
  var queue := new Queue<integer>;

  for var i := 0 to n - 1 do
  begin
    if graph[i].Length = 0 then
      queue.Enqueue(i);
    foreach var neigh in graph[i] do
      reverseGraph[neigh].Add(i);
  end;

  while queue.Count > 0 do
  begin
    var current := queue.Dequeue;
    safe[current] := true;
    foreach var neigh in reverseGraph[current] do
    begin
      graphSet[neigh].Remove(current);
      if graphSet[neigh].Count = 0 then
        queue.Enqueue(neigh);
    end;
  end;

  var safeStates := new List<integer>;
  for var i := 0 to n - 1 do
    if safe[i] then
      safeStates.Add(i);

  Result := safeStates.ToArray;
end;

