function MissingPositive(nums: array of integer): integer;
begin
  var n := nums.Length;
  var arr := nums.Copy;

  for var i := 0 to n - 1 do
  begin
    while (1 <= arr[i]) and (arr[i] <= n) and (arr[arr[i] - 1] <> arr[i]) do
      Swap(arr[arr[i] - 1], arr[i]);
  end;

  for var i := 0 to n - 1 do
    if arr[i] <> i + 1 then
    begin
      Result := i + 1;
      exit;
    end;

  Result := n + 1;
end;

function DailyTemperatures(T: array of integer): array of integer;
begin
  var ans := new integer[T.Length];

  for var i := T.Length - 2 downto 0 do
  begin
    var nxt := i + 1;
    while T[i] >= T[nxt] do
    begin
      if ans[nxt] = 0 then
        break;
      nxt += ans[nxt];
    end;
    if T[nxt] > T[i] then
      ans[i] := nxt - i;
  end;

  Result := ans;
end;

function EvenFibonacciSum(limit: integer): integer;
begin
  var a := 1;
  var b := 2;
  var evenSum := 0;

  while b <= limit do
  begin
    if b mod 2 = 0 then
      evenSum += b;
    (a, b) := (b, a + b);
  end;

  Result := evenSum;
end;

function LengthOfLongestSubstringThreeDistinct(s: string): integer;
begin
  var maxLen := 0;
  var chars := new Dictionary<char, integer>;
  var start := 0;

  for var i := 0 to s.Length - 1 do
  begin
    var c := s[i + 1];
    if chars.ContainsKey(c) then
      chars[c] += 1
    else
      chars[c] := 1;

    while chars.Count > 3 do
    begin
      var startChar := s[start + 1];
      chars[startChar] -= 1;
      if chars[startChar] = 0 then
        chars.Remove(startChar);
      start += 1;
    end;

    maxLen := max(maxLen, i - start + 1);
  end;

  Result := maxLen;
end;

function ValidParenthesesString(s: string): boolean;
begin
