  if (peak = 0) or (peak = arr.Length - 1) then
  begin
    Result := false;
    exit;
  end;

  for var i := peak to arr.Length - 2 do
    if arr[i] <= arr[i + 1] then
    begin
      Result := false;
      exit;
    end;

  Result := true;
end;

