function SmallestNSumCubes(m: integer): integer;
begin
  var n := 1;
  var cubeSum := 0;

  while cubeSum < m do
  begin
    cubeSum := cubeSum + n * n * n;
    n += 1;
  end;

  if cubeSum = m then
    Result := n - 1
  else
    Result := -1;
end;

function CalculateExtendedGcd(a, b: integer): (integer, integer, integer);
begin
  if a = 0 then
    Result := (b, 0, 1)
  else
  begin
    var (gcd, x1, y1) := CalculateExtendedGcd(b mod a, a);
    var x := y1 - (b div a) * x1;
    var y := x1;
    Result := (gcd, x, y);
  end;
end;

function FindMaxSlidingWindow(nums: array of integer; k: integer): array of integer;
begin
  if nums.Length = 0 then
  begin
    Result := new integer[0];
    exit;
  end;

  var window := new List<integer>;
  var maxElements := new List<integer>;

  for var i := 0 to k - 1 do
  begin
    while (window.Count > 0) and (nums[i] >= nums[window.Last]) do
      window.RemoveAt(window.Count - 1);
    window.Add(i);
  end;

  maxElements.Add(nums[window.First]);

  for var i := k to nums.Length - 1 do
  begin
    if window.First <= i - k then
      window.RemoveAt(0);

    while (window.Count > 0) and (nums[i] >= nums[window.Last]) do
      window.RemoveAt(window.Count - 1);
    window.Add(i);
    maxElements.Add(nums[window.First]);
  end;

  Result := maxElements.ToArray;
end;

function IsInterleave(s1, s2, s3: string): boolean;
begin
  if s1.Length + s2.Length <> s3.Length then
  begin
    Result := false;
    exit;
  end;

  var queue := new Queue<(integer, integer)>;
  queue.Enqueue((0, 0));
  var visited := new HashSet<(integer, integer)>;

  while queue.Count > 0 do
  begin
    var (x, y) := queue.Dequeue;
    if (x = s1.Length) and (y = s2.Length) then
    begin
      Result := true;
      exit;
    end;

    if (x < s1.Length) and (s1[x + 1] = s3[x + y + 1]) and not visited.Contains((x + 1, y)) then
    begin
      queue.Enqueue((x + 1, y));
      visited.Add((x + 1, y));
    end;

    if (y < s2.Length) and (s2[y + 1] = s3[x + y + 1]) and not visited.Contains((x, y + 1)) then
    begin
      queue.Enqueue((x, y + 1));
      visited.Add((x, y + 1));
    end;
  end;

  Result := false;
end;

function UppercaseStrings(strings: array of string): array of string;
begin
  var uppercased := new List<string>;
  foreach var s in strings do
    uppercased.Add(s.ToUpper);
  Result := uppercased.ToArray;
end;

function SumOfDigits(num: integer): integer;
begin
  var sum := 0;
  var n := num;
  while n > 0 do
  begin
    sum := sum + (n mod 10);
    n := n div 10;
  end;
  Result := sum;
end;

type TreeNode = class
  val: integer;
  left: TreeNode;
  right: TreeNode;
  constructor Create(v: integer; l: TreeNode := nil; r: TreeNode := nil);
  begin
    val := v;
    left := l;
    right := r;
  end;
end;

function FindLCA(root: TreeNode; val1, val2: integer): integer?;
begin
  if root = nil then
  begin
    Result := nil;
    exit;
  end;

  if (root.val = val1) or (root.val = val2) then
  begin
    Result := root.val;
    exit;
  end;

  var leftLCA := FindLCA(root.left, val1, val2);
  var rightLCA := FindLCA(root.right, val1, val2);

  if (leftLCA <> nil) and (rightLCA <> nil) then
    Result := root.val
  else if leftLCA <> nil then
    Result := leftLCA
  else
    Result := rightLCA;
end;

function DiffDays(date1, date2: string): integer;
begin
  var format := 'yyyy-MM-dd';
  var d1 := DateTime.ParseExact(date1, format, nil);
  var d2 := DateTime.ParseExact(date2, format, nil);
  var delta := d2 - d1;
  Result := Abs(delta.Days);
end;

function CountPalindromeSubstrings(s: string): integer;
begin
  var n := s.Length;
  var count := 0;

  for var i := 0 to n - 1 do
  begin
    // odd length palindromes
    var l := i;
    var r := i;
    while (l >= 0) and (r < n) and (s[l + 1] = s[r + 1]) do
    begin
      count += 1;
      l -= 1;
      r += 1;
    end;

    // even length palindromes
    l := i;
    r := i + 1;
    while (l >= 0) and (r < n) and (s[l + 1] = s[r + 1]) do
    begin
      count += 1;
      l -= 1;
      r += 1;
    end;
  end;

  Result := count;
end;

function FindClosest(sortedList: array of integer; target: integer): integer;
begin
  if sortedList.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var left := 0;
  var right := sortedList.Length - 1;

  while left < right - 1 do
  begin
    var mid := (left + right) div 2;
    if sortedList[mid] = target then
    begin
      Result := sortedList[mid];
      exit;
    end
    else if sortedList[mid] < target then
      left := mid
    else
      right := mid;
  end;

  if Abs(sortedList[left] - target) <= Abs(sortedList[right] - target) then
    Result := sortedList[left]
  else
    Result := sortedList[right];
end;

function PartitionList(nums: array of integer; x: integer): array of integer;
begin
  var less := new List<integer>;
  var greater := new List<integer>;

  foreach var num in nums do
    if num < x then
      less.Add(num)
    else
      greater.Add(num);

  less.AddRange(greater);
  Result := less.ToArray;
end;

function CanBeNonDecreasing(nums: array of integer): boolean;
begin
  var modified := false;
  var arr := nums.Copy;

  for var i := 1 to arr.Length - 1 do
  begin
    if arr[i] < arr[i - 1] then
    begin
      if modified then
      begin
        Result := false;
        exit;
      end;

      if (i = 1) or (arr[i] >= arr[i - 2]) then
        arr[i - 1] := arr[i]
      else if (i = arr.Length - 1) or (arr[i + 1] >= arr[i - 1]) then
        arr[i] := arr[i - 1]
      else
      begin
        Result := false;
        exit;
      end;

      modified := true;
    end;
  end;

  Result := true;
end;

function EncodeMessage(plainText: string; shift: integer): string;
begin
  var cipherText := new StringBuilder;

  foreach var ch in plainText do
  begin
    if char.IsLetter(ch) then
    begin
      var asciiOffset := if char.IsLower(ch) then Ord('a') else Ord('A');
      var shifted := (Ord(ch) - asciiOffset + shift) mod 26 + asciiOffset;
      cipherText.Append(char(shifted));
    end
    else
      cipherText.Append(ch);
  end;

  Result := cipherText.ToString;
end;

function SumNested(lst: array of object): integer;
begin
  var total := 0;

  foreach var item in lst do
  begin
    if item is array of object then
      total += SumNested(item as array of object)
    else if item is integer then
      total += integer(item);
  end;

  Result := total;
end;

function FindFarthestPoint(points: array of (integer, integer, integer)): (integer, integer, integer);
begin
  var farthest: (integer, integer, integer) := (0, 0, 0);
  var maxDistance := 0.0;

  foreach var point in points do
  begin
    var distance := Sqrt(point.Item1 * point.Item1 + point.Item2 * point.Item2 + point.Item3 * point.Item3);
    if distance > maxDistance then
    begin
      maxDistance := distance;
      farthest := point;
    end;
  end;

  Result := farthest;
end;

function AssignmentSlots(N, K: integer; arr: array of (integer, integer)): integer;
begin
  var sorted := arr.OrderBy(x -> x.Item2).ToArray;
  var completed := 0;
  var kTime := ArrGen(K, i -> true);

  foreach var t in sorted do
  begin
    for var i := t.Item1 - 1 to t.Item2 - 1 do
    begin
      if kTime[i] then
      begin
        kTime[i] := false;
        completed += 1;
        break;
      end;
    end;
  end;

  Result := completed;
end;

function Division(dividend, divisor: integer): integer;
begin
  if divisor = 0 then
    raise new System.DivideByZeroException('Cannot divide by zero');

  if (dividend = -2147483648) and (divisor = -1) then
  begin
    Result := 2147483647;
    exit;
  end;

  var a := Abs(dividend);
  var b := Abs(divisor);
  var quotient := 0;

  while a >= b do
  begin
    var temp := b;
    var multiple := 1;
    while temp <= a do
    begin
      a := a - temp;
      quotient := quotient + multiple;
      temp := temp shl 1;
      multiple := multiple shl 1;
    end;
  end;

  if (dividend > 0) = (divisor > 0) then
    Result := quotient
  else
    Result := -quotient;
end;

function FindMaxSumSubarray(arr: array of integer; k: integer): integer;
begin
  if arr.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var maxSum := 0;
  var currentSum := 0;

  for var i := 0 to k - 1 do
    currentSum += arr[i];
  maxSum := currentSum;

  for var i := k to arr.Length - 1 do
  begin
    currentSum := currentSum + arr[i] - arr[i - k];
    if currentSum > maxSum then
      maxSum := currentSum;
  end;

  Result := maxSum;
end;

function IsPerfectPower(n: integer): boolean;
begin
  if n < 2 then
  begin
    Result := false;
    exit;
  end;

  for var base := 2 to Trunc(Sqrt(n)) do
  begin
    var pow := 2;
    var val := Round(Power(base, pow));
    while val <= n do
    begin
      if val = n then
      begin
        Result := true;
        exit;
      end;
      pow += 1;
      val := Round(Power(base, pow));
    end;
  end;

  Result := false;
end;

function CheckSymmetric(matrix: array[,] of integer): boolean;
begin
  var n := matrix.GetLength(0);
  if n = 0 then
  begin
    Result := false;
    exit;
  end;

  for var i := 0 to n - 1 do
    for var j := 0 to n - 1 do
      if matrix[i, j] <> matrix[j, i] then
      begin
        Result := false;
        exit;
      end;

  Result := true;
end;

function CountOddEnds(nums: array of integer): integer;
  function IsOddDigit(n: integer): boolean := n mod 2 <> 0;

  function FirstDigit(n: integer): integer;
  begin
    var num := n;
    while num >= 10 do
      num := num div 10;
    Result := num;
  end;
begin
  var count := 0;

  foreach var num in nums do
    if (num > 10) and IsOddDigit(FirstDigit(num)) and IsOddDigit(num mod 10) then
      count += 1;

  Result := count;
end;

function PrimeFactorsProduct(n: integer): integer;
begin
  var i := 2;
  var product := 1;
  var seen := new HashSet<integer>;
  var num := n;

  while i * i <= num do
  begin
    if num mod i = 0 then
    begin
      num := num div i;
      if not seen.Contains(i) then
      begin
        product := product * i;
        seen.Add(i);
      end;
    end
    else
      i += 1;
  end;

  if (num > 1) and not seen.Contains(num) then
    product := product * num;

  Result := product;
end;

var dpMatrix: array[,] of integer;
var matrixGlobal: array[,] of integer;
var numRowsGlobal: integer;
var numColsGlobal: integer;
var directionsLongest := |(0, 1), (1, 0), (0, -1), (-1, 0)|;

function DFSLongest(i, j: integer): integer;
begin
  if dpMatrix[i, j] <> 0 then
    exit(dpMatrix[i, j]);

  var maxLen := 1;

  foreach var dir in directionsLongest do
  begin
    var ni := i + dir.Item1;
    var nj := j + dir.Item2;
    if (ni >= 0) and (ni < numRowsGlobal) and (nj >= 0) and (nj < numColsGlobal) and 
       (matrixGlobal[ni, nj] > matrixGlobal[i, j]) then
      maxLen := max(maxLen, 1 + DFSLongest(ni, nj));
  end;

  dpMatrix[i, j] := maxLen;
  Result := maxLen;
end;

function LongestPathInMatrix(matrix: array[,] of integer): integer;
begin
  if (matrix.GetLength(0) = 0) or (matrix.GetLength(1) = 0) then
  begin
    Result := 0;
    exit;
  end;

  numRowsGlobal := matrix.GetLength(0);
  numColsGlobal := matrix.GetLength(1);
  matrixGlobal := matrix;
  dpMatrix := new integer[numRowsGlobal, numColsGlobal];

  var longest := 0;
  for var i := 0 to numRowsGlobal - 1 do
    for var j := 0 to numColsGlobal - 1 do
      longest := max(longest, DFSLongest(i, j));

  Result := longest;
end;

