function IsBalanced(root: TreeNode): boolean;
  function CheckHeight(node: TreeNode): integer;
  begin
    if node = nil then
    begin
      Result := 0;
      exit;
    end;

    var leftHeight := CheckHeight(node.left);
    if leftHeight = -1 then
    begin
      Result := -1;
      exit;
    end;

    var rightHeight := CheckHeight(node.right);
    if rightHeight = -1 then
    begin
      Result := -1;
      exit;
    end;

    if Abs(leftHeight - rightHeight) > 1 then
    begin
      Result := -1;
      exit;
    end;

    Result := max(leftHeight, rightHeight) + 1;
  end;
begin
  Result := CheckHeight(root) <> -1;
end;
